      setTimeout(() => closeProductModal(), 1000);
    } catch (error) {
        setMessage({ type: 'error', text: 'Erro ao salvar.' });
    } finally {
        setIsSubmitting(false);
    }
  };

  // Render logic remains identical to previous, just injecting the CustomizationGroupEditor in the modal
  return (
