import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Product, ProductOption, SelectedCustomization, CustomizationGroup, CustomizationOption } from '../types';
import { ArrowLeftIcon, PlusIcon, MinusIcon, ShoppingBagIcon, ExpandIcon, XIcon, ChevronLeftIcon, ChevronRightIcon, CheckCircleIcon } from './IconComponents';

interface ProductDetailModalProps {
  product: Product | null;
  onClose: () => void;
  onAddToCart: (product: Product, quantity: number, observations?: string, selectedOption?: ProductOption, selectedCustomizations?: SelectedCustomization[]) => void;
}

const ProductDetailModal: React.FC<ProductDetailModalProps> = ({ product, onClose, onAddToCart }) => {
  const [quantity, setQuantity] = useState(1);
  const [observations, setObservations] = useState('');
  const [isImageFullscreen, setIsImageFullscreen] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [selectedOption, setSelectedOption] = useState<ProductOption | null>(null);

  // Estado para armazenar as seleções de cada grupo
  const [customSelections, setCustomSelections] = useState<Record<string, Record<string, number>>>({});

  useEffect(() => {
    if (product) {
      setQuantity(1);
      setObservations('');
      setIsImageFullscreen(false);
      setCurrentImageIndex(0);
      setCustomSelections({});

      if (product.options && product.options.length > 0) {
          setSelectedOption(product.options[0]);
      } else {
          setSelectedOption(null);
      }
    }
  }, [product]);

  const handleImageNavigation = useCallback((direction: 'next' | 'prev') => {
    if (!product) return;
    const newIndex = direction === 'next'
      ? (currentImageIndex + 1) % product.imageUrls.length
      : (currentImageIndex - 1 + product.imageUrls.length) % product.imageUrls.length;
    setCurrentImageIndex(newIndex);
  }, [currentImageIndex, product]);

  const formatPrice = (price: number) => {
    return price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  // Lógica de cálculo de extras e validação
  const { extraTotal, isAllGroupsValid, formattedCustomizations } = useMemo(() => {
    let total = 0;
    let allValid = true;
    const result: SelectedCustomization[] = [];

    if (!product?.customizationGroups) return { extraTotal: 0, isAllGroupsValid: true, formattedCustomizations: [] };

    for (const group of product.customizationGroups) {
      const groupSelections = (customSelections[group.id] || {}) as Record<string, number>;
      // Fix: Explicitly type reducer arguments to avoid unknown errors
      const totalInGroup = Object.values(groupSelections).reduce((a: number, b: number) => a + b, 0);

      // Validação de Min/Max
      if (totalInGroup < group.min || totalInGroup > group.max) {
        allValid = false;
      }

      const selectedItems: { name: string; quantity: number; priceExtra: number }[] = [];
      for (const [optName, optQty] of Object.entries(groupSelections)) {
        if (optQty > 0) {
          const opt = group.options.find(o => o.name === optName);
          if (opt) {
            // Fix: Cast optQty as number for arithmetic operation
            total += (opt.priceExtra * (optQty as number));
            selectedItems.push({
              name: opt.name,
              quantity: optQty as number,
              priceExtra: opt.priceExtra
            });
          }
        }
      }

      if (selectedItems.length > 0) {
        result.push({
          groupName: group.name,
          items: selectedItems
        });
      }
    }

    return { extraTotal: total, isAllGroupsValid: allValid, formattedCustomizations: result };
  }, [product, customSelections]);

  const handleCustomOptionChange = (group: CustomizationGroup, option: CustomizationOption, delta: number) => {
    setCustomSelections(prev => {
      const groupSelections = { ...(prev[group.id] || {}) } as Record<string, number>;
      const currentQty = groupSelections[option.name] || 0;
      // Fix: Explicitly type reducer arguments
      const totalInGroup = Object.values(groupSelections).reduce((a: number, b: number) => a + b, 0);

      // Regras de seleção única (RADIO behavior)
      if (group.type === 'single') {
        if (delta > 0) {
            return { ...prev, [group.id]: { [option.name]: 1 } };
        } else {
            return { ...prev, [group.id]: {} };
        }
      }

      // Regras de seleção múltipla (CHECKBOX / COUNTER behavior)
      const newQty = Math.max(0, currentQty + delta);
      if (delta > 0 && totalInGroup >= group.max) return prev; // Bloqueia se atingiu o máximo do grupo

      return {
        ...prev,
        [group.id]: {
          ...groupSelections,
          [option.name]: newQty
        }
      };
    });
  };

  const handleAddToCartClick = () => {
    if (!product) return;

    if (product.options && product.options.length > 0 && !selectedOption) {
        alert("Por favor, selecione uma opção.");
        return;
    }

    if (!isAllGroupsValid) {
        alert("Por favor, complete as seleções obrigatórias.");
        return;
    }

    onAddToCart(product, quantity, observations, selectedOption || undefined, formattedCustomizations);
  };

  if (!product) return null;

  const basePrice = selectedOption ? selectedOption.price : product.price;
  const unitPrice = basePrice + extraTotal;
  const total = unitPrice * quantity;
  const isSoldOut = product.inventoryEnabled && (product.inventoryQuantity || 0) <= 0;

  return (
    <>
      <div className="fixed inset-0 z-50 bg-white flex flex-col animate-slide-in-up">
        <style>{`.animate-slide-in-up { animation: slideInUp 0.3s ease-out; } @keyframes slideInUp { from { transform: translateY(100%); } to { transform: translateY(0); } }`}</style>

        <div className="flex-1 overflow-y-auto pb-32"> 
          <div className="max-w-2xl mx-auto w-full">
            {/* Cabeçalho com Imagem */}
            {product.imageUrls?.length > 0 ? (
              <div className="relative group w-full bg-gray-100">
                  <div className="aspect-square sm:aspect-video w-full relative overflow-hidden">
                     <img src={product.imageUrls[currentImageIndex]} alt={product.name} className={`w-full h-full object-cover ${isSoldOut ? 'grayscale' : ''}`} />
                  </div>
                  <button onClick={onClose} className="absolute top-4 left-4 p-2 bg-white/70 backdrop-blur-sm rounded-full text-brand-text shadow-sm"><ArrowLeftIcon className="w-6 h-6"/></button>
              </div>
            ) : (
               <div className="p-4 border-b flex items-center sticky top-0 bg-white z-20">
                  <button onClick={onClose} className="p-2 -ml-2 rounded-full text-brand-text"><ArrowLeftIcon className="w-6 h-6"/></button>
                  <h1 className="ml-2 text-lg font-bold text-brand-text truncate">{product.name}</h1>
              </div>
            )}

            <div className="p-6 space-y-8">
                <div>
                    <h1 className="text-2xl font-bold text-brand-text">{product.name}</h1>
                    <p className="text-brand-text-light mt-2 text-sm leading-relaxed">{product.description}</p>
                </div>

                {/* Seção de Variações (Tamanhos/Opções base) */}
                {product.options && product.options.length > 0 && (
                    <div className="space-y-4">
                        <h3 className="text-base font-bold text-brand-text border-l-4 border-brand-primary pl-3">Escolha o Tamanho</h3>
                        <div className="grid grid-cols-1 gap-2">
                            {product.options.map((opt, idx) => (
                                <button 
                                    key={idx}
                                    onClick={() => setSelectedOption(opt)}
                                    className={`flex items-center justify-between p-4 rounded-xl border transition-all ${selectedOption?.name === opt.name ? 'border-brand-primary bg-brand-secondary/20 ring-1 ring-brand-primary' : 'border-gray-100 hover:bg-gray-50'}`}
                                >
                                    <span className="font-bold text-gray-700">{opt.name}</span>
                                    <span className="font-bold text-brand-primary">{formatPrice(opt.price)}</span>
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* Seção de Customizações Dinâmicas */}
                {product.customizationGroups?.map((group) => {
                    const groupSelections = (customSelections[group.id] || {}) as Record<string, number>;
                    // Fix: Explicitly type reducer arguments
                    const totalInGroup = Object.values(groupSelections).reduce((a: number, b: number) => a + b, 0);
                    const isGroupValid = totalInGroup >= group.min && totalInGroup <= group.max;

                    return (
                        <div key={group.id} className="space-y-4 pt-4 border-t border-gray-100">
                            <div className="flex justify-between items-center">
                                <div>
                                    <h3 className="text-base font-bold text-brand-text">{group.name}</h3>
                                    <p className="text-xs text-gray-400">
                                        {group.min === group.max ? `Escolha exatamente ${group.min}` : 
                                         group.min > 0 ? `Escolha de ${group.min} a ${group.max}` : `Opcional (máx ${group.max})`}
                                    </p>
                                </div>
                                {!isGroupValid && (
                                    <span className="text-[10px] font-bold bg-amber-100 text-amber-700 px-2 py-0.5 rounded uppercase">Obrigatório</span>
                                )}
                                {isGroupValid && group.min > 0 && (
                                    <CheckCircleIcon className="w-5 h-5 text-green-500" />
                                )}
                            </div>

                            <div className="space-y-3">
                                {group.options.map((opt) => {
                                    const qty = groupSelections[opt.name] || 0;
                                    const isSelected = qty > 0;

                                    return (
                                        <div key={opt.name} className={`flex items-center justify-between p-3 rounded-xl border transition-all ${isSelected ? 'border-brand-primary/50 bg-brand-secondary/10' : 'border-gray-50'}`}>
                                            <div className="flex-grow min-w-0 pr-4">
                                                <p className="text-sm font-bold text-gray-700 truncate">{opt.name}</p>
                                                {opt.priceExtra > 0 && <p className="text-xs text-brand-accent font-bold">+{formatPrice(opt.priceExtra)}</p>}
                                            </div>

                                            <div className="flex items-center bg-white rounded-lg shadow-sm border border-gray-100">
                                                <button 
                                                    onClick={() => handleCustomOptionChange(group, opt, -1)}
                                                    className={`p-2 transition-opacity ${qty === 0 ? 'opacity-20' : 'opacity-100'}`}
                                                >
                                                    <MinusIcon className="w-4 h-4" />
                                                </button>
                                                <span className={`px-2 text-sm font-black w-8 text-center ${qty > 0 ? 'text-brand-primary' : 'text-gray-300'}`}>{qty}</span>
                                                <button 
                                                    onClick={() => handleCustomOptionChange(group, opt, 1)}
                                                    className={`p-2 transition-opacity ${totalInGroup >= group.max && group.type !== 'single' ? 'opacity-20' : 'opacity-100'}`}
                                                >
                                                    <PlusIcon className="w-4 h-4" />
                                                </button>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    );
                })}

                <div className="pt-4 border-t border-gray-100">
                    <label className="block text-sm font-bold text-brand-text mb-2">Alguma observação?</label>
                    <textarea 
                        value={observations}
                        onChange={(e) => setObservations(e.target.value)}
                        rows={3}
                        placeholder="Ex: Sem cebola, trocar laço para azul..."
                        className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-brand-primary outline-none"
                    />
                </div>
            </div>
          </div>
        </div>

        {/* Rodapé Fixo */}
        {!isSoldOut && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 p-4 shadow-[0_-4px_10px_rgba(0,0,0,0.05)] z-30">
                <div className="max-w-2xl mx-auto w-full flex items-center justify-between gap-4">
                    <div className="flex items-center bg-gray-100 rounded-full">
                        <button onClick={() => setQuantity(q => Math.max(1, q - 1))} className="p-3"><MinusIcon className="w-5 h-5" /></button>
                        <span className="px-4 font-black text-lg">{quantity}</span>
                        <button onClick={() => setQuantity(q => q + 1)} className="p-3"><PlusIcon className="w-5 h-5" /></button>
                    </div>

                    <button 
                      onClick={handleAddToCartClick}
                      disabled={!isAllGroupsValid}
                      className="flex-grow bg-brand-primary text-white font-bold py-4 px-6 rounded-xl flex items-center justify-between disabled:opacity-50 transition-all active:scale-95 shadow-lg shadow-brand-primary/20"
                    >
                        <div className="flex items-center gap-2">
                            <ShoppingBagIcon className="w-5 h-5" />
                            <span>Adicionar</span>
                        </div>
                        <span className="font-black text-lg">{formatPrice(total)}</span>
                    </button>
                </div>
            </div>
        )}
      </div>
    </>
  );
};

