              <ShoppingBagIcon className="w-5 h-5" />
              Sua Sacola
            </h2>
            <button onClick={onClose} className="p-2 rounded-full hover:bg-gray-100 transition-colors">
              <XIcon className="w-6 h-6 text-gray-400" />
            </button>
          </header>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar">
            {cartItems.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-center space-y-4">
                <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center">
                  <ShoppingBagIcon className="w-10 h-10 text-gray-200" />
                </div>
                <div>
                  <p className="text-gray-900 font-bold">Sua sacola está vazia</p>
                  <p className="text-gray-400 text-sm">Adicione delícias para continuar</p>
                </div>
                <button onClick={onClose} className="text-brand-primary font-bold hover:underline">
                  Voltar ao cardápio
                </button>
              </div>
            ) : (
              cartItems.map((item, index) => (
                <div key={`${item.id}-${item.selectedOption?.name || index}`} className="flex items-start bg-white p-3 rounded-xl border border-gray-100 gap-4 shadow-sm">
                  {item.imageUrls?.length > 0 && (
                    <img src={item.imageUrls[0]} alt={item.name} className="w-16 h-16 object-cover rounded-lg" />
