                    <div className="flex justify-between items-start">
                      <h3 className="font-bold text-brand-text text-sm truncate">{item.name}</h3>
                      <button onClick={() => onRemoveItem(item.id, item.selectedOption?.name)} className="p-1 text-gray-300 hover:text-red-500">
                        <TrashIcon className="w-4 h-4" />
                      </button>
                    </div>

                    {item.selectedOption && (
                      <p className="text-[10px] text-gray-400 font-black uppercase mt-0.5">{item.selectedOption.name}</p>
                    )}

                    {/* Lista de Customizações */}
                    {item.selectedCustomizations && item.selectedCustomizations.length > 0 && (
                      <div className="mt-1.5 space-y-1">
                        {item.selectedCustomizations.map((group, gIdx) => (
                          <div key={gIdx}>
                            <p className="text-[9px] font-black text-brand-primary uppercase opacity-60 leading-none">{group.groupName}</p>
                            <ul className="text-[10px] text-gray-500 italic mt-0.5 space-y-0.5">
                              {group.items.map((opt, oIdx) => (
                                <li key={oIdx} className="leading-tight">+ {opt.quantity}x {opt.name}</li>
                              ))}
                            </ul>
                          </div>
                        ))}
                      </div>
                    )}

                    <div className="flex justify-between items-center mt-3">
                      <p className="text-brand-primary font-black text-sm">{formatPrice(item.price)}</p>
                      <div className="flex items-center bg-gray-50 rounded-lg border border-gray-100">
                        <button 
                          onClick={() => onUpdateQuantity(item.id, item.quantity - 1, item.selectedOption?.name)}
                          className="p-1.5 text-gray-500 hover:text-brand-primary"
                        >
                          <MinusIcon className="w-3 h-3" />
                        </button>
                        <span className="px-2 font-black text-xs min-w-[24px] text-center">{item.quantity}</span>
                        <button 
                          onClick={() => onUpdateQuantity(item.id, item.quantity + 1, item.selectedOption?.name)}
                          className="p-1.5 text-gray-500 hover:text-brand-primary"
                        >
                          <PlusIcon className="w-3 h-3" />
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>

          {cartItems.length > 0 && (
            <footer className="p-4 border-t bg-gray-50 space-y-4">
              <div className="flex justify-between items-center text-brand-text">
                <span className="font-medium text-sm">Subtotal</span>
                <span className="font-black text-lg">{formatPrice(subtotal)}</span>
              </div>
              <button
                onClick={onCheckout}
                className="w-full bg-brand-primary text-white font-black py-4 rounded-xl shadow-lg hover:bg-brand-primary-dark transition-all active:scale-95 flex items-center justify-center gap-2"
              >
                Continuar para entrega
              </button>
            </footer>
          )}
        </div>
      </div>
    </>
  );
};

