import React, { useState, useEffect, useRef, useMemo } from 'react';
import type { Product, ProductOption, CategoryMetadata, CustomizationGroup, CustomizationOption } from '../types';
import { TrashIcon, SearchIcon, DragHandleIcon, CopyIcon, PlusIcon, ChevronRightIcon, XIcon as CloseIcon } from './IconComponents';

const CustomizationGroupEditor: React.FC<{
    groups: CustomizationGroup[];
    onChange: (groups: CustomizationGroup[]) => void;
}> = ({ groups, onChange }) => {
    const addGroup = () => {
        const newGroup: CustomizationGroup = {
            id: `group-${Date.now()}`,
            name: '',
            min: 1,
            max: 1,
            type: 'single',
            options: []
        };
        onChange([...groups, newGroup]);
    };

    const updateGroup = (id: string, data: Partial<CustomizationGroup>) => {
        onChange(groups.map(g => g.id === id ? { ...g, ...data } : g));
    };

    const removeGroup = (id: string) => {
        onChange(groups.filter(g => g.id !== id));
    };

    const addOptionToGroup = (groupId: string) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                return {
                    ...g,
                    options: [...g.options, { name: '', priceExtra: 0 }]
                };
            }
            return g;
        }));
    };

    const updateOptionInGroup = (groupId: string, optIndex: number, data: Partial<CustomizationOption>) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                const newOpts = [...g.options];
                newOpts[optIndex] = { ...newOpts[optIndex], ...data };
                return { ...g, options: newOpts };
            }
            return g;
        }));
    };

    const removeOptionFromGroup = (groupId: string, optIndex: number) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                return { ...g, options: g.options.filter((_, i) => i !== optIndex) };
            }
            return g;
        }));
    };

    return (
        <div className="space-y-6 mt-4 border-t pt-6">
            <div className="flex items-center justify-between">
                <div>
                    <h3 className="text-sm font-black text-gray-700 uppercase tracking-widest">Personalizações & Adicionais</h3>
                    <p className="text-[10px] text-gray-400">Monte opções como "Massa", "Sabores da Caixa" ou "Extras".</p>
                </div>
                <button type="button" onClick={addGroup} className="text-xs font-bold text-brand-primary bg-brand-secondary/30 px-3 py-1.5 rounded-full hover:bg-brand-primary hover:text-white transition-all">
                    + Adicionar Grupo
                </button>
            </div>

            <div className="space-y-4">
                {groups.map((group) => (
                    <div key={group.id} className="bg-gray-50 p-4 rounded-xl border border-gray-200 relative">
                        <button onClick={() => removeGroup(group.id)} className="absolute top-3 right-3 text-gray-300 hover:text-red-500 transition-colors">
                            <TrashIcon className="w-5 h-5"/>
                        </button>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                            <div>
                                <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Título do Grupo</label>
                                <input 
                                    type="text" 
                                    value={group.name} 
                                    onChange={e => updateGroup(group.id, { name: e.target.value })}
                                    placeholder="Ex: Escolha a Massa"
                                    className="w-full px-3 py-2 border rounded-lg text-sm outline-none focus:ring-2 focus:ring-brand-primary bg-white shadow-sm"
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Mínimo</label>
                                    <input type="number" min="0" value={group.min} onChange={e => updateGroup(group.id, { min: parseInt(e.target.value) })} className="w-full px-3 py-2 border rounded-lg text-sm bg-white shadow-sm"/>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Máximo</label>
                                    <input type="number" min="1" value={group.max} onChange={e => updateGroup(group.id, { max: parseInt(e.target.value), type: parseInt(e.target.value) > 1 ? 'counter' : 'single' })} className="w-full px-3 py-2 border rounded-lg text-sm bg-white shadow-sm"/>
                                </div>
                            </div>
                        </div>

                        <div className="space-y-2 mt-4">
                            <p className="text-[10px] font-black text-gray-400 uppercase mb-2">Opções Disponíveis</p>
                            <div className="space-y-2">
                                {group.options.map((opt, idx) => (
                                    <div key={idx} className="flex gap-2 items-center bg-white p-2 rounded-lg border border-gray-100 shadow-sm">
                                        <input 
                                            type="text" 
                                            value={opt.name} 
                                            onChange={e => updateOptionInGroup(group.id, idx, { name: e.target.value })} 
                                            placeholder="Nome (Ex: Chocolate)"
                                            className="flex-grow px-2 py-1 text-sm border-b border-transparent focus:border-brand-primary outline-none"
                                        />
                                        <div className="flex items-center gap-1 bg-gray-50 px-2 py-1 rounded">
                                            <span className="text-[10px] text-gray-400 font-bold">R$</span>
                                            <input 
                                                type="number" 
                                                step="0.01"
                                                value={opt.priceExtra} 
                                                onChange={e => updateOptionInGroup(group.id, idx, { priceExtra: parseFloat(e.target.value) })} 
                                                className="w-16 bg-transparent text-sm font-bold text-brand-primary outline-none text-right"
                                                placeholder="0,00"
                                            />
                                        </div>
                                        <button type="button" onClick={() => removeOptionFromGroup(group.id, idx)} className="p-1.5 text-gray-300 hover:text-red-500 transition-colors">
                                            <TrashIcon className="w-4 h-4"/>
                                        </button>
                                    </div>
                                ))}
                            </div>
                            <button 
                                type="button" 
                                onClick={() => addOptionToGroup(group.id)} 
                                className="w-full mt-2 py-2 border-2 border-dashed border-gray-200 rounded-lg text-[10px] text-gray-400 font-bold uppercase tracking-wider hover:border-brand-primary hover:text-brand-primary transition-all flex items-center justify-center gap-1"
                            >
                                <PlusIcon className="w-3 h-3"/>
                                Adicionar Opção
                            </button>
                        </div>
                    </div>
                ))}
            </div>

            {groups.length === 0 && (
                <div className="text-center py-8 bg-gray-50 rounded-xl border border-dashed border-gray-200">
                    <p className="text-xs text-gray-400 font-medium italic">Nenhuma personalização cadastrada.</p>
                </div>
            )}
        </div>
    );
};

interface ProductsViewProps {
  products: Product[];
  categories: CategoryMetadata[];
  onAddProduct: (productData: Omit<Product, 'id'>) => Promise<void>;
  onUpdateProduct: (productData: Product) => Promise<void>;
  onDeleteProduct: (productId: string) => Promise<void>;
  onAddCategory: (categoryName: string) => Promise<void>;
  onDeleteCategory: (categoryName: string) => Promise<void>;
  onUpdateCategoryOrder: (newOrder: CategoryMetadata[]) => Promise<void>;
  onToggleCategoriesArchive: (categoryNames: string[], archive: boolean) => Promise<void>;
}

const ProductsView: React.FC<ProductsViewProps> = ({ 
    products, 
    categories, 
    onAddProduct, 
    onUpdateProduct, 
    onDeleteProduct, 
    onAddCategory, 
    onDeleteCategory, 
    onUpdateCategoryOrder,
    onToggleCategoriesArchive
}) => {
  const initialFormState = {
    name: '',
    description: '',
    price: '',
    originalPrice: '',
    promotionalTag: '',
    category: '',
    imageUrls: '',
    leadTimeDays: '0',
    inventoryEnabled: false,
    inventoryQuantity: '0'
  };

  const [productForm, setProductForm] = useState(initialFormState);
  const [productOptions, setProductOptions] = useState<ProductOption[]>([]);
  const [customizationGroups, setCustomizationGroups] = useState<CustomizationGroup[]>([]);

  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const closeProductModal = () => {
    setIsProductModalOpen(false);
    setEditingProduct(null);
    setProductForm(initialFormState);
    setProductOptions([]);
    setCustomizationGroups([]);
    setMessage(null);
  };

  const handleEditClick = (product: Product) => {
    setEditingProduct(product);
    setProductForm({
        name: product.name,
        description: product.description,
        price: String(product.price),
        originalPrice: product.originalPrice ? String(product.originalPrice) : '',
        promotionalTag: product.promotionalTag || '',
        category: product.category,
        imageUrls: product.imageUrls ? product.imageUrls.join('\n') : '',
        leadTimeDays: String(product.leadTimeDays || 0),
        inventoryEnabled: !!product.inventoryEnabled,
        inventoryQuantity: String(product.inventoryQuantity || 0)
    });
    setProductOptions(product.options || []);
    setCustomizationGroups(product.customizationGroups || []);
    setIsProductModalOpen(true);
  };

  const handleProductSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    setIsSubmitting(true);
    const imageUrlsArray = productForm.imageUrls.split('\n').map(url => url.trim()).filter(url => url);

    try {
      let effectivePrice = parseFloat(productForm.price);
      if (productOptions.length > 0) {
          effectivePrice = Math.min(...productOptions.map(o => o.price));
      }

      const productData: any = {
        name: productForm.name,
        description: productForm.description,
        price: effectivePrice,
        originalPrice: productForm.originalPrice ? parseFloat(productForm.originalPrice) : 0,
        promotionalTag: productForm.promotionalTag,
        category: productForm.category,
        imageUrls: imageUrlsArray,
        leadTimeDays: parseInt(productForm.leadTimeDays, 10) || 0,
        options: productOptions,
        customizationGroups: customizationGroups,
        inventoryEnabled: productForm.inventoryEnabled,
        inventoryQuantity: parseInt(productForm.inventoryQuantity, 10) || 0,
      };

      if (editingProduct) {
        await onUpdateProduct({ ...productData, id: editingProduct.id });
        setMessage({ type: 'success', text: 'Produto atualizado!' });
      } else {
        await onAddProduct(productData);
        setMessage({ type: 'success', text: 'Produto cadastrado!' });
      }

      setTimeout(() => closeProductModal(), 1500);
    } catch (error) {
        setMessage({ type: 'error', text: 'Erro ao salvar o produto.' });
    } finally {
        setIsSubmitting(false);
    }
  };

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
        p.category.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [products, searchQuery]);

  return (
    <div className="space-y-6">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
            <h2 className="text-xl font-bold text-brand-text">Gerenciar Produtos</h2>
            <button 
                onClick={() => setIsProductModalOpen(true)}
                className="bg-brand-primary text-white px-4 py-2 rounded-lg font-bold shadow-md hover:bg-brand-primary-dark transition-all flex items-center gap-2"
            >
                <PlusIcon className="w-5 h-5" />
                Novo Produto
            </button>
        </div>

        <div className="relative">
            <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input 
                type="text" 
                placeholder="Pesquisar por nome ou categoria..."
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 rounded-xl shadow-sm outline-none focus:ring-2 focus:ring-brand-primary"
            />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredProducts.map(product => (
                <div key={product.id} className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden group hover:shadow-md transition-all">
                    <div className="aspect-video bg-gray-100 relative overflow-hidden">
                        {product.imageUrls?.[0] ? (
                            <img src={product.imageUrls[0]} className="w-full h-full object-cover" alt={product.name} />
                        ) : (
                            <div className="w-full h-full flex items-center justify-center text-gray-300">Sem imagem</div>
                        )}
                        <div className="absolute top-2 right-2 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={() => handleEditClick(product)} className="bg-white p-2 rounded-full shadow-md text-brand-primary hover:bg-brand-primary hover:text-white transition-all">
                                <ChevronRightIcon className="w-4 h-4 rotate-180" />
                            </button>
                        </div>
                    </div>
                    <div className="p-4">
                        <div className="flex justify-between items-start mb-1">
                            <h3 className="font-bold text-brand-text truncate pr-2">{product.name}</h3>
                            <span className="text-xs font-black text-brand-primary">{product.price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                        </div>
                        <p className="text-[10px] font-bold text-gray-400 uppercase mb-3">{product.category}</p>
                        <div className="flex gap-2">
                            <button onClick={() => handleEditClick(product)} className="flex-1 py-2 bg-gray-50 text-gray-600 rounded-lg text-[10px] font-bold uppercase hover:bg-gray-100 transition-colors">Editar</button>
                            <button onClick={async () => { if(confirm("Deseja excluir?")) await onDeleteProduct(product.id); }} className="px-3 py-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-600 hover:text-white transition-colors">
                                <TrashIcon className="w-4 h-4" />
                            </button>
                        </div>
                    </div>
                </div>
            ))}
        </div>

        {/* Modal de Cadastro/Edição */}
        {isProductModalOpen && (
            <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
                <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={closeProductModal}></div>
                <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden animate-slide-in-up">
                    <header className="p-4 border-b flex items-center justify-between bg-gray-50">
                        <h2 className="font-bold text-brand-text text-lg">
                            {editingProduct ? 'Editar Produto' : 'Cadastrar Novo Produto'}
                        </h2>
                        <button onClick={closeProductModal} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
                            <CloseIcon className="w-6 h-6 text-gray-400" />
                        </button>
                    </header>

                    <form onSubmit={handleProductSubmit} className="flex-1 overflow-y-auto p-6 space-y-8 no-scrollbar">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-4">
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Nome do Produto</label>
                                    <input type="text" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} className="w-full px-4 py-2 bg-white border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-brand-primary" required />
                                </div>
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Descrição</label>
                                    <textarea value={productForm.description} onChange={e => setProductForm({...productForm, description: e.target.value})} className="w-full px-4 py-2 bg-white border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-brand-primary" rows={3} />
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Preço Atual</label>
                                        <input type="number" step="0.01" value={productForm.price} onChange={e => setProductForm({...productForm, price: e.target.value})} className="w-full px-4 py-2 bg-white border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-brand-primary" required />
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Preço De (Original)</label>
                                        <input type="number" step="0.01" value={productForm.originalPrice} onChange={e => setProductForm({...productForm, originalPrice: e.target.value})} className="w-full px-4 py-2 bg-white border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-brand-primary" />
                                    </div>
                                </div>
                            </div>

                            <div className="space-y-4">
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Categoria</label>
                                    <select 
                                        value={productForm.category} 
                                        onChange={e => setProductForm({...productForm, category: e.target.value})} 
                                        className="w-full px-4 py-2 bg-white border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-brand-primary"
                                        required
                                    >
                                        <option value="">Selecione...</option>
                                        {categories.map(c => <option key={c.name} value={c.name}>{c.name}</option>)}
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">URLs das Imagens (uma por linha)</label>
                                    <textarea value={productForm.imageUrls} onChange={e => setProductForm({...productForm, imageUrls: e.target.value})} className="w-full px-4 py-2 bg-white border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-brand-primary text-xs" rows={4} placeholder="https://.../img1.jpg" />
                                </div>
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Antecedência Mínima (Dias)</label>
                                    <input type="number" value={productForm.leadTimeDays} onChange={e => setProductForm({...productForm, leadTimeDays: e.target.value})} className="w-full px-4 py-2 bg-white border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-brand-primary" />
                                </div>
                            </div>
                        </div>

                        {/* Editor de Personalização */}
                        <CustomizationGroupEditor 
                           groups={customizationGroups} 
                           onChange={setCustomizationGroups} 
                        />

                        {message && (
                            <div className={`p-4 rounded-xl text-sm font-bold text-center animate-fade-in ${message.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                                {message.text}
                            </div>
                        )}
                    </form>

                    <footer className="p-4 border-t bg-gray-50 flex gap-4">
                        <button onClick={closeProductModal} type="button" className="flex-1 py-3 bg-white border border-gray-200 rounded-xl font-bold text-gray-600 hover:bg-gray-100 transition-colors">Cancelar</button>
                        <button 
                            onClick={handleProductSubmit}
                            disabled={isSubmitting}
                            className="flex-[2] py-3 bg-brand-primary text-white rounded-xl font-black shadow-lg hover:brightness-105 transition-all disabled:opacity-50"
                        >
                            {isSubmitting ? 'Processando...' : (editingProduct ? 'Salvar Alterações' : 'Cadastrar Produto')}
                        </button>
                    </footer>
                </div>
            </div>
        )}
    </div>
  );
}

export default ProductsView;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Product, CartItem, StoreInfoData, Order, ProductOption, CategoryMetadata, SelectedCustomization } from './types';
import { getMenu, getStoreInfo, incrementVisitCount } from './services/menuService';
import Header from './components/Header';
import CategoryTabs from './components/CategoryTabs';
import StoreInfo from './components/StoreInfo';
import ProductCard from './components/ProductCard';
import ProductDetailModal from './components/ProductDetailModal';
import Cart from './components/Cart';
import CartButton from './components/CartButton';
import CheckoutPage from './components/CheckoutPage';
import OrderSuccessPage from './components/OrderSuccessPage';
import StoreInfoModal from './components/StoreInfoModal';
import CategoryMenuModal from './components/CategoryMenuModal';
import OrderTrackingModal from './components/OrderTrackingModal';
import LoginPage from './components/LoginPage';
import AdminPage from './components/AdminPage';
import Footer from './components/Footer';
import { auth } from './firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';

const App: React.FC = () => {
  const [view, setView] = useState<'menu' | 'checkout' | 'order-success' | 'login' | 'admin'>('menu');
  const [storeInfo, setStoreInfo] = useState<StoreInfoData | null>(null);
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<CategoryMetadata[]>([]);
  const [selectedCategory, setSelectedCategory] = useState('Todos');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);
  const [isStoreModalOpen, setIsStoreModalOpen] = useState(false);
  const [isCategoryMenuOpen, setIsCategoryMenuOpen] = useState(false);
  const [isOrderTrackerOpen, setIsOrderTrackerOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [user, setUser] = useState<any>(null);

  const loadData = useCallback(async () => {
    try {
      const [info, menu] = await Promise.all([getStoreInfo(), getMenu()]);
      setStoreInfo(info);
      setProducts(menu.products);
      setCategories(menu.categories);
    } catch (error) {
      console.error("Erro ao carregar dados:", error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
    incrementVisitCount();
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      if (currentUser && view === 'login') setView('admin');
    });
    return () => unsubscribe();
  }, [loadData, view]);

  // Filtra categorias arquivadas para o menu do cliente
  const activeCategoryNames = useMemo(() => 
    ['Todos', ...categories.filter(c => !c.isArchived).map(c => c.name)], 
    [categories]
  );

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      // O produto deve pertencer a uma categoria que NÃO está arquivada
      const categoryMeta = categories.find(c => c.name === p.category);
      if (categoryMeta?.isArchived) return false;

      const matchesCategory = selectedCategory === 'Todos' || p.category === selectedCategory;
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            p.description.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [products, selectedCategory, searchQuery, categories]);

  const handleAddToCart = useCallback((productToAdd: Product, quantity: number, observations?: string, selectedOption?: ProductOption, selectedCustomizations?: SelectedCustomization[]) => {
    setCartItems(prevItems => {
        // Chave única baseada no ID, variação de tamanho e TODAS as escolhas extras
        const customizationFingerprint = JSON.stringify(selectedCustomizations || []);

        const existingItemIndex = prevItems.findIndex(item => 
            item.id === productToAdd.id && 
            item.selectedOption?.name === selectedOption?.name &&
            JSON.stringify(item.selectedCustomizations || []) === customizationFingerprint
        );

        if (existingItemIndex !== -1) {
            const newItems = [...prevItems];
            newItems[existingItemIndex] = {
                ...newItems[existingItemIndex],
                quantity: newItems[existingItemIndex].quantity + quantity,
                observations: observations 
            };
            return newItems;
        } else {
            const basePrice = selectedOption ? selectedOption.price : productToAdd.price;
            // Soma o preço de todos os itens extras selecionados
            const extraTotal = (selectedCustomizations || []).reduce((acc, group) => {
                return acc + group.items.reduce((gAcc, item) => gAcc + (item.priceExtra * item.quantity), 0);
            }, 0);

            return [...prevItems, { 
                ...productToAdd, 
                price: basePrice + extraTotal,
                quantity, 
                observations, 
                selectedOption,
                selectedCustomizations 
            }];
        }
    });
    setSelectedProduct(null);
  }, []);

  const handleUpdateQuantity = (productId: string, newQuantity: number, optionName?: string) => {
    if (newQuantity <= 0) {
      handleRemoveItem(productId, optionName);
      return;
    }
    setCartItems(prev => prev.map(item => 
      (item.id === productId && item.selectedOption?.name === optionName) 
        ? { ...item, quantity: newQuantity } 
        : item
    ));
  };

  const handleRemoveItem = (productId: string, optionName?: string) => {
    setCartItems(prev => prev.filter(item => !(item.id === productId && item.selectedOption?.name === optionName)));
  };

  const cartTotal = cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const cartItemCount = cartItems.reduce((sum, item) => sum + item.quantity, 0);

  if (view === 'login') return <LoginPage onLoginSuccess={() => setView('admin')} onNavigateBack={() => setView('menu')} />;
  if (view === 'admin' && user) return (
    <AdminPage 
      products={products} 
      categories={categories} 
      storeInfo={storeInfo}
      onAddProduct={async (p) => { await loadData(); }}
      onUpdateProduct={async (p) => { await loadData(); }}
      onDeleteProduct={async (id) => { await loadData(); }}
      onUpdateStoreInfo={async (info) => { setStoreInfo(info); await loadData(); }}
      onAddCategory={async (n) => { await loadData(); }}
      onDeleteCategory={async (n) => { await loadData(); }}
      onUpdateCategoryOrder={async (o) => { await loadData(); }}
      onToggleCategoriesArchive={async (n, a) => { await loadData(); }}
      onNavigateBack={() => setView('menu')}
      onLogout={async () => { await signOut(auth); setView('menu'); }}
      onRefreshData={loadData}
    />
  );

  if (view === 'checkout') return (
    <CheckoutPage 
      cartItems={cartItems} 
      storeInfo={storeInfo} 
      onNavigateBack={() => setView('menu')}
      onUpdateQuantity={handleUpdateQuantity}
      onRemoveItem={handleRemoveItem}
      onOrderSuccess={(order) => {
        setLastOrder(order);
        setCartItems([]);
        setView('order-success');
      }}
    />
  );

  if (view === 'order-success') return <OrderSuccessPage order={lastOrder} storeInfo={storeInfo} onNavigateBack={() => setView('menu')} />;

  return (
    <div className="min-h-screen bg-brand-bg flex flex-col">
      <Header onSearch={setSearchQuery} searchQuery={searchQuery} />
      <CategoryTabs 
        categories={activeCategoryNames} 
        selectedCategory={selectedCategory} 
        onSelectCategory={setSelectedCategory}
        onOpenMenu={() => setIsCategoryMenuOpen(true)}
        onSearch={setSearchQuery}
        searchQuery={searchQuery}
      />

      <main className="flex-grow pb-24">
        <StoreInfo 
          storeInfo={storeInfo} 
          isLoading={isLoading} 
          onOpenModal={() => setIsStoreModalOpen(true)}
          onOpenOrderTracker={() => setIsOrderTrackerOpen(true)}
        />

        <div className="container mx-auto px-4 sm:px-6 lg:px-8 mt-8">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredProducts.map(product => (
              <ProductCard key={product.id} product={product} onProductClick={setSelectedProduct} />
            ))}
          </div>
          {filteredProducts.length === 0 && !isLoading && (
            <div className="text-center py-20">
              <p className="text-brand-text-light">Nenhum produto encontrado nesta categoria.</p>
            </div>
          )}
        </div>
      </main>

      <Footer onNavigate={(v) => setView(v)} />

      <CartButton itemCount={cartItemCount} totalPrice={cartTotal} onClick={() => setIsCartOpen(true)} />

      <ProductDetailModal product={selectedProduct} onClose={() => setSelectedProduct(null)} onAddToCart={handleAddToCart} />

      <Cart 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        cartItems={cartItems} 
        onUpdateQuantity={handleUpdateQuantity} 
        onRemoveItem={handleRemoveItem} 
        onCheckout={() => { setIsCartOpen(false); setView('checkout'); }} 
      />

      <StoreInfoModal isOpen={isStoreModalOpen} onClose={() => setIsStoreModalOpen(false)} storeInfo={storeInfo} />
      <CategoryMenuModal isOpen={isCategoryMenuOpen} onClose={() => setIsCategoryMenuOpen(false)} categories={activeCategoryNames} onSelectCategory={setSelectedCategory} />
      <OrderTrackingModal isOpen={isOrderTrackerOpen} onClose={() => setIsOrderTrackerOpen(false)} onTrackOrder={(o) => { setLastOrder(o); setView('order-success'); setIsOrderTrackerOpen(false); }} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Product, ProductOption, SelectedCustomization, CustomizationGroup, CustomizationOption } from '../types';
import { ArrowLeftIcon, PlusIcon, MinusIcon, ShoppingBagIcon, XIcon, CheckCircleIcon } from './IconComponents';

interface ProductDetailModalProps {
  product: Product | null;
  onClose: () => void;
  onAddToCart: (product: Product, quantity: number, observations?: string, selectedOption?: ProductOption, selectedCustomizations?: SelectedCustomization[]) => void;
}

const ProductDetailModal: React.FC<ProductDetailModalProps> = ({ product, onClose, onAddToCart }) => {
  const [quantity, setQuantity] = useState(1);
  const [observations, setObservations] = useState('');
  const [selectedOption, setSelectedOption] = useState<ProductOption | null>(null);
  const [customSelections, setCustomSelections] = useState<Record<string, Record<string, number>>>({});

  useEffect(() => {
    if (product) {
      setQuantity(1);
      setObservations('');
      setCustomSelections({});
      setSelectedOption(product.options && product.options.length > 0 ? product.options[0] : null);
    }
  }, [product]);

  const formatPrice = (price: number) => price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const { extraTotal, isAllGroupsValid, formattedCustomizations } = useMemo(() => {
    let total = 0;
    let allValid = true;
    const result: SelectedCustomization[] = [];

    if (!product?.customizationGroups) return { extraTotal: 0, isAllGroupsValid: true, formattedCustomizations: [] };

    for (const group of product.customizationGroups) {
      const groupSelections = customSelections[group.id] || {};
      const totalInGroup = Object.values(groupSelections).reduce((a, b) => a + b, 0);

      if (totalInGroup < group.min || totalInGroup > group.max) allValid = false;

      const items = [];
      for (const [optName, optQty] of Object.entries(groupSelections)) {
        if (optQty > 0) {
          const opt = group.options.find(o => o.name === optName);
          if (opt) {
            total += (opt.priceExtra * optQty);
            items.push({ name: opt.name, quantity: optQty, priceExtra: opt.priceExtra });
          }
        }
      }
      if (items.length > 0) result.push({ groupName: group.name, items });
    }
    return { extraTotal: total, isAllGroupsValid: allValid, formattedCustomizations: result };
  }, [product, customSelections]);

  const handleCustomOptionChange = (group: CustomizationGroup, option: CustomizationOption, delta: number) => {
    setCustomSelections(prev => {
      const groupSelections = { ...(prev[group.id] || {}) };
      const currentQty = groupSelections[option.name] || 0;
      const totalInGroup = Object.values(groupSelections).reduce((a, b) => a + b, 0);

      if (group.type === 'single') {
        if (delta > 0) return { ...prev, [group.id]: { [option.name]: 1 } };
        return { ...prev, [group.id]: {} };
      }

      const newQty = Math.max(0, currentQty + delta);
      if (delta > 0 && totalInGroup >= group.max) return prev;

      return { ...prev, [group.id]: { ...groupSelections, [option.name]: newQty } };
    });
  };

  if (!product) return null;

  const basePrice = selectedOption ? selectedOption.price : product.price;
  const totalPrice = (basePrice + extraTotal) * quantity;
  const isSoldOut = product.inventoryEnabled && (product.inventoryQuantity || 0) <= 0;

  return (
    <div className="fixed inset-0 z-50 bg-white flex flex-col animate-slide-in-up">
      <div className="flex-1 overflow-y-auto pb-32">
        <div className="max-w-2xl mx-auto w-full">
          {product.imageUrls?.length > 0 ? (
            <div className="relative bg-gray-100 aspect-video">
              <img src={product.imageUrls[0]} className="w-full h-full object-cover" alt={product.name} />
              <button onClick={onClose} className="absolute top-4 left-4 p-2 bg-white/80 rounded-full shadow-md"><ArrowLeftIcon className="w-6 h-6"/></button>
            </div>
          ) : (
            <div className="p-4 border-b flex items-center sticky top-0 bg-white z-10">
              <button onClick={onClose} className="p-2"><ArrowLeftIcon className="w-6 h-6"/></button>
              <h2 className="ml-2 font-bold truncate">{product.name}</h2>
            </div>
          )}

          <div className="p-6 space-y-8">
            <div>
              <h1 className="text-2xl font-bold text-brand-text">{product.name}</h1>
              <p className="text-brand-text-light mt-2 text-sm">{product.description}</p>
            </div>

            {product.options && product.options.length > 0 && (
              <div className="space-y-4">
                <h3 className="text-base font-bold border-l-4 border-brand-primary pl-3">Escolha o Tamanho</h3>
                <div className="grid gap-2">
                  {product.options.map((opt, i) => (
                    <button key={i} onClick={() => setSelectedOption(opt)} className={`flex justify-between p-4 rounded-xl border transition-all ${selectedOption?.name === opt.name ? 'border-brand-primary bg-brand-secondary/20 ring-1 ring-brand-primary' : 'border-gray-100'}`}>
                      <span className="font-bold">{opt.name}</span>
                      <span className="font-bold text-brand-primary">{formatPrice(opt.price)}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {product.customizationGroups?.map(group => {
              const groupSelections = customSelections[group.id] || {};
              const totalInGroup = Object.values(groupSelections).reduce((a, b) => a + b, 0);
              const isValid = totalInGroup >= group.min && totalInGroup <= group.max;

              return (
                <div key={group.id} className="pt-6 border-t border-gray-100 space-y-4">
                  <div className="flex justify-between items-start">
                    <div>
                      <h3 className="text-base font-bold">{group.name}</h3>
                      <p className="text-xs text-gray-400">
                        {group.min === group.max ? `Escolha ${group.min}` : `Escolha de ${group.min} a ${group.max}`}
                      </p>
                    </div>
                    {isValid ? <CheckCircleIcon className="w-5 h-5 text-green-500" /> : <span className="text-[10px] font-bold bg-amber-100 text-amber-700 px-2 py-0.5 rounded uppercase">Obrigatório</span>}
                  </div>
                  <div className="space-y-3">
                    {group.options.map(opt => {
                      const qty = groupSelections[opt.name] || 0;
                      return (
                        <div key={opt.name} className={`flex items-center justify-between p-3 rounded-xl border transition-all ${qty > 0 ? 'border-brand-primary/50 bg-brand-secondary/10' : 'border-gray-50'}`}>
                          <div className="flex-grow pr-4">
                            <p className="text-sm font-bold">{opt.name}</p>
                            {opt.priceExtra > 0 && <p className="text-xs text-brand-accent font-bold">+{formatPrice(opt.priceExtra)}</p>}
                          </div>
                          <div className="flex items-center bg-white rounded-lg border border-gray-100 shadow-sm">
                            <button onClick={() => handleCustomOptionChange(group, opt, -1)} className={`p-2 ${qty === 0 ? 'opacity-20' : ''}`}><MinusIcon className="w-4 h-4"/></button>
                            <span className="px-2 text-sm font-black w-8 text-center">{qty}</span>
                            <button onClick={() => handleCustomOptionChange(group, opt, 1)} className={`p-2 ${totalInGroup >= group.max && group.type !== 'single' ? 'opacity-20' : ''}`}><PlusIcon className="w-4 h-4"/></button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}

            <div className="pt-6 border-t border-gray-100">
              <label className="block text-sm font-bold mb-2">Alguma observação?</label>
              <textarea value={observations} onChange={e => setObservations(e.target.value)} rows={3} placeholder="Ex: Sem açúcar, trocar morango por uva..." className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-brand-primary outline-none" />
            </div>
          </div>
        </div>
      </div>

      {!isSoldOut && (
        <div className="fixed bottom-0 left-0 right-0 bg-white border-t p-4 shadow-lg z-20">
          <div className="max-w-2xl mx-auto flex items-center gap-4">
            <div className="flex items-center bg-gray-100 rounded-full">
              <button onClick={() => setQuantity(q => Math.max(1, q - 1))} className="p-3"><MinusIcon className="w-5 h-5"/></button>
              <span className="px-4 font-black text-lg">{quantity}</span>
              <button onClick={() => setQuantity(q => q + 1)} className="p-3"><PlusIcon className="w-5 h-5"/></button>
            </div>
            <button onClick={() => onAddToCart(product, quantity, observations, selectedOption || undefined, formattedCustomizations)} disabled={!isAllGroupsValid} className="flex-grow bg-brand-primary text-white font-black py-4 rounded-xl flex items-center justify-between px-6 disabled:opacity-50">
              <span>Adicionar</span>
              <span>{formatPrice(totalPrice)}</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

