import React, { useState, useMemo } from 'react';
import type { Product, ProductOption, CategoryMetadata, CustomizationGroup, CustomizationOption } from '../types';
import { TrashIcon, SearchIcon, PlusIcon, ChevronRightIcon, XIcon as CloseIcon } from './IconComponents';

const CustomizationGroupEditor: React.FC<{
    groups: CustomizationGroup[];
    onChange: (groups: CustomizationGroup[]) => void;
}> = ({ groups, onChange }) => {
    const addGroup = () => {
        const newGroup: CustomizationGroup = {
            id: `group-${Date.now()}`,
            name: '',
            min: 1,
            max: 1,
            type: 'single',
            options: []
        };
        onChange([...groups, newGroup]);
    };

    const updateGroup = (id: string, data: Partial<CustomizationGroup>) => {
        onChange(groups.map(g => g.id === id ? { ...g, ...data } : g));
    };

    const removeGroup = (id: string) => onChange(groups.filter(g => g.id !== id));

    const addOption = (groupId: string) => {
        onChange(groups.map(g => g.id === groupId ? { ...g, options: [...g.options, { name: '', priceExtra: 0 }] } : g));
    };

    const updateOption = (groupId: string, optIndex: number, data: Partial<CustomizationOption>) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                const newOpts = [...g.options];
                newOpts[optIndex] = { ...newOpts[optIndex], ...data };
                return { ...g, options: newOpts };
            }
            return g;
        }));
    };

    const removeOption = (groupId: string, optIndex: number) => {
        onChange(groups.map(g => g.id === groupId ? { ...g, options: g.options.filter((_, i) => i !== optIndex) } : g));
    };

    return (
        <div className="space-y-6 mt-6 border-t pt-6">
            <div className="flex items-center justify-between">
                <h3 className="text-sm font-black text-gray-700 uppercase tracking-widest">Personalização & Adicionais</h3>
                <button type="button" onClick={addGroup} className="text-xs font-bold text-brand-primary bg-brand-secondary/30 px-3 py-1.5 rounded-full hover:bg-brand-primary hover:text-white transition-all">
                    + Novo Grupo
                </button>
            </div>
            <div className="space-y-4">
                {groups.map((group) => (
                    <div key={group.id} className="bg-gray-50 p-4 rounded-xl border border-gray-200 relative">
                        <button onClick={() => removeGroup(group.id)} className="absolute top-3 right-3 text-gray-300 hover:text-red-500"><TrashIcon className="w-5 h-5"/></button>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                            <div>
                                <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Nome do Grupo (Ex: Massa)</label>
                                <input type="text" value={group.name} onChange={e => updateGroup(group.id, { name: e.target.value })} className="w-full px-3 py-2 border rounded-lg text-sm bg-white"/>
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Mínimo</label>
                                    <input type="number" value={group.min} onChange={e => updateGroup(group.id, { min: parseInt(e.target.value) })} className="w-full px-3 py-2 border rounded-lg text-sm bg-white"/>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Máximo</label>
                                    <input type="number" value={group.max} onChange={e => updateGroup(group.id, { max: parseInt(e.target.value), type: parseInt(e.target.value) > 1 ? 'counter' : 'single' })} className="w-full px-3 py-2 border rounded-lg text-sm bg-white"/>
                                </div>
                            </div>
                        </div>
                        <div className="space-y-2">
                            {group.options.map((opt, idx) => (
                                <div key={idx} className="flex gap-2 items-center bg-white p-2 rounded-lg border border-gray-100 shadow-sm">
                                    <input type="text" value={opt.name} onChange={e => updateOption(group.id, idx, { name: e.target.value })} placeholder="Nome" className="flex-grow px-2 py-1 text-sm outline-none"/>
                                    <div className="flex items-center gap-1 bg-gray-50 px-2 py-1 rounded">
                                        <span className="text-[10px] text-gray-400 font-bold">R$</span>
                                        <input type="number" step="0.01" value={opt.priceExtra} onChange={e => updateOption(group.id, idx, { priceExtra: parseFloat(e.target.value) })} className="w-16 bg-transparent text-sm font-bold text-brand-primary outline-none" />
                                    </div>
                                    <button type="button" onClick={() => removeOption(group.id, idx)} className="text-gray-300 hover:text-red-500"><TrashIcon className="w-4 h-4"/></button>
                                </div>
                            ))}
                            <button type="button" onClick={() => addOption(group.id)} className="w-full py-2 border-2 border-dashed border-gray-200 rounded-lg text-[10px] text-gray-400 font-bold hover:border-brand-primary hover:text-brand-primary">
                                + Adicionar Opção
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

