        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filtered.map((p: any) => (
                <div key={p.id} className="bg-white rounded-xl shadow-sm border p-4 flex gap-4">
                    <img src={p.imageUrls?.[0]} className="w-20 h-20 object-cover rounded-lg" alt="" />
                    <div className="flex-grow min-w-0">
