import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Product, ProductOption, SelectedCustomization, CustomizationGroup, CustomizationOption } from '../types';
import { ArrowLeftIcon, PlusIcon, MinusIcon, ShoppingBagIcon, XIcon, CheckCircleIcon } from './IconComponents';

interface ProductDetailModalProps {
  product: Product | null;
  onClose: () => void;
  onAddToCart: (product: Product, quantity: number, observations?: string, selectedOption?: ProductOption, selectedCustomizations?: SelectedCustomization[]) => void;
}

const ProductDetailModal: React.FC<ProductDetailModalProps> = ({ product, onClose, onAddToCart }) => {
  const [quantity, setQuantity] = useState(1);
  const [observations, setObservations] = useState('');
  const [selectedOption, setSelectedOption] = useState<ProductOption | null>(null);
  const [customSelections, setCustomSelections] = useState<Record<string, Record<string, number>>>({});

  useEffect(() => {
    if (product) {
      setQuantity(1);
      setObservations('');
      setCustomSelections({});
      setSelectedOption(product.options && product.options.length > 0 ? product.options[0] : null);
    }
  }, [product]);

  const formatPrice = (price: number) => price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const { extraTotal, isAllGroupsValid, formattedCustomizations } = useMemo(() => {
    let total = 0;
    let allValid = true;
    const result: SelectedCustomization[] = [];

    if (!product?.customizationGroups) return { extraTotal: 0, isAllGroupsValid: true, formattedCustomizations: [] };

    for (const group of product.customizationGroups) {
      const groupSelections = customSelections[group.id] || {};
      // Fix: Add explicit type cast to ensure reduce works with numbers
      const totalInGroup = (Object.values(groupSelections) as number[]).reduce((a: number, b: number) => a + b, 0);

      if (totalInGroup < group.min || totalInGroup > group.max) allValid = false;

      const items = [];
      // Fix: Add explicit type cast to ensure optQty is treated as a number
      for (const [optName, optQty] of Object.entries(groupSelections) as [string, number][]) {
        if (optQty > 0) {
          const opt = group.options.find(o => o.name === optName);
          if (opt) {
            total += (opt.priceExtra * optQty);
            items.push({ name: opt.name, quantity: optQty, priceExtra: opt.priceExtra });
          }
        }
      }
      if (items.length > 0) result.push({ groupName: group.name, items });
    }
    return { extraTotal: total, isAllGroupsValid: allValid, formattedCustomizations: result };
  }, [product, customSelections]);

  const handleCustomOptionChange = (group: CustomizationGroup, option: CustomizationOption, delta: number) => {
    setCustomSelections(prev => {
      const groupSelections = { ...(prev[group.id] || {}) };
      const currentQty = groupSelections[option.name] || 0;
      // Fix: Add explicit type cast to ensure reduce works with numbers
      const totalInGroup = (Object.values(groupSelections) as number[]).reduce((a: number, b: number) => a + b, 0);

      if (group.type === 'single') {
        if (delta > 0) return { ...prev, [group.id]: { [option.name]: 1 } };
        return { ...prev, [group.id]: {} };
      }

      const newQty = Math.max(0, currentQty + delta);
      if (delta > 0 && totalInGroup >= group.max) return prev;

      return { ...prev, [group.id]: { ...groupSelections, [option.name]: newQty } };
    });
  };

  if (!product) return null;

  const basePrice = selectedOption ? selectedOption.price : product.price;
  const totalPrice = (basePrice + extraTotal) * quantity;
  const isSoldOut = product.inventoryEnabled && (product.inventoryQuantity || 0) <= 0;

  return (
    <div className="fixed inset-0 z-50 bg-white flex flex-col animate-slide-in-up">
      <div className="flex-1 overflow-y-auto pb-32">
        <div className="max-w-2xl mx-auto w-full">
          {product.imageUrls?.length > 0 ? (
            <div className="relative bg-gray-100 aspect-video">
              <img src={product.imageUrls[0]} className="w-full h-full object-cover" alt={product.name} />
              <button onClick={onClose} className="absolute top-4 left-4 p-2 bg-white/80 rounded-full shadow-md"><ArrowLeftIcon className="w-6 h-6"/></button>
            </div>
          ) : (
            <div className="p-4 border-b flex items-center sticky top-0 bg-white z-10">
              <button onClick={onClose} className="p-2"><ArrowLeftIcon className="w-6 h-6"/></button>
              <h2 className="ml-2 font-bold truncate">{product.name}</h2>
            </div>
          )}

          <div className="p-6 space-y-8">
            <div>
              <h1 className="text-2xl font-bold text-brand-text">{product.name}</h1>
              <p className="text-brand-text-light mt-2 text-sm">{product.description}</p>
            </div>

            {product.options && product.options.length > 0 && (
              <div className="space-y-4">
                <h3 className="text-base font-bold border-l-4 border-brand-primary pl-3">Escolha o Tamanho</h3>
                <div className="grid gap-2">
                  {product.options.map((opt, i) => (
                    <button key={i} onClick={() => setSelectedOption(opt)} className={`flex justify-between p-4 rounded-xl border transition-all ${selectedOption?.name === opt.name ? 'border-brand-primary bg-brand-secondary/20 ring-1 ring-brand-primary' : 'border-gray-100'}`}>
                      <span className="font-bold">{opt.name}</span>
                      <span className="font-bold text-brand-primary">{formatPrice(opt.price)}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {product.customizationGroups?.map(group => {
              const groupSelections = customSelections[group.id] || {};
              // Fix: Add explicit type cast to ensure reduce works with numbers
              const totalInGroup = (Object.values(groupSelections) as number[]).reduce((a: number, b: number) => a + b, 0);
              const isValid = totalInGroup >= group.min && totalInGroup <= group.max;

              return (
                <div key={group.id} className="pt-6 border-t border-gray-100 space-y-4">
                  <div className="flex justify-between items-start">
                    <div>
                      <h3 className="text-base font-bold">{group.name}</h3>
                      <p className="text-xs text-gray-400">
                        {group.min === group.max ? `Escolha ${group.min}` : `Escolha de ${group.min} a ${group.max}`}
                      </p>
                    </div>
                    {isValid ? <CheckCircleIcon className="w-5 h-5 text-green-500" /> : <span className="text-[10px] font-bold bg-amber-100 text-amber-700 px-2 py-0.5 rounded uppercase">Obrigatório</span>}
                  </div>
                  <div className="space-y-3">
                    {group.options.map(opt => {
                      const qty = groupSelections[opt.name] || 0;
                      return (
                        <div key={opt.name} className={`flex items-center justify-between p-3 rounded-xl border transition-all ${qty > 0 ? 'border-brand-primary/50 bg-brand-secondary/10' : 'border-gray-50'}`}>
                          <div className="flex-grow pr-4">
                            <p className="text-sm font-bold">{opt.name}</p>
                            {opt.priceExtra > 0 && <p className="text-xs text-brand-accent font-bold">+{formatPrice(opt.priceExtra)}</p>}
                          </div>
                          <div className="flex items-center bg-white rounded-lg border border-gray-100 shadow-sm">
                            <button onClick={() => handleCustomOptionChange(group, opt, -1)} className={`p-2 ${qty === 0 ? 'opacity-20' : ''}`}><MinusIcon className="w-4 h-4"/></button>
                            <span className="px-2 text-sm font-black w-8 text-center">{qty}</span>
                            <button onClick={() => handleCustomOptionChange(group, opt, 1)} className={`p-2 ${totalInGroup >= group.max && group.type !== 'single' ? 'opacity-20' : ''}`}><PlusIcon className="w-4 h-4"/></button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}

            <div className="pt-6 border-t border-gray-100">
              <label className="block text-sm font-bold mb-2">Alguma observação?</label>
              <textarea value={observations} onChange={e => setObservations(e.target.value)} rows={3} placeholder="Ex: Sem açúcar, trocar morango por uva..." className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-brand-primary outline-none" />
            </div>
          </div>
        </div>
      </div>

      {!isSoldOut && (
        <div className="fixed bottom-0 left-0 right-0 bg-white border-t p-4 shadow-lg z-20">
          <div className="max-w-2xl mx-auto flex items-center gap-4">
            <div className="flex items-center bg-gray-100 rounded-full">
              <button onClick={() => setQuantity(q => Math.max(1, q - 1))} className="p-3"><MinusIcon className="w-5 h-5"/></button>
              <span className="px-4 font-black text-lg">{quantity}</span>
              <button onClick={() => setQuantity(q => q + 1)} className="p-3"><PlusIcon className="w-5 h-5"/></button>
            </div>
            <button onClick={() => onAddToCart(product, quantity, observations, selectedOption || undefined, formattedCustomizations)} disabled={!isAllGroupsValid} className="flex-grow bg-brand-primary text-white font-black py-4 rounded-xl flex items-center justify-between px-6 disabled:opacity-50">
              <span>Adicionar</span>
              <span>{formatPrice(totalPrice)}</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

