import CategoryTabs from './components/CategoryTabs';
import ProductCard from './components/ProductCard';
import Footer from './components/Footer';
import LoginPage from './components/LoginPage';
import AdminPage from './components/AdminPage';
import StoreInfoModal from './components/StoreInfoModal';
import CategoryMenuModal from './components/CategoryMenuModal';
import ProductDetailModal from './components/ProductDetailModal';
import CartButton from './components/CartButton';
import CheckoutPage from './components/CheckoutPage';
import OrderSuccessPage from './components/OrderSuccessPage';
import OrderTrackingModal from './components/OrderTrackingModal';
import { BikeIcon, ShoppingBagIcon } from './components/IconComponents';
import type { Product, CartItem, StoreInfoData, Order, ProductOption, CategoryMetadata, SelectedCustomization } from './types';
import { getMenu, addProduct, getStoreInfo, updateStoreInfo, updateProduct, deleteProduct, addCategory, deleteCategory, initializeFirebaseData, updateCategoryOrder, incrementVisitCount, getOrderById, toggleCategoriesArchive } from './services/menuService';
import { auth } from './firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';

const App: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<CategoryMetadata[]>([]);
  const [storeInfo, setStoreInfo] = useState<StoreInfoData | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<string>('Todos');
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [view, setView] = useState<'menu' | 'login' | 'admin' | 'checkout' | 'orderSuccess'>('menu');
  const [orderSuccessData, setOrderSuccessData] = useState<Order | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [isStoreInfoModalOpen, setStoreInfoModalOpen] = useState(false);
  const [isCategoryMenuOpen, setCategoryMenuOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [isOrderTrackingOpen, setIsOrderTrackingOpen] = useState(false);

  const [activeOrders, setActiveOrders] = useState<Order[]>([]);

  useEffect(() => {
    incrementVisitCount();
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      if (user) {
        setIsAuthenticated(true);
      } else {
        setIsAuthenticated(false);
        setView(currentView => currentView === 'admin' ? 'login' : currentView);
      }
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const checkActiveOrders = async () => {
      let ids: string[] = [];
      const legacyId = localStorage.getItem('activeOrderId');
      if (legacyId) ids.push(legacyId);
      const storedIds = localStorage.getItem('activeOrderIds');
      if (storedIds) {
        try {
          const parsed = JSON.parse(storedIds);
          if (Array.isArray(parsed)) {
            ids = [...ids, ...parsed];
          }
        } catch (e) {
          console.error("Error parsing activeOrderIds", e);
        }
      }
      ids = [...new Set(ids)];
      if (ids.length === 0) {
        setActiveOrders([]);
        return;
      }
      const promises = ids.map(id => getOrderById(id));
      const results = await Promise.all(promises);
      const validOrders: Order[] = [];
      const validIds: string[] = [];
      results.forEach(order => {
        if (order && order.status !== 'archived' && order.status !== 'completed') {
            validOrders.push(order);
            validIds.push(order.id);
        }
      });
      validOrders.sort((a, b) => b.orderNumber - a.orderNumber);
      setActiveOrders(validOrders);
      if (validIds.length !== ids.length || legacyId) {
          localStorage.setItem('activeOrderIds', JSON.stringify(validIds));
          localStorage.removeItem('activeOrderId');
      }
    };
    checkActiveOrders();
    const interval = setInterval(checkActiveOrders, 30000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const isModalOpen = isStoreInfoModalOpen || isCategoryMenuOpen || !!selectedProduct || isOrderTrackingOpen;
    if (isModalOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'auto';
    }
    return () => {
      document.body.style.overflow = 'auto';
    };
  }, [isStoreInfoModalOpen, isCategoryMenuOpen, selectedProduct, isOrderTrackingOpen]);

  const fetchInitialData = useCallback(async () => {
    setIsLoading(true);
    try {
        await initializeFirebaseData();
        const [menuResult, storeInfoResult] = await Promise.all([getMenu(), getStoreInfo()]);
        setProducts(menuResult.products);
        setCategories(menuResult.categories);
        setStoreInfo(storeInfoResult);
    } catch (error) {
        console.error("Failed to fetch initial data", error);
    } finally {
        setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    if (view === 'menu' || (view === 'admin' && isAuthenticated)) {
        fetchInitialData();
    }
  }, [view, isAuthenticated, fetchInitialData]);

  const handleSelectCategory = useCallback((category: string) => {
    setSelectedCategory(category);
  }, []);

  const handleModalCategorySelect = useCallback((category: string) => {
    setSelectedCategory(category);
    setCategoryMenuOpen(false);
  }, []);

  const handleAddProduct = useCallback(async (productData: Omit<Product, 'id'>) => {
    await addProduct(productData);
    await fetchInitialData(); 
  }, [fetchInitialData]);

  const handleUpdateProduct = useCallback(async (productData: Product) => {
      await updateProduct(productData);
      await fetchInitialData();
  }, [fetchInitialData]);

   const handleDeleteProduct = useCallback(async (productId: string) => {
      try {
        await deleteProduct(productId);
        setProducts(prevProducts => prevProducts.filter(p => p.id !== productId));
      } catch (error) {
        console.error("Failed to delete product. Refetching to sync.", error);
        await fetchInitialData();
      }
  }, [fetchInitialData]);

  const handleUpdateStoreInfo = useCallback(async (storeInfoData: StoreInfoData) => {
      await updateStoreInfo(storeInfoData);
      await fetchInitialData();
  }, [fetchInitialData]);

  const handleAddCategory = useCallback(async (categoryName: string) => {
    const updatedCategories = await addCategory(categoryName);
    setCategories(updatedCategories);
  }, []);

  const handleDeleteCategory = useCallback(async (categoryName: string) => {
      const updatedCategories = await deleteCategory(categoryName);
      setCategories(updatedCategories);
      if (selectedCategory === categoryName) {
        setSelectedCategory('Todos');
      }
  }, [selectedCategory]);

  const handleUpdateCategoryOrder = useCallback(async (newOrder: CategoryMetadata[]) => {
      try {
          await updateCategoryOrder(newOrder);
          setCategories(newOrder);
      } catch (error) {
          console.error("Failed to update category order", error);
          await fetchInitialData();
      }
  }, [fetchInitialData]);

  const handleToggleCategoriesArchive = useCallback(async (categoryNames: string[], archive: boolean) => {
      try {
          const updated = await toggleCategoriesArchive(categoryNames, archive);
          setCategories(updated);
          if (archive && categoryNames.includes(selectedCategory)) {
              setSelectedCategory('Todos');
          }
      } catch (error) {
          console.error("Failed to archive categories", error);
      }
  }, [selectedCategory]);

  const handleProductClick = useCallback((product: Product) => {
    setSelectedProduct(product);
  }, []);

  const handleCloseModal = useCallback(() => {
    setSelectedProduct(null);
  }, []);

  const handleAddToCart = useCallback((productToAdd: Product, quantity: number, observations?: string, selectedOption?: ProductOption, selectedCustomizations?: SelectedCustomization[]) => {
    setCartItems(prevItems => {
        // Criamos uma chave única baseada em: ID + Nome da Opção + String das Customizações
        // Isso garante que dois bolos com recheios diferentes não se agrupem erroneamente
        const customizationKey = JSON.stringify(selectedCustomizations || []);
        const existingItemIndex = prevItems.findIndex(item => 
            item.id === productToAdd.id && 
            item.selectedOption?.name === selectedOption?.name &&
            JSON.stringify(item.selectedCustomizations || []) === customizationKey
        );

        if (existingItemIndex !== -1) {
            const newItems = [...prevItems];
            newItems[existingItemIndex] = {
                ...newItems[existingItemIndex],
                quantity: newItems[existingItemIndex].quantity + quantity,
                observations: observations 
            };
            return newItems;
        } else {
            const basePrice = selectedOption ? selectedOption.price : productToAdd.price;
            // Somamos o preço base com os extras das customizações
            const extraPrice = (selectedCustomizations || []).reduce((acc, group) => {
                return acc + group.items.reduce((groupAcc, item) => groupAcc + (item.priceExtra * item.quantity), 0);
            }, 0);

            return [...prevItems, { 
                ...productToAdd, 
                price: basePrice + extraPrice,
                quantity, 
                observations, 
                selectedOption,
                selectedCustomizations 
            }];
        }
    });
    setSelectedProduct(null);
  }, []);

  const handleUpdateCartQuantity = useCallback((productId: string, newQuantity: number, optionName?: string) => {
    setCartItems(prev => {
        if (newQuantity <= 0) {
            return prev.filter(item => !(item.id === productId && item.selectedOption?.name === optionName));
        }
        return prev.map(item =>
            (item.id === productId && item.selectedOption?.name === optionName) 
                ? { ...item, quantity: newQuantity } 
                : item
        );
    });
  }, []);

  const handleRemoveFromCart = useCallback((productId: string, optionName?: string) => {
    setCartItems(prev => prev.filter(item => !(item.id === productId && item.selectedOption?.name === optionName)));
  }, []);

  const handleGoToCheckout = useCallback(() => {
    setView('checkout');
  }, []);

  const handleOrderSuccess = (order: Order) => {
    setOrderSuccessData(order);
    setCartItems([]);
    setActiveOrders(prev => {
        const exists = prev.some(o => o.id === order.id);
        const newOrders = exists 
            ? prev.map(o => o.id === order.id ? order : o) 
            : [order, ...prev];
        const ids = newOrders.map(o => o.id);
        localStorage.setItem('activeOrderIds', JSON.stringify(ids));
        localStorage.removeItem('activeOrderId');
        return newOrders;
    });
    setView('orderSuccess');
  };

  const handleTrackOrder = useCallback((order: Order) => {
    setOrderSuccessData(order);
    setView('orderSuccess');
    setIsOrderTrackingOpen(false);
  }, []);

  const handleBannerClick = () => {
    if (activeOrders.length === 1) {
        setOrderSuccessData(activeOrders[0]);
        setView('orderSuccess');
    } else if (activeOrders.length > 1) {
        setIsOrderTrackingOpen(true);
    }
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
      setView('login');
    } catch (error) {
      console.error("Error signing out", error);
    }
  };

  const SectionTitle: React.FC<{ title: string }> = ({ title }) => (
    <div className="flex justify-between items-center mb-6 mt-10">
        <div className="flex items-center space-x-3">
            <div className="w-1.5 h-6 bg-brand-primary rounded-full"></div>
            <h2 className="text-xl font-bold text-brand-text tracking-tight">{title}</h2>
        </div>
    </div>
  );

  const activeCategoriesList = useMemo(() => {
      return categories.filter(c => !c.isArchived).map(c => c.name);
  }, [categories]);

  const allVisibleCategoriesForTabs = useMemo(() => {
    const productCategories = new Set(products.map(p => p.category));
    const activeOfficial = activeCategoriesList;
    const orphanCategories = Array.from(productCategories).filter(cat => 
        cat && cat !== 'Todos' && !activeOfficial.includes(cat) && 
        !categories.some(c => c.name === cat && c.isArchived)
    );
    return [...activeOfficial, ...orphanCategories];
  }, [activeCategoriesList, products, categories]);

  const renderMenu = () => {
    const categoriesWithProducts = allVisibleCategoriesForTabs.filter(category => 
        products.some(p => p.category === category)
    );
    const visibleCategoriesForTabs = ['Todos', ...categoriesWithProducts];

    const getStatusText = (status: Order['status']) => {
        const texts = {
            new: 'Recebido',
            pending_payment: 'Pagamento Pendente',
            confirmed: 'Em Preparo',
            shipped: 'Saiu para entrega',
            completed: 'Finalizado',
            archived: ''
        };
        return texts[status] || 'Em andamento';
    };

    return (
        <>
        <div className="min-h-screen flex flex-col bg-gray-50">
            {activeOrders.length > 0 && (
                <div 
                    onClick={handleBannerClick}
                    className="bg-brand-primary text-white py-3 px-4 cursor-pointer shadow-md flex items-center justify-between"
                >
                    {activeOrders.length === 1 ? (
                        <>
                            <div className="flex items-center gap-3">
                                <div className="bg-white/20 p-2 rounded-full">
                                    <BikeIcon className="w-5 h-5 text-white" />
                                </div>
                                <div>
                                    <p className="text-sm font-semibold">Você possui um pedido em andamento</p>
                                    <p className="text-xs text-brand-secondary opacity-90">
                                        Pedido #{activeOrders[0].orderNumber} • {getStatusText(activeOrders[0].status)}
                                    </p>
                                </div>
                            </div>
                            <div className="bg-white/10 px-3 py-1 rounded text-xs font-bold hover:bg-white/20 transition-colors">
                                Ver
                            </div>
                        </>
                    ) : (
                        <>
                            <div className="flex items-center gap-3">
                                <div className="bg-white/20 p-2 rounded-full">
                                    <ShoppingBagIcon className="w-5 h-5 text-white" />
                                </div>
                                <div>
                                    <p className="text-sm font-semibold">Você tem {activeOrders.length} pedidos em andamento</p>
                                    <p className="text-xs text-brand-secondary opacity-90">
                                        Toque para acompanhar
                                    </p>
                                </div>
                            </div>
                            <div className="bg-white/10 px-3 py-1 rounded text-xs font-bold hover:bg-white/20 transition-colors">
                                Ver todos
                            </div>
                        </>
                    )}
                </div>
            )}
            <main className="flex-grow">
            <StoreInfo 
                storeInfo={storeInfo} 
                isLoading={!storeInfo}
                onOpenModal={() => setStoreInfoModalOpen(true)}
                onOpenOrderTracker={() => setIsOrderTrackingOpen(true)}
            />
            <CategoryTabs
                categories={visibleCategoriesForTabs}
                selectedCategory={selectedCategory}
                onSelectCategory={handleSelectCategory}
                onOpenMenu={() => setStoreInfoModalOpen(true)} // Mantido como original
                onSearch={setSearchQuery}
                searchQuery={searchQuery}
            />
            <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-4">
                {isLoading ? (
                <div>
                    {Array.from({length: 2}).map((_, i) => (
                        <div key={i}>
                            <div className="h-6 bg-gray-200 rounded w-1/3 animate-pulse mb-4 mt-8"></div>
                            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                                {Array.from({length: 3}).map((_, index) => (
                                    <div key={index} className="flex items-center bg-white p-2 rounded-lg gap-4 animate-pulse">
                                        <div className="w-24 h-24 sm:w-32 sm:h-32 bg-gray-200 rounded-md"></div>
                                        <div className="flex-grow space-y-3 py-2">
                                            <div className="h-5 bg-gray-200 rounded w-3/4"></div>
                                            <div className="h-4 bg-gray-200 rounded w-full hidden sm:block"></div>
                                            <div className="h-6 bg-gray-200 rounded w-1/2"></div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
                ) : searchQuery.trim() !== '' ? (() => {
                    const searchResults = products.filter(p =>
                    p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                    p.description.toLowerCase().includes(searchQuery.toLowerCase())
                    );
                    return (
                    <section>
                        <SectionTitle title={`Resultados para "${searchQuery}"`} />
                        {searchResults.length > 0 ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 sm:gap-6">
                            {searchResults.map(product => (
                            <ProductCard key={product.id} product={product} onProductClick={handleProductClick} />
                            ))}
                        </div>
                        ) : (
                        <p className="text-center text-gray-500 mt-8">Nenhum produto encontrado.</p>
                        )}
                    </section>
                    );
                })() : (
                    selectedCategory === 'Todos' ? (
                        categoriesWithProducts.map(category => {
                            const categoryProducts = products.filter(p => p.category === category);
                            if (categoryProducts.length === 0) return null;
                            return (
                                <section key={category}>
                                    <SectionTitle title={category} />
                                    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 sm:gap-6">
                                        {categoryProducts.map(product => (
                                            <ProductCard key={product.id} product={product} onProductClick={handleProductClick} />
                                        ))}
                                    </div>
                                </section>
                            )
                        })
                    ) : (() => {
                        const categoryProducts = products.filter(p => p.category === selectedCategory);
                        return (
                        <section>
                            <SectionTitle title={selectedCategory} />
                            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 sm:gap-6">
                                {categoryProducts.map(product => (
                                <ProductCard
                                    key={product.id}
                                    product={product}
                                    onProductClick={handleProductClick}
                                />
                                ))}
                            </div>
                        </section>
                        );
                    })()
                )}
            </div>
            </main>
            <Footer onNavigate={(target) => {
                if (target === 'login' && isAuthenticated) {
                    setView('admin');
                } else {
                    setView(target);
                }
            }} />
            {cartItems.length > 0 && <div className="h-24 sm:h-28" />}
        </div>
        <StoreInfoModal 
            isOpen={isStoreInfoModalOpen}
            onClose={() => setStoreInfoModalOpen(false)}
            storeInfo={storeInfo}
        />
        <CategoryMenuModal
            isOpen={isCategoryMenuOpen}
            onClose={() => setCategoryMenuOpen(false)}
            categories={categoriesWithProducts}
            onSelectCategory={handleModalCategorySelect}
        />
        <ProductDetailModal 
            product={selectedProduct}
            onClose={handleCloseModal}
            onAddToCart={handleAddToCart}
        />
        <CartButton 
            itemCount={cartItems.reduce((sum, item) => sum + item.quantity, 0)}
            totalPrice={cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0)}
            onClick={handleGoToCheckout}
        />
        <OrderTrackingModal
            isOpen={isOrderTrackingOpen}
            onClose={() => setIsOrderTrackingOpen(false)}
            onTrackOrder={handleTrackOrder}
            initialOrders={activeOrders}
        />
        </>
    );
  }


  switch (view) {
    case 'login':
      return <LoginPage
        onLoginSuccess={() => {
          setView('admin');
        }}
        onNavigateBack={() => setView('menu')}
      />;
    case 'admin':
      if (!isAuthenticated) {
        return <div className="min-h-screen flex items-center justify-center">Verificando acesso...</div>;
      }
      return <AdminPage
        products={products}
        categories={categories}
        storeInfo={storeInfo}
        onAddProduct={handleAddProduct}
        onUpdateProduct={handleUpdateProduct}
        onDeleteProduct={handleDeleteProduct}
        onUpdateStoreInfo={handleUpdateStoreInfo}
        onAddCategory={handleAddCategory}
        onDeleteCategory={handleDeleteCategory}
        onUpdateCategoryOrder={handleUpdateCategoryOrder}
        onToggleCategoriesArchive={handleToggleCategoriesArchive}
        onNavigateBack={() => setView('menu')}
        onLogout={handleLogout}
        onRefreshData={fetchInitialData}
      />;
    case 'checkout':
        return <CheckoutPage 
            cartItems={cartItems}
            storeInfo={storeInfo}
            onNavigateBack={() => {
                setView('menu');
            }}
            onOrderSuccess={handleOrderSuccess}
            onUpdateQuantity={handleUpdateCartQuantity}
            onRemoveItem={handleRemoveFromCart}
        />;
    case 'orderSuccess':
        return <OrderSuccessPage
            order={orderSuccessData}
            storeInfo={storeInfo}
            onNavigateBack={() => setView('menu')}
        />
    default:
      return renderMenu();
  }
};

export default App;

import React from 'react';
import type { CartItem } from '../types';
import { XIcon, PlusIcon, MinusIcon, TrashIcon } from './IconComponents';

interface CartProps {
  isOpen: boolean;
  onClose: () => void;
  cartItems: CartItem[];
  onUpdateQuantity: (productId: string, newQuantity: number, optionName?: string) => void;
  onRemoveItem: (productId: string, optionName?: string) => void;
  onCheckout: () => void;
}

const Cart: React.FC<CartProps> = ({ isOpen, onClose, cartItems, onUpdateQuantity, onRemoveItem, onCheckout }) => {
  const total = cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0);

  const formatPrice = (price: number) => {
    return price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  return (
    <>
      <div
        className={`fixed inset-0 bg-black bg-opacity-50 z-40 transition-opacity duration-300 ${
          isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'
        }`}
        onClick={onClose}
      />
      <div
        className={`fixed top-0 right-0 h-full w-full max-w-md bg-brand-bg shadow-2xl z-50 transform transition-transform duration-300 ease-in-out ${
          isOpen ? 'translate-x-0' : 'translate-x-full'
        }`}
      >
        <div className="flex flex-col h-full">
          <div className="flex items-center justify-between p-4 border-b border-brand-secondary">
            <h2 className="text-2xl font-bold text-brand-text">Meu Pedido</h2>
            <button onClick={onClose} className="p-2 rounded-full hover:bg-brand-secondary/50">
              <XIcon className="h-6 w-6 text-brand-text" />
            </button>
          </div>

          <div className="flex-grow overflow-y-auto p-4 space-y-4 no-scrollbar">
            {cartItems.length === 0 ? (
              <div className="text-center py-20">
                <p className="text-brand-text text-lg">Seu carrinho está vazio.</p>
                <p className="text-gray-500 mt-2">Adicione delícias do nosso cardápio!</p>
              </div>
            ) : (
              cartItems.map((item, index) => (
                <div key={`${item.id}-${item.selectedOption?.name || index}-${JSON.stringify(item.selectedCustomizations || [])}`} className="flex items-start bg-white p-3 rounded-lg shadow-sm">
                  {item.imageUrls && item.imageUrls.length > 0 && (
                      <img src={item.imageUrls[0]} alt={item.name} className="w-20 h-20 object-cover rounded-md flex-shrink-0" />
                  )}
                  <div className={`flex-grow min-w-0 ${item.imageUrls && item.imageUrls.length > 0 ? 'ml-4' : ''}`}>
                    <h3 className="font-semibold text-brand-text truncate">{item.name}</h3>

                    {item.selectedOption && (
                        <p className="text-[10px] text-gray-500 font-bold uppercase mb-1">{item.selectedOption.name}</p>
                    )}

                    {/* Exibição das Customizações */}
                    {item.selectedCustomizations && item.selectedCustomizations.length > 0 && (
                      <div className="mb-2 space-y-1">
                        {item.selectedCustomizations.map((group, gIdx) => (
                          <div key={gIdx} className="text-[10px]">
                            <span className="text-brand-primary font-bold">{group.groupName}: </span>
                            <span className="text-gray-500 italic">
                              {group.items.map(opt => `${opt.quantity}x ${opt.name}`).join(', ')}
                            </span>
                          </div>
                        ))}
                      </div>
                    )}

                    <p className="text-brand-primary font-bold">{formatPrice(item.price)}</p>
                    <div className="flex items-center mt-2">
                      <button onClick={() => onUpdateQuantity(item.id, item.quantity - 1, item.selectedOption?.name)} className="p-1 rounded-full bg-brand-secondary/50 text-brand-text"><MinusIcon className="w-4 h-4" /></button>
                      <span className="px-3 font-bold text-brand-text">{item.quantity}</span>
                      <button onClick={() => onUpdateQuantity(item.id, item.quantity + 1, item.selectedOption?.name)} className="p-1 rounded-full bg-brand-secondary/50 text-brand-text"><PlusIcon className="w-4 h-4" /></button>
                    </div>
                  </div>
                  <button onClick={() => onRemoveItem(item.id, item.selectedOption?.name)} className="ml-4 p-2 text-gray-300 hover:text-red-500">
                    <TrashIcon className="w-5 h-5" />
                  </button>
                </div>
              ))
            )}
          </div>

          {cartItems.length > 0 && (
            <div className="p-4 border-t border-brand-secondary bg-white">
              <div className="flex justify-between items-center text-lg font-bold text-brand-text">
                <span>Total:</span>
                <span>{formatPrice(total)}</span>
              </div>
              <button
                onClick={onCheckout}
                className="w-full mt-4 bg-brand-primary text-white font-bold py-3 rounded-lg text-lg hover:bg-brand-primary-dark transition-colors duration-300 shadow-md active:scale-95"
              >
                Continuar
              </button>
            </div>
          )}
        </div>
      </div>
    </>
  );
};

export default Cart;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Product, ProductOption, CustomizationGroup, CustomizationOption, SelectedCustomization } from '../types';
import { ArrowLeftIcon, PlusIcon, MinusIcon, ShoppingBagIcon, ExpandIcon, XIcon, ChevronLeftIcon, ChevronRightIcon, CheckCircleIcon } from './IconComponents';

interface ProductDetailModalProps {
  product: Product | null;
  onClose: () => void;
  onAddToCart: (product: Product, quantity: number, observations?: string, selectedOption?: ProductOption, selectedCustomizations?: SelectedCustomization[]) => void;
}

const ProductDetailModal: React.FC<ProductDetailModalProps> = ({ product, onClose, onAddToCart }) => {
  const [quantity, setQuantity] = useState(1);
  const [observations, setObservations] = useState('');
  const [isImageFullscreen, setIsImageFullscreen] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [selectedOption, setSelectedOption] = useState<ProductOption | null>(null);

  // Estrutura do estado: { [groupId]: { [optionName]: quantity } }
  const [customSelections, setCustomSelections] = useState<Record<string, Record<string, number>>>({});

  useEffect(() => {
    if (product) {
      setQuantity(1);
      setObservations('');
      setIsImageFullscreen(false);
      setCurrentImageIndex(0);
      setCustomSelections({});
      if (product.options && product.options.length > 0) {
          setSelectedOption(product.options[0]);
      } else {
          setSelectedOption(null);
      }
    }
  }, [product]);

  const handleImageNavigation = useCallback((direction: 'next' | 'prev') => {
    if (!product) return;
    const newIndex = direction === 'next'
      ? (currentImageIndex + 1) % product.imageUrls.length
      : (currentImageIndex - 1 + product.imageUrls.length) % product.imageUrls.length;
    setCurrentImageIndex(newIndex);
  }, [currentImageIndex, product]);

  const handleQuantityChange = (amount: number) => {
    setQuantity(prev => {
        const next = Math.max(1, prev + amount);
        if (product?.inventoryEnabled && next > (product.inventoryQuantity || 0)) {
            return prev;
        }
        return next;
    });
  };

  // Cálculo de extras e validação
  const { extraTotal, isAllGroupsValid, formattedCustomizations } = useMemo(() => {
    let total = 0;
    let allValid = true;
    const result: SelectedCustomization[] = [];

    if (!product?.customizationGroups) return { extraTotal: 0, isAllGroupsValid: true, formattedCustomizations: [] };

    for (const group of product.customizationGroups) {
      const groupSelections = customSelections[group.id] || {};
      const totalInGroup = Object.values(groupSelections).reduce((a: number, b: number) => a + b, 0);

      if (totalInGroup < group.min || totalInGroup > group.max) {
        allValid = false;
      }

      const items = [];
      for (const [optName, optQty] of Object.entries(groupSelections)) {
        if (optQty > 0) {
          const opt = group.options.find(o => o.name === optName);
          if (opt) {
            total += (opt.priceExtra * optQty);
            items.push({ name: opt.name, quantity: optQty, priceExtra: opt.priceExtra });
          }
        }
      }
      if (items.length > 0) {
        result.push({ groupName: group.name, items });
      }
    }
    return { extraTotal: total, isAllGroupsValid: allValid, formattedCustomizations: result };
  }, [product, customSelections]);

  const handleCustomOptionChange = (group: CustomizationGroup, option: CustomizationOption, delta: number) => {
    setCustomSelections(prev => {
      const groupSelections = { ...(prev[group.id] || {}) };
      const currentQty = groupSelections[option.name] || 0;
      const totalInGroup = Object.values(groupSelections).reduce((a: number, b: number) => a + b, 0);

      // Se for seleção única e cliente clicou em adicionar
      if (group.type === 'single') {
        if (delta > 0) {
          // Limpa o grupo e seleciona apenas este
          return { ...prev, [group.id]: { [option.name]: 1 } };
        } else {
          // Deseleciona
          return { ...prev, [group.id]: {} };
        }
      }

      // Se for contador (múltiplos itens)
      const newQty = Math.max(0, currentQty + delta);

      // Bloqueia se ultrapassar o máximo do grupo
      if (delta > 0 && totalInGroup >= group.max) {
        return prev;
      }

      return {
        ...prev,
        [group.id]: {
          ...groupSelections,
          [option.name]: newQty
        }
      };
    });
  };

  const handleAddToCartClick = () => {
    if (product) {
        if (product.options && product.options.length > 0 && !selectedOption) {
            alert("Por favor, selecione uma opção.");
            return;
        }

        if (!isAllGroupsValid) {
            alert("Por favor, preencha as opções obrigatórias.");
            return;
        }

      onAddToCart(product, quantity, observations, selectedOption || undefined, formattedCustomizations);
    }
  };

  const formatPrice = (price: number) => {
    return price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  if (!product) return null;

  const basePrice = selectedOption ? selectedOption.price : product.price;
  const totalPrice = (basePrice + extraTotal) * quantity;
  const isSoldOut = product.inventoryEnabled && (product.inventoryQuantity || 0) <= 0;

  return (
    <>
      {isImageFullscreen && (
        <div className="fixed inset-0 bg-black z-[70] flex items-center justify-center p-4" onClick={() => setIsImageFullscreen(false)}>
            <button className="absolute top-4 right-4 text-white p-2"><XIcon className="w-8 h-8"/></button>
            <img src={product.imageUrls[currentImageIndex]} className="max-h-full max-w-full object-contain" alt={product.name}/>
        </div>
      )}

      <div className="fixed inset-0 z-50 bg-white flex flex-col animate-slide-in-up no-scrollbar overflow-y-auto">
        <style>{`.animate-slide-in-up { animation: slideInUp 0.3s ease-out; } @keyframes slideInUp { from { transform: translateY(100%); } to { transform: translateY(0); } }`}</style>

        <div className="flex-1 pb-32"> 
          <div className="max-w-2xl mx-auto w-full">
            {product.imageUrls && product.imageUrls.length > 0 ? (
              <div className="relative aspect-square sm:aspect-video w-full bg-gray-100">
                  <img 
                    src={product.imageUrls[currentImageIndex]} 
                    alt={product.name} 
                    className={`w-full h-full object-cover ${isSoldOut ? 'grayscale' : ''}`}
                    onClick={() => setIsImageFullscreen(true)}
                  />
                  <button onClick={onClose} className="absolute top-4 left-4 p-2 bg-white/80 rounded-full shadow-md"><ArrowLeftIcon className="w-6 h-6"/></button>
                  {isSoldOut && <div className="absolute inset-0 bg-black/40 flex items-center justify-center"><span className="bg-red-600 text-white font-bold px-6 py-2 rounded uppercase tracking-widest">Esgotado</span></div>}
              </div>
            ) : (
               <div className="p-4 border-b flex items-center sticky top-0 bg-white z-20">
                  <button onClick={onClose} className="p-2 -ml-2"><ArrowLeftIcon className="w-6 h-6"/></button>
                  <h1 className="ml-2 text-lg font-bold text-brand-text truncate">{product.name}</h1>
              </div>
            )}

            <div className="p-6 space-y-8">
                <div>
                    <h1 className="text-2xl font-bold text-brand-text">{product.name}</h1>
                    <p className="text-brand-text-light text-base mt-2 leading-relaxed">{product.description}</p>
                </div>

                {/* Tamanhos / Opções Base */}
                {product.options && product.options.length > 0 && !isSoldOut && (
                    <div className="space-y-4">
                        <h3 className="text-base font-bold text-brand-text border-l-4 border-brand-primary pl-3">Escolha uma opção</h3>
                        <div className="grid gap-3">
                            {product.options.map((option, index) => (
                                <button 
                                    key={index} 
                                    onClick={() => setSelectedOption(option)}
                                    className={`flex items-center justify-between p-4 rounded-xl border transition-all ${selectedOption?.name === option.name ? 'border-brand-primary bg-brand-secondary/20 ring-1 ring-brand-primary' : 'border-gray-200'}`}
                                >
                                    <span className="font-bold text-brand-text">{option.name}</span>
                                    <span className="font-bold text-brand-primary">{formatPrice(option.price)}</span>
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* Grupos de Personalização (Estilo Dino) */}
                {product.customizationGroups?.map((group) => {
                  const groupSelections = customSelections[group.id] || {};
                  const totalInGroup = Object.values(groupSelections).reduce((a, b) => a + b, 0);
                  const isValid = totalInGroup >= group.min && totalInGroup <= group.max;

                  return (
                    <div key={group.id} className="pt-6 border-t border-gray-100 space-y-4 animate-fade-in">
                        <div className="flex justify-between items-start">
                            <div>
                                <h3 className="text-base font-bold text-brand-text">{group.name}</h3>
                                <p className="text-xs text-gray-400">
                                    {group.min === group.max ? `Escolha ${group.min}` : `Escolha de ${group.min} a ${group.max}`}
                                </p>
                            </div>
                            {isValid ? (
                                <CheckCircleIcon className="w-5 h-5 text-green-500" />
                            ) : (
                                <span className="text-[10px] font-black bg-amber-100 text-amber-700 px-2 py-0.5 rounded uppercase">Obrigatório</span>
                            )}
                        </div>

                        <div className="space-y-3">
                            {group.options.map((opt) => {
                                const qty = groupSelections[opt.name] || 0;
                                return (
                                    <div key={opt.name} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${qty > 0 ? 'border-brand-primary/50 bg-brand-secondary/10' : 'border-gray-50'}`}>
                                        <div className="flex-grow pr-4">
                                            <p className="text-sm font-bold text-brand-text">{opt.name}</p>
                                            {opt.priceExtra > 0 && <p className="text-xs text-brand-accent font-bold">+{formatPrice(opt.priceExtra)}</p>}
                                        </div>

                                        <div className="flex items-center bg-white rounded-lg border border-gray-100 shadow-sm">
                                            <button 
                                              onClick={() => handleCustomOptionChange(group, opt, -1)}
                                              className={`p-2 transition-opacity ${qty === 0 ? 'opacity-20' : 'text-brand-text hover:bg-gray-50'}`}
                                            >
                                                <MinusIcon className="w-4 h-4"/>
                                            </button>
                                            <span className="px-3 text-sm font-black w-10 text-center text-brand-text">{qty}</span>
                                            <button 
                                              onClick={() => handleCustomOptionChange(group, opt, 1)}
                                              className={`p-2 transition-opacity ${totalInGroup >= group.max && group.type !== 'single' ? 'opacity-20' : 'text-brand-primary hover:bg-gray-50'}`}
                                            >
                                                <PlusIcon className="w-4 h-4"/>
                                            </button>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                  );
                })}

                {!isSoldOut && (
                    <div className="pt-6 border-t border-gray-100">
                        <label className="block text-sm font-bold text-brand-text mb-2">Observações</label>
                        <textarea 
                            value={observations}
                            onChange={(e) => setObservations(e.target.value)}
                            rows={3}
                            placeholder="Algum pedido especial? (Ex: Sem amendoim)"
                            className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-brand-primary outline-none"
                        />
                    </div>
                )}
            </div>
          </div>
        </div>

        {!isSoldOut && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 p-4 shadow-xl z-30">
                <div className="max-w-2xl mx-auto flex items-center gap-4">
                    <div className="flex items-center bg-gray-100 rounded-full p-1">
                      <button onClick={() => handleQuantityChange(-1)} disabled={quantity === 1} className="p-3 disabled:opacity-30"><MinusIcon className="w-5 h-5" /></button>
                      <span className="px-4 text-xl font-black w-12 text-center text-brand-text">{quantity}</span>
                      <button onClick={() => handleQuantityChange(1)} className="p-3"><PlusIcon className="w-5 h-5" /></button>
                    </div>

                    <button 
                      onClick={handleAddToCartClick}
                      disabled={!isAllGroupsValid}
                      className="flex-grow bg-brand-primary text-white font-black py-4 px-6 rounded-2xl flex items-center justify-between shadow-lg hover:brightness-105 active:scale-95 transition-all disabled:opacity-50"
                    >
                        <span className="flex items-center gap-2">
                           <ShoppingBagIcon className="w-6 h-6" />
                           Adicionar
                        </span>
                        <span>{formatPrice(totalPrice)}</span>
                    </button>
                </div>
            </div>
        )}
      </div>
    </>
  );
};

export default ProductDetailModal;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import type { Product, ProductOption, CategoryMetadata, CustomizationGroup, CustomizationOption } from '../types';
import { TrashIcon, SearchIcon, DragHandleIcon, CopyIcon, PlusIcon, ChevronRightIcon, XIcon as CloseIcon } from './IconComponents';

const CustomizationGroupEditor: React.FC<{
    groups: CustomizationGroup[];
    onChange: (groups: CustomizationGroup[]) => void;
}> = ({ groups, onChange }) => {
    const addGroup = () => {
        const newGroup: CustomizationGroup = {
            id: `group-${Date.now()}`,
            name: '',
            min: 0,
            max: 1,
            type: 'single',
            options: []
        };
        onChange([...groups, newGroup]);
    };

    const updateGroup = (id: string, data: Partial<CustomizationGroup>) => {
        onChange(groups.map(g => g.id === id ? { ...g, ...data } : g));
    };

    const removeGroup = (id: string) => {
        onChange(groups.filter(g => g.id !== id));
    };

    const addOptionToGroup = (groupId: string) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                return {
                    ...g,
                    options: [...g.options, { name: '', priceExtra: 0 }]
                };
            }
            return g;
        }));
    };

    const updateOptionInGroup = (groupId: string, optIndex: number, data: Partial<CustomizationOption>) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                const newOpts = [...g.options];
                newOpts[optIndex] = { ...newOpts[optIndex], ...data };
                return { ...g, options: newOpts };
            }
            return g;
        }));
    };

    const removeOptionFromGroup = (groupId: string, optIndex: number) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                return { ...g, options: g.options.filter((_, i) => i !== optIndex) };
            }
            return g;
        }));
    };

    return (
        <div className="space-y-6 mt-8 border-t pt-8">
            <div className="flex items-center justify-between">
                <div>
                    <h3 className="text-sm font-black text-gray-700 uppercase tracking-widest">Personalizações & Adicionais</h3>
                    <p className="text-[10px] text-gray-400">Configure grupos como "Escolha a Massa" ou "Extras Pagos".</p>
                </div>
                <button type="button" onClick={addGroup} className="text-xs font-bold text-brand-primary bg-brand-secondary/30 px-3 py-1.5 rounded-full hover:bg-brand-primary hover:text-white transition-all">
                    + Adicionar Grupo
                </button>
            </div>

            <div className="space-y-6">
                {groups.map((group) => (
                    <div key={group.id} className="bg-gray-50 p-4 rounded-xl border border-gray-200 relative animate-fade-in">
                        <button onClick={() => removeGroup(group.id)} className="absolute top-3 right-3 text-gray-300 hover:text-red-500 transition-colors">
                            <TrashIcon className="w-5 h-5"/>
                        </button>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                            <div>
                                <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Título do Grupo</label>
                                <input 
                                    type="text" 
                                    value={group.name} 
                                    onChange={e => updateGroup(group.id, { name: e.target.value })}
                                    placeholder="Ex: Escolha a Massa"
                                    className="w-full px-3 py-2 border rounded-lg text-sm bg-white shadow-sm"
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Mínimo</label>
                                    <input type="number" min="0" value={group.min} onChange={e => updateGroup(group.id, { min: parseInt(e.target.value) })} className="w-full px-3 py-2 border rounded-lg text-sm bg-white shadow-sm"/>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Máximo</label>
                                    <input type="number" min="1" value={group.max} onChange={e => updateGroup(group.id, { max: parseInt(e.target.value), type: parseInt(e.target.value) > 1 ? 'counter' : 'single' })} className="w-full px-3 py-2 border rounded-lg text-sm bg-white shadow-sm"/>
                                </div>
                            </div>
                        </div>

                        <div className="space-y-2">
                            {group.options.map((opt, idx) => (
                                <div key={idx} className="flex gap-2 items-center bg-white p-2 rounded-lg border border-gray-100 shadow-sm">
                                    <input 
                                        type="text" 
                                        value={opt.name} 
                                        onChange={e => updateOptionInGroup(group.id, idx, { name: e.target.value })} 
                                        placeholder="Nome do item"
                                        className="flex-grow px-2 py-1 text-sm outline-none border-b border-transparent focus:border-brand-primary"
                                    />
                                    <div className="flex items-center gap-1 bg-gray-50 px-2 py-1 rounded">
                                        <span className="text-[10px] text-gray-400 font-bold">R$</span>
                                        <input 
                                            type="number" 
                                            step="0.01"
                                            value={opt.priceExtra} 
                                            onChange={e => updateOptionInGroup(group.id, idx, { priceExtra: parseFloat(e.target.value) })} 
                                            className="w-16 bg-transparent text-sm font-bold text-brand-primary outline-none"
                                        />
                                    </div>
                                    <button type="button" onClick={() => removeOptionFromGroup(group.id, idx)} className="text-gray-300 hover:text-red-500">
                                        <TrashIcon className="w-4 h-4"/>
                                    </button>
                                </div>
                            ))}
                            <button 
                                type="button" 
                                onClick={() => addOptionToGroup(group.id)} 
                                className="w-full py-2 border-2 border-dashed border-gray-200 rounded-lg text-[10px] text-gray-400 font-bold hover:border-brand-primary hover:text-brand-primary transition-all"
                            >
                                + Adicionar Opção
                            </button>
                        </div>
                    </div>
                ))}
            </div>

            {groups.length === 0 && (
                <div className="text-center py-6 bg-gray-50 rounded-xl border border-dashed border-gray-200">
                    <p className="text-xs text-gray-400 font-medium italic">Nenhuma personalização cadastrada para este produto.</p>
                </div>
            )}
        </div>
    );
};

const SearchableSelect: React.FC<{
    options: CategoryMetadata[];
    value: string;
    onChange: (value: string) => void;
    placeholder: string;
}> = ({ options, value, onChange, placeholder }) => {
    const [isOpen, setIsOpen] = useState(false);
    const [search, setSearch] = useState('');
    const containerRef = useRef<HTMLDivElement>(null);

    const filteredOptions = useMemo(() => {
        return options.filter(opt => 
            opt.name.toLowerCase().includes(search.toLowerCase())
        );
    }, [options, search]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const selectedCategory = options.find(o => o.name === value);

    return (
        <div className="relative mt-1" ref={containerRef}>
            <button
                type="button"
                onClick={() => setIsOpen(!isOpen)}
                className="relative w-full bg-white border border-gray-300 rounded-md shadow-sm pl-3 pr-10 py-2 text-left cursor-default focus:outline-none focus:ring-1 focus:ring-brand-primary focus:border-brand-primary sm:text-sm"
            >
                <span className="block truncate text-gray-900">
                    {selectedCategory ? (
                        <span className="flex items-center gap-2">
                            {selectedCategory.isArchived ? '📦' : '📂'} {selectedCategory.name}
                        </span>
                    ) : (
                        <span className="text-gray-400">{placeholder}</span>
                    )}
                </span>
                <span className="absolute inset-y-0 right-0 flex items-center pr-2 pointer-events-none">
                    <svg className="h-5 w-5 text-gray-400 transform transition-transform duration-200" style={{ transform: isOpen ? 'rotate(-90deg)' : 'rotate(90deg)' }} viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
                    </svg>
                </span>
            </button>

            {isOpen && (
                <div className="absolute z-50 mt-1 w-full bg-white shadow-lg max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                    <div className="sticky top-0 z-10 bg-white px-2 py-2 border-b border-gray-100">
                        <div className="relative">
                            <SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
                            <input
                                type="text"
                                className="block w-full pl-8 pr-3 py-1.5 border border-gray-200 rounded-md text-sm focus:ring-brand-primary focus:border-brand-primary"
                                placeholder="Pesquisar categoria..."
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                                onClick={(e) => e.stopPropagation()}
                                autoFocus
                            />
                        </div>
                    </div>
                    <ul className="max-h-48 overflow-y-auto">
                        {filteredOptions.length > 0 ? (
                            filteredOptions.map((opt) => (
                                <li
                                    key={opt.name}
                                    onClick={() => {
                                        onChange(opt.name);
                                        setIsOpen(false);
                                        setSearch('');
                                    }}
                                    className={`cursor-pointer select-none relative py-2 pl-3 pr-9 hover:bg-brand-secondary/30 transition-colors ${
                                        value === opt.name ? 'bg-brand-secondary/50 text-brand-primary font-semibold' : 'text-gray-900'
                                    }`}
                                >
                                    <div className="flex items-center gap-2">
                                        <span className="text-xs">{opt.isArchived ? '📦' : '📂'}</span>
                                        <span className="block truncate">{opt.name}</span>
                                        {opt.isArchived && <span className="text-[10px] text-gray-400 uppercase font-bold">(Arquivada)</span>}
                                    </div>
                                    {value === opt.name && (
                                        <span className="absolute inset-y-0 right-0 flex items-center pr-4 text-brand-primary">
                                            <svg className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                                <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                                            </svg>
                                        </span>
                                    )}
                                </li>
                            ))
                        ) : (
                            <li className="py-4 text-center text-gray-500 text-sm">Nenhuma categoria encontrada</li>
                        )}
                    </ul>
                </div>
            )}
        </div>
    );
};

