                </p>
                <div className="mt-6 flex justify-center gap-4">
                    <button onClick={onCancel} className="px-6 py-2 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50">
                        Cancelar
                    </button>
                    <button onClick={onConfirm} className="px-6 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-brand-primary hover:bg-brand-primary-dark">
                        Apagar
                    </button>
                </div>
            </div>
        </div>
    );
};

const DeleteCategoryConfirmationModal: React.FC<{
    categoryName: string;
    onCancel: () => void;
    onConfirm: () => void;
}> = ({ categoryName, onCancel, onConfirm }) => {
    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-[100] flex items-center justify-center p-4">
            <div className="bg-white rounded-lg shadow-xl max-w-sm w-full p-6 text-center animate-fade-in-up">
                <h3 className="text-lg font-bold text-brand-text">Confirmar Exclusão</h3>
                <p className="text-sm text-gray-500 mt-2">
                    Você tem certeza que deseja apagar a categoria <span className="font-semibold">"{categoryName}"</span>? Esta ação não pode ser desfeita.
                </p>
                <div className="mt-6 flex justify-center gap-4">
                    <button onClick={onCancel} className="px-6 py-2 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50">
                        Cancelar
                    </button>
                    <button onClick={onConfirm} className="px-6 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-brand-primary hover:bg-brand-primary-dark">
                        Apagar
                    </button>
                </div>
            </div>
        </div>
    );
};

const ProductsView: React.FC<ProductsViewProps> = ({ 
    products, 
    categories, 
    onAddProduct, 
    onUpdateProduct, 
    onDeleteProduct, 
    onAddCategory, 
    onDeleteCategory, 
    onUpdateCategoryOrder,
    onToggleCategoriesArchive
}) => {
  const activeCategoriesOnly = useMemo(() => categories.filter(c => !c.isArchived), [categories]);
  const archivedCategoriesOnly = useMemo(() => categories.filter(c => c.isArchived), [categories]);

  const sortedCategoriesForSelect = useMemo(() => {
    return [...activeCategoriesOnly, ...archivedCategoriesOnly];
  }, [activeCategoriesOnly, archivedCategoriesOnly]);

  const initialFormState = {
    name: '',
    description: '',
    price: '',
    originalPrice: '',
    promotionalTag: '',
    category: '',
    imageUrls: '',
    leadTimeDays: '0',
    inventoryEnabled: false,
    inventoryQuantity: '0'
  };

  const [productForm, setProductForm] = useState(initialFormState);
  const [productOptions, setProductOptions] = useState<ProductOption[]>([]);
  const [customizationGroups, setCustomizationGroups] = useState<CustomizationGroup[]>([]);
  const [newOption, setNewOption] = useState({ name: '', price: '' });

  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [productToDelete, setProductToDelete] = useState<Product | null>(null);
  const [categoryToDelete, setCategoryToDelete] = useState<string | null>(null);
  const [newCategory, setNewCategory] = useState('');
  const [productSearchQuery, setProductSearchQuery] = useState('');
  const [selectedCategoryFilter, setSelectedCategoryFilter] = useState('Todas');

  const [categoryTab, setCategoryTab] = useState<'active' | 'archived'>('active');
  const [productViewTab, setProductViewTab] = useState<'active' | 'inactive'>('active');
  const [selectedCategoryNames, setSelectedCategoryNames] = useState<string[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  useEffect(() => {
    if (productToDelete || categoryToDelete || isProductModalOpen) {
        document.body.style.overflow = 'hidden';
        return () => {
            document.body.style.overflow = 'auto';
        };
    }
  }, [productToDelete, categoryToDelete, isProductModalOpen]);

  useEffect(() => {
    if (productOptions.length > 0 && isProductModalOpen) {
        const minPrice = Math.min(...productOptions.map(o => o.price));
        setProductForm(prev => ({ ...prev, price: String(minPrice) }));
    }
  }, [productOptions, isProductModalOpen]);

  const handleProductFormChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as HTMLInputElement;
    if (type === 'checkbox') {
        setProductForm(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
    } else {
        setProductForm(prev => ({ ...prev, [name]: value }));
    }
  };

  const openAddProductModal = () => {
    setEditingProduct(null);
    setProductForm(initialFormState);
    setProductOptions([]);
    setCustomizationGroups([]);
    setIsProductModalOpen(true);
  };

  const handleEditClick = (product: Product) => {
    setEditingProduct(product);
    setProductForm({
        name: product.name,
        description: product.description,
        price: String(product.price),
        originalPrice: (product.originalPrice && product.originalPrice > 0) ? String(product.originalPrice) : '',
        promotionalTag: product.promotionalTag || '',
        category: product.category,
        imageUrls: product.imageUrls ? product.imageUrls.join('\n') : '',
        leadTimeDays: String(product.leadTimeDays || 0),
        inventoryEnabled: !!product.inventoryEnabled,
        inventoryQuantity: String(product.inventoryQuantity || 0)
    });
    setProductOptions(product.options || []);
    setCustomizationGroups(product.customizationGroups || []);
    setIsProductModalOpen(true);
  };

  const handleDuplicateClick = (product: Product) => {
    setProductForm({
        name: `${product.name} (Cópia)`,
        description: product.description,
        price: String(product.price),
        originalPrice: (product.originalPrice && product.originalPrice > 0) ? String(product.originalPrice) : '',
        promotionalTag: product.promotionalTag || '',
        category: product.category,
        imageUrls: product.imageUrls ? product.imageUrls.join('\n') : '',
        leadTimeDays: String(product.leadTimeDays || 0),
        inventoryEnabled: !!product.inventoryEnabled,
        inventoryQuantity: String(product.inventoryQuantity || 0)
    });
    setProductOptions(product.options || []);
    setCustomizationGroups(product.customizationGroups || []);
    setEditingProduct(null); 
    setIsProductModalOpen(true);
  };

  const confirmDelete = async () => {
    if (!productToDelete) return;
    setMessage(null);
    try {
        await onDeleteProduct(productToDelete.id);
        setMessage({ type: 'success', text: 'Produto apagado!' });
    } catch (error) {
        setMessage({ type: 'error', text: 'Erro ao apagar.' });
    } finally {
        setProductToDelete(null);
        setTimeout(() => setMessage(null), 3000);
    }
  };

  const closeProductModal = () => {
    setIsProductModalOpen(false);
    setEditingProduct(null);
    setProductForm(initialFormState);
    setProductOptions([]);
    setCustomizationGroups([]);
    setMessage(null);
  };

  const handleAddOption = () => {
      if (!newOption.name || !newOption.price) return;
      setProductOptions([...productOptions, { name: newOption.name, price: parseFloat(newOption.price) }]);
      setNewOption({ name: '', price: '' });
  };

  const handleRemoveOption = (index: number) => {
      setProductOptions(productOptions.filter((_, i) => i !== index));
  };

  const handleProductSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    setIsSubmitting(true);
    const imageUrlsArray = productForm.imageUrls.split('\n').map(url => url.trim()).filter(url => url);

    try {
      let effectivePrice = parseFloat(productForm.price);
      if (productOptions.length > 0) {
          effectivePrice = Math.min(...productOptions.map(o => o.price));
      }

      const productData: any = {
        name: productForm.name,
        description: productForm.description,
        price: effectivePrice,
        category: productForm.category,
        imageUrls: imageUrlsArray,
        leadTimeDays: parseInt(productForm.leadTimeDays, 10) || 0,
        options: productOptions,
        customizationGroups: customizationGroups,
        inventoryEnabled: productForm.inventoryEnabled,
        inventoryQuantity: parseInt(productForm.inventoryQuantity, 10) || 0,
      };

      if (editingProduct) productData.id = editingProduct.id;

      const origPrice = parseFloat(productForm.originalPrice);
      productData.originalPrice = !isNaN(origPrice) && origPrice > 0 ? origPrice : null;
      productData.promotionalTag = productForm.promotionalTag?.trim() || null;

      if (editingProduct) {
        await onUpdateProduct(productData);
        setMessage({ type: 'success', text: 'Atualizado!' });
      } else {
        await onAddProduct(productData);
        setMessage({ type: 'success', text: 'Cadastrado!' });
      }

      setTimeout(closeProductModal, 1000);
    } catch (error) {
        setMessage({ type: 'error', text: 'Ocorreu um erro.' });
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleAddCategory = async () => {
    if (!newCategory.trim()) return;
    setIsSubmitting(true);
    try {
        await onAddCategory(newCategory);
        setNewCategory('');
        setMessage({ type: 'success', text: 'Categoria adicionada!' });
    } catch (e) {
        setMessage({ type: 'error', text: 'Erro.' });
    } finally {
        setIsSubmitting(false);
        setTimeout(() => setMessage(null), 3000);
    }
  };

  const handleDeleteCategory = (categoryName: string) => {
      if (products.some(p => p.category === categoryName)) {
          alert(`A categoria "${categoryName}" está em uso e não pode ser removida.`);
          return;
      }
      setCategoryToDelete(categoryName);
  };

  const confirmDeleteCategory = async () => {
    if (!categoryToDelete) return;
    setIsSubmitting(true);
    try {
        await onDeleteCategory(categoryToDelete);
    } catch (e) {
        setMessage({ type: 'error', text: 'Erro ao apagar.' });
    } finally {
        setIsSubmitting(false);
        setCategoryToDelete(null);
    }
  };

  const handleSort = () => {
      if (dragItem.current === null || dragOverItem.current === null) return;
      const categoriesCopy = [...categories];
      const activeCats = categories.filter(c => !c.isArchived);
      const realDragIdx = categories.findIndex(c => c.name === activeCats[dragItem.current!].name);
      const realTargetIdx = categories.findIndex(c => c.name === activeCats[dragOverItem.current!].name);
      const item = categoriesCopy.splice(realDragIdx, 1)[0];
      categoriesCopy.splice(realTargetIdx, 0, item);
      dragItem.current = null;
      dragOverItem.current = null;
      onUpdateCategoryOrder(categoriesCopy);
  };

  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(productSearchQuery.toLowerCase());
    const isArchived = categories.find(c => c.name === p.category)?.isArchived;
    if (productViewTab === 'active' && isArchived) return false;
    if (productViewTab === 'inactive' && !isArchived) return false;
    return matchesSearch && (selectedCategoryFilter === 'Todas' || p.category === selectedCategoryFilter);
  });

  const inputStyles = "mt-1 block w-full px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm text-gray-900 focus:ring-brand-primary outline-none focus:ring-2 sm:text-sm";

  return (
    <>
        {productToDelete && (
            <DeleteConfirmationModal product={productToDelete} onCancel={() => setProductToDelete(null)} onConfirm={confirmDelete}/>
        )}
        {categoryToDelete && (
            <DeleteCategoryConfirmationModal categoryName={categoryToDelete} onCancel={() => setCategoryToDelete(null)} onConfirm={confirmDeleteCategory}/>
        )}

        {isProductModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-xl shadow-2xl max-w-3xl w-full max-h-[90vh] overflow-hidden flex flex-col animate-slide-in-up no-scrollbar">
                    <header className="p-4 border-b bg-gray-50 flex justify-between items-center">
                        <h2 className="text-xl font-bold text-brand-text">{editingProduct ? 'Editar Produto' : 'Novo Produto'}</h2>
                        <button onClick={closeProductModal} className="p-2 hover:bg-gray-200 rounded-full text-gray-400"><CloseIcon className="w-6 h-6"/></button>
                    </header>
                    <div className="flex-1 overflow-y-auto p-6 no-scrollbar">
                        <form onSubmit={handleProductSubmit} className="space-y-6">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="space-y-4">
                                    <div><label className="text-xs font-bold text-gray-500 uppercase">Nome</label><input type="text" value={productForm.name} onChange={handleProductFormChange} name="name" className={inputStyles} required /></div>
                                    <div><label className="text-xs font-bold text-gray-500 uppercase">Descrição</label><textarea value={productForm.description} onChange={handleProductFormChange} name="description" rows={3} className={inputStyles} required /></div>
                                    <div><label className="text-xs font-bold text-gray-500 uppercase">Categoria</label><SearchableSelect options={sortedCategoriesForSelect} value={productForm.category} onChange={(val) => setProductForm(prev => ({ ...prev, category: val }))} placeholder="Selecione..."/></div>
                                </div>
                                <div className="space-y-4">
                                    <div><label className="text-xs font-bold text-gray-500 uppercase">Imagens (URLs)</label><textarea value={productForm.imageUrls} onChange={handleProductFormChange} name="imageUrls" rows={3} className={inputStyles} placeholder="Uma URL por linha"/></div>
                                    <div className="grid grid-cols-2 gap-2">
                                        <div><label className="text-xs font-bold text-gray-500 uppercase">Preço Venda</label><input type="number" step="0.01" value={productForm.price} onChange={handleProductFormChange} name="price" className={inputStyles} readOnly={productOptions.length > 0} /></div>
                                        <div><label className="text-xs font-bold text-gray-500 uppercase">Dias Antecedência</label><input type="number" value={productForm.leadTimeDays} onChange={handleProductFormChange} name="leadTimeDays" className={inputStyles} /></div>
                                    </div>
                                    <div className="flex items-center gap-2 p-2 bg-gray-50 rounded border">
                                        <input type="checkbox" id="inv" name="inventoryEnabled" checked={!!productForm.inventoryEnabled} onChange={handleProductFormChange} className="w-4 h-4 text-brand-primary" />
                                        <label htmlFor="inv" className="text-xs font-bold text-gray-700">Controle Estoque</label>
                                        {productForm.inventoryEnabled && <input type="number" value={productForm.inventoryQuantity} name="inventoryQuantity" onChange={handleProductFormChange} className="w-16 ml-auto px-2 py-1 border rounded text-xs"/>}
                                    </div>
                                </div>
                            </div>

                            {/* Variantes de Tamanho */}
                            <div className="bg-gray-50 p-4 rounded-xl border border-gray-200">
                                <h4 className="text-xs font-black text-gray-400 uppercase mb-4 tracking-widest">Tamanhos / Variantes (Opcional)</h4>
                                <div className="space-y-2 mb-4">
                                    {productOptions.map((opt, i) => (
                                        <div key={i} className="flex justify-between bg-white p-2 border rounded-lg">
                                            <span className="text-sm font-bold">{opt.name} - R$ {opt.price.toFixed(2)}</span>
                                            <button type="button" onClick={() => handleRemoveOption(i)}><TrashIcon className="w-4 h-4 text-red-400"/></button>
                                        </div>
                                    ))}
                                </div>
                                <div className="flex gap-2">
                                    <input type="text" placeholder="Ex: Pequeno" value={newOption.name} onChange={e => setNewOption({...newOption, name: e.target.value})} className="flex-grow px-2 py-1 border rounded text-sm"/>
                                    <input type="number" placeholder="0,00" value={newOption.price} onChange={e => setNewOption({...newOption, price: e.target.value})} className="w-24 px-2 py-1 border rounded text-sm"/>
                                    <button type="button" onClick={handleAddOption} className="bg-brand-primary text-white px-3 py-1 rounded text-xs">Add</button>
                                </div>
                            </div>

                            {/* EDITOR DE PERSONALIZAÇÃO (ESTILO DINO) */}
                            <CustomizationGroupEditor groups={customizationGroups} onChange={setCustomizationGroups} />

                            <div className="flex gap-3">
                                <button type="submit" disabled={isSubmitting} className="flex-grow bg-brand-primary text-white py-3 rounded-xl font-bold shadow-lg disabled:opacity-50">
                                    {isSubmitting ? 'Salvando...' : (editingProduct ? 'Salvar Alterações' : 'Cadastrar Produto')}
                                </button>
                                <button type="button" onClick={closeProductModal} className="px-6 border rounded-xl font-bold text-gray-500">Cancelar</button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        )}

        <div className="space-y-8">
            <div className="max-w-3xl mx-auto flex justify-between items-center bg-white rounded-xl shadow-sm p-4 border border-gray-100">
                <h2 className="text-xl font-bold text-brand-text">Gestão de Produtos</h2>
                <button onClick={openAddProductModal} className="bg-brand-primary text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2"><PlusIcon className="w-5 h-5"/>Novo Produto</button>
            </div>

            <div className="max-w-3xl mx-auto bg-white rounded-xl shadow-md p-6">
                <h2 className="text-2xl font-bold text-brand-text mb-6">Categorias</h2>
                <div className="flex gap-2 mb-6">
                    <input type="text" value={newCategory} onChange={e => setNewCategory(e.target.value)} className={inputStyles + ' flex-grow'} placeholder="Nova categoria..." />
                    <button onClick={handleAddCategory} className="bg-brand-primary text-white px-4 rounded-lg font-bold">Add</button>
                </div>
                <div className="border-b mb-4 flex gap-4">
                    <button onClick={() => setCategoryTab('active')} className={`py-2 px-1 border-b-2 font-bold text-sm ${categoryTab === 'active' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}>Ativas</button>
                    <button onClick={() => setCategoryTab('archived')} className={`py-2 px-1 border-b-2 font-bold text-sm ${categoryTab === 'archived' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}>Arquivadas</button>
                </div>
                <div className="space-y-2">
                    {(categoryTab === 'active' ? activeCategoriesOnly : archivedCategoriesOnly).map((cat, i) => (
                        <div key={cat.name} draggable={categoryTab === 'active'} onDragStart={() => dragItem.current = i} onDragEnter={() => dragOverItem.current = i} onDragEnd={handleSort} onDragOver={e => e.preventDefault()} className="flex justify-between items-center p-3 bg-gray-50 border rounded-lg">
                            <span className="flex items-center gap-2 text-sm font-medium"><DragHandleIcon className="w-4 h-4 text-gray-300"/>{cat.name}</span>
                            <div className="flex gap-3">
                                <button onClick={() => onToggleCategoriesArchive([cat.name], !cat.isArchived)} title={cat.isArchived ? "Restaurar" : "Arquivar"}>
                                    <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4" /></svg>
                                </button>
                                <button onClick={() => handleDeleteCategory(cat.name)}><TrashIcon className="w-5 h-5 text-red-300"/></button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="max-w-3xl mx-auto bg-white rounded-xl shadow-md p-6">
                <h2 className="text-2xl font-bold text-brand-text mb-6">Produtos</h2>
                <div className="flex gap-4 mb-6 flex-wrap">
                    <div className="relative flex-grow min-w-[200px]"><SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-300"/><input type="text" value={productSearchQuery} onChange={e => setProductSearchQuery(e.target.value)} placeholder="Pesquisar produtos..." className="w-full pl-10 pr-4 py-2 bg-gray-50 rounded-full text-sm outline-none focus:ring-2 focus:ring-brand-primary"/></div>
                    <select value={selectedCategoryFilter} onChange={e => setSelectedCategoryFilter(e.target.value)} className="bg-gray-50 rounded-full px-4 py-2 text-sm outline-none">
                        <option value="Todas">Todas as Categorias</option>
                        {activeCategoriesOnly.map(c => <option key={c.name} value={c.name}>{c.name}</option>)}
                    </select>
                </div>
                <div className="border-b mb-6 flex gap-4">
                    <button onClick={() => setProductViewTab('active')} className={`py-2 px-1 border-b-2 font-bold text-sm ${productViewTab === 'active' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}>Visíveis</button>
                    <button onClick={() => setProductViewTab('inactive')} className={`py-2 px-1 border-b-2 font-bold text-sm ${productViewTab === 'inactive' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}>Arquivados (Categoria)</button>
                </div>
                <div className="space-y-3">
                    {filteredProducts.map(p => (
                        <div key={p.id} className="flex justify-between items-center p-3 bg-white border rounded-xl hover:shadow-sm transition-shadow">
                            <div className="flex items-center gap-3 min-w-0">
                                {p.imageUrls?.[0] ? <img src={p.imageUrls[0]} className="w-12 h-12 object-cover rounded-lg"/> : <div className="w-12 h-12 bg-gray-100 rounded-lg"/>}
                                <div className="min-w-0">
                                    <p className="font-bold text-sm truncate">{p.name}</p>
                                    <p className="text-[10px] text-gray-400 font-bold uppercase">{p.category}</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-3">
                                <button onClick={() => handleDuplicateClick(p)} title="Duplicar"><CopyIcon className="w-4 h-4 text-gray-300"/></button>
                                <button onClick={() => handleEditClick(p)} className="text-xs font-bold text-brand-primary hover:underline">Editar</button>
                                <button onClick={() => setProductToDelete(p)} className="text-xs font-bold text-red-400 hover:underline">Apagar</button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    </>
  );
};

export default ProductsView;

import * as https from "https";
import { Buffer } from "buffer";

interface ApiRequest {
    method?: string;
    body: any;
}

interface ApiResponse {
    setHeader: (key: string, value: any) => void;
    status: (code: number) => {
        json: (data: any) => void;
        end: (message?: string) => void;
    };
}

const formatPrice = (price: number) => (price || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

const formatDisplayDate = (dateString: string) => {
    if (!dateString) return 'N/A';
    try {
        const date = new Date(dateString + 'T00:00:00');
        return new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' }).format(date);
    } catch (e) {
        return dateString;
    }
}

const escapeHtml = (unsafe: string) => {
    return (unsafe || '')
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
};

async function sendNewOrderNotification(order: any) {
    const botToken = process.env.TELEGRAM_BOT_TOKEN;
    const chatId = process.env.TELEGRAM_CHAT_ID;

    if (!botToken || !chatId) {
        throw new Error("Telegram Bot Token or Chat ID not configured.");
    }

    const itemsList = (order.items || []).map((item: any) => {
        let text = `• <b>${item.quantity}x</b> ${escapeHtml(item.name)}`;
        if (item.option) {
            text += ` (<i>${escapeHtml(item.option)}</i>)`;
        }

        // Adicionando o detalhamento das customizações
        if (item.selectedCustomizations && item.selectedCustomizations.length > 0) {
            item.selectedCustomizations.forEach((group: any) => {
                const selections = group.items.map((opt: any) => `${opt.quantity}x ${opt.name}`).join(', ');
                text += `\n   └ <b>${escapeHtml(group.groupName)}:</b> ${escapeHtml(selections)}`;
            });
        }

        if (item.observations) {
            text += `\n   <pre>Obs: ${escapeHtml(item.observations)}</pre>`;
        }
        return text;
    }).join("\n\n");

    const address = order.delivery?.address || {};
    const fullAddress = escapeHtml(`${address.street || ''}, ${address.number || ''}${address.complement ? `, ${address.complement}` : ''} - ${address.neighborhood || ''}`);

    const rawWhatsapp = (order.customer?.whatsapp || '').replace(/\D/g, '');
    const whatsappLink = `https://wa.me/55${rawWhatsapp}`;

    const message = `<b>🔔 NOVO PEDIDO - #${order.orderNumber} 🔔</b>

<b>🗓️ DATA AGENDADA:</b>
<b>${formatDisplayDate(order.deliveryDate)}</b>

---

<b>👤 CLIENTE</b>
<b>Nome:</b> ${escapeHtml(order.customer?.name)}
<b>WhatsApp:</b> ${escapeHtml(order.customer?.whatsapp)}
<a href="${whatsappLink}">💬 Iniciar conversa</a>

---

<b>📦 ITENS DO PEDIDO</b>
${itemsList}

---

<b>💰 PAGAMENTO</b>
<b>Subtotal:</b> ${formatPrice(order.total)}
<b>Método:</b> ${escapeHtml(order.paymentMethod)}

---

<b>🚚 ENDEREÇO</b>
${fullAddress}
<b>CEP:</b> ${escapeHtml(address.cep)}`;

    const data = JSON.stringify({
      chat_id: chatId,
      text: message,
      parse_mode: "HTML",
      disable_web_page_preview: true,
      reply_markup: {
        inline_keyboard: [[{ text: "🌐 Abrir Painel", url: "https://pipper-psi.vercel.app/" }]],
      },
    });

    const options = {
      hostname: "api.telegram.org",
      port: 443,
      path: `/bot${botToken}/sendMessage`,
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Content-Length": Buffer.byteLength(data),
      },
    };

    return new Promise<void>((resolve, reject) => {
        const req = https.request(options, (res) => {
          res.on("end", () => res.statusCode! >= 200 && res.statusCode! < 300 ? resolve() : reject());
        });
        req.on("error", (error) => reject(error));
        req.write(data);
        req.end();
    });
}

export default async function handler(req: ApiRequest, res: ApiResponse) {
    if (req.method !== 'POST') return res.status(405).end();
    try {
        await sendNewOrderNotification(req.body.order);
        return res.status(200).json({ message: 'Success' });
    } catch (error: any) {
        return res.status(500).json({ error: 'Error' });
    }
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Product, ProductOption, CustomizationGroup, CustomizationOption, SelectedCustomization } from '../types';
import { ArrowLeftIcon, PlusIcon, MinusIcon, ShoppingBagIcon, ExpandIcon, XIcon, ChevronLeftIcon, ChevronRightIcon, CheckCircleIcon } from './IconComponents';

interface ProductDetailModalProps {
  product: Product | null;
  onClose: () => void;
  onAddToCart: (product: Product, quantity: number, observations?: string, selectedOption?: ProductOption, selectedCustomizations?: SelectedCustomization[]) => void;
}

const ProductDetailModal: React.FC<ProductDetailModalProps> = ({ product, onClose, onAddToCart }) => {
  const [quantity, setQuantity] = useState(1);
  const [observations, setObservations] = useState('');
  const [isImageFullscreen, setIsImageFullscreen] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [selectedOption, setSelectedOption] = useState<ProductOption | null>(null);

  // Estrutura do estado: { [groupId]: { [optionName]: quantity } }
  const [customSelections, setCustomSelections] = useState<Record<string, Record<string, number>>>({});

  useEffect(() => {
    if (product) {
      setQuantity(1);
      setObservations('');
      setIsImageFullscreen(false);
      setCurrentImageIndex(0);
      setCustomSelections({});
      if (product.options && product.options.length > 0) {
          setSelectedOption(product.options[0]);
      } else {
          setSelectedOption(null);
      }
    }
  }, [product]);

  const handleImageNavigation = useCallback((direction: 'next' | 'prev') => {
    if (!product) return;
    const newIndex = direction === 'next'
      ? (currentImageIndex + 1) % product.imageUrls.length
      : (currentImageIndex - 1 + product.imageUrls.length) % product.imageUrls.length;
    setCurrentImageIndex(newIndex);
  }, [currentImageIndex, product]);

  const handleQuantityChange = (amount: number) => {
    // Adding type annotation to fix unknown error in arithmetic/comparison
    setQuantity((prev: number) => {
        const next = Math.max(1, prev + amount);
        // Explicitly casting inventoryQuantity as number for comparison
        const inventoryLimit = (product?.inventoryQuantity || 0) as number;
        if (product?.inventoryEnabled && next > inventoryLimit) {
            return prev;
        }
        return next;
    });
  };

  // Cálculo de extras e validação
  const { extraTotal, isAllGroupsValid, formattedCustomizations } = useMemo(() => {
    let total = 0;
    let allValid = true;
    const result: SelectedCustomization[] = [];

    if (!product?.customizationGroups) return { extraTotal: 0, isAllGroupsValid: true, formattedCustomizations: [] };

    for (const group of product.customizationGroups) {
      const groupSelections = customSelections[group.id] || {};
      // Casting Object.values as number[] to ensure reduce returns a number
      const totalInGroup = (Object.values(groupSelections) as number[]).reduce((a: number, b: number) => a + b, 0);

      if (totalInGroup < group.min || totalInGroup > group.max) {
        allValid = false;
      }

      const items = [];
      for (const [optName, optQty] of Object.entries(groupSelections)) {
        if (optQty > 0) {
          const opt = group.options.find(o => o.name === optName);
          if (opt) {
            total += (opt.priceExtra * optQty);
            items.push({ name: opt.name, quantity: optQty, priceExtra: opt.priceExtra });
          }
        }
      }
      if (items.length > 0) {
        result.push({ groupName: group.name, items });
      }
    }
    return { extraTotal: total as number, isAllGroupsValid: allValid, formattedCustomizations: result };
  }, [product, customSelections]);

  const handleCustomOptionChange = (group: CustomizationGroup, option: CustomizationOption, delta: number) => {
    setCustomSelections(prev => {
      const groupSelections = { ...(prev[group.id] || {}) } as Record<string, number>;
      const currentQty = groupSelections[option.name] || 0;
      // Casting Object.values as number[] to fix unknown error in reduce
      const totalInGroup = (Object.values(groupSelections) as number[]).reduce((a: number, b: number) => a + b, 0);

      // Se for seleção única e cliente clicou em adicionar
      if (group.type === 'single') {
        if (delta > 0) {
          // Limpa o grupo e seleciona apenas este
          return { ...prev, [group.id]: { [option.name]: 1 } };
        } else {
          // Deseleciona
          return { ...prev, [group.id]: {} };
        }
      }

      // Se for contador (múltiplos itens)
      const newQty = Math.max(0, currentQty + delta);

      // Bloqueia se ultrapassar o máximo do grupo, treating group.max as number
      if (delta > 0 && totalInGroup >= (group.max as number)) {
        return prev;
      }

      return {
        ...prev,
        [group.id]: {
          ...groupSelections,
          [option.name]: newQty
        }
      };
    });
  };

  const handleAddToCartClick = () => {
    if (product) {
        if (product.options && product.options.length > 0 && !selectedOption) {
            alert("Por favor, selecione uma opção.");
            return;
        }

        if (!isAllGroupsValid) {
            alert("Por favor, preencha as opções obrigatórias.");
            return;
        }

      onAddToCart(product, quantity, observations, selectedOption || undefined, formattedCustomizations);
    }
  };

  const formatPrice = (price: number) => {
    return price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  if (!product) return null;

  // Explicitly casting values as number to fix unknown arithmetic errors
  const basePriceVal = (selectedOption ? selectedOption.price : product.price) as number;
  const extraTotalVal = extraTotal as number;
  const quantityVal = quantity as number;
  const totalPrice = (basePriceVal + extraTotalVal) * quantityVal;
  const isSoldOut = product.inventoryEnabled && (product.inventoryQuantity || 0) <= 0;

  return (
    <>
      {isImageFullscreen && (
        <div className="fixed inset-0 bg-black z-[70] flex items-center justify-center p-4" onClick={() => setIsImageFullscreen(false)}>
            <button className="absolute top-4 right-4 text-white p-2"><XIcon className="w-8 h-8"/></button>
            <img src={product.imageUrls[currentImageIndex]} className="max-h-full max-w-full object-contain" alt={product.name}/>
        </div>
      )}

      <div className="fixed inset-0 z-50 bg-white flex flex-col animate-slide-in-up no-scrollbar overflow-y-auto">
        <style>{`.animate-slide-in-up { animation: slideInUp 0.3s ease-out; } @keyframes slideInUp { from { transform: translateY(100%); } to { transform: translateY(0); } }`}</style>

        <div className="flex-1 pb-32"> 
          <div className="max-w-2xl mx-auto w-full">
            {product.imageUrls && product.imageUrls.length > 0 ? (
              <div className="relative aspect-square sm:aspect-video w-full bg-gray-100">
                  <img 
                    src={product.imageUrls[currentImageIndex]} 
                    alt={product.name} 
                    className={`w-full h-full object-cover ${isSoldOut ? 'grayscale' : ''}`}
                    onClick={() => setIsImageFullscreen(true)}
                  />
                  <button onClick={onClose} className="absolute top-4 left-4 p-2 bg-white/80 rounded-full shadow-md"><ArrowLeftIcon className="w-6 h-6"/></button>
                  {isSoldOut && <div className="absolute inset-0 bg-black/40 flex items-center justify-center"><span className="bg-red-600 text-white font-bold px-6 py-2 rounded uppercase tracking-widest">Esgotado</span></div>}
              </div>
            ) : (
               <div className="p-4 border-b flex items-center sticky top-0 bg-white z-20">
                  <button onClick={onClose} className="p-2 -ml-2"><ArrowLeftIcon className="w-6 h-6"/></button>
                  <h1 className="ml-2 text-lg font-bold text-brand-text truncate">{product.name}</h1>
              </div>
            )}

            <div className="p-6 space-y-8">
                <div>
                    <h1 className="text-2xl font-bold text-brand-text">{product.name}</h1>
                    <p className="text-brand-text-light text-base mt-2 leading-relaxed">{product.description}</p>
                </div>

                {/* Tamanhos / Opções Base */}
                {product.options && product.options.length > 0 && !isSoldOut && (
                    <div className="space-y-4">
                        <h3 className="text-base font-bold text-brand-text border-l-4 border-brand-primary pl-3">Escolha uma opção</h3>
                        <div className="grid gap-3">
                            {product.options.map((option, index) => (
                                <button 
                                    key={index} 
                                    onClick={() => setSelectedOption(option)}
                                    className={`flex items-center justify-between p-4 rounded-xl border transition-all ${selectedOption?.name === option.name ? 'border-brand-primary bg-brand-secondary/20 ring-1 ring-brand-primary' : 'border-gray-200'}`}
                                >
                                    <span className="font-bold text-brand-text">{option.name}</span>
                                    <span className="font-bold text-brand-primary">{formatPrice(option.price)}</span>
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* Grupos de Personalização (Estilo Dino) */}
                {product.customizationGroups?.map((group) => {
                  const groupSelections = customSelections[group.id] || {};
                  const totalInGroup = Object.values(groupSelections).reduce((a, b) => a + b, 0);
                  const isValid = totalInGroup >= group.min && totalInGroup <= group.max;

                  return (
                    <div key={group.id} className="pt-6 border-t border-gray-100 space-y-4 animate-fade-in">
                        <div className="flex justify-between items-start">
                            <div>
                                <h3 className="text-base font-bold text-brand-text">{group.name}</h3>
                                <p className="text-xs text-gray-400">
                                    {group.min === group.max ? `Escolha ${group.min}` : `Escolha de ${group.min} a ${group.max}`}
                                </p>
                            </div>
                            {isValid ? (
                                <CheckCircleIcon className="w-5 h-5 text-green-500" />
                            ) : (
                                <span className="text-[10px] font-black bg-amber-100 text-amber-700 px-2 py-0.5 rounded uppercase">Obrigatório</span>
                            )}
                        </div>

                        <div className="space-y-3">
                            {group.options.map((opt) => {
                                const qty = groupSelections[opt.name] || 0;
                                return (
                                    <div key={opt.name} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${qty > 0 ? 'border-brand-primary/50 bg-brand-secondary/10' : 'border-gray-50'}`}>
                                        <div className="flex-grow pr-4">
                                            <p className="text-sm font-bold text-brand-text">{opt.name}</p>
                                            {opt.priceExtra > 0 && <p className="text-xs text-brand-accent font-bold">+{formatPrice(opt.priceExtra)}</p>}
                                        </div>

                                        <div className="flex items-center bg-white rounded-lg border border-gray-100 shadow-sm">
                                            <button 
                                              onClick={() => handleCustomOptionChange(group, opt, -1)}
                                              className={`p-2 transition-opacity ${qty === 0 ? 'opacity-20' : 'text-brand-text hover:bg-gray-50'}`}
                                            >
                                                <MinusIcon className="w-4 h-4"/>
                                            </button>
                                            <span className="px-3 text-sm font-black w-10 text-center text-brand-text">{qty}</span>
                                            <button 
                                              onClick={() => handleCustomOptionChange(group, opt, 1)}
                                              className={`p-2 transition-opacity ${totalInGroup >= group.max && group.type !== 'single' ? 'opacity-20' : 'text-brand-primary hover:bg-gray-50'}`}
                                            >
                                                <PlusIcon className="w-4 h-4"/>
                                            </button>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                  );
                })}

                {!isSoldOut && (
                    <div className="pt-6 border-t border-gray-100">
                        <label className="block text-sm font-bold text-brand-text mb-2">Observações</label>
                        <textarea 
                            value={observations}
                            onChange={(e) => setObservations(e.target.value)}
                            rows={3}
                            placeholder="Algum pedido especial? (Ex: Sem amendoim)"
                            className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-brand-primary outline-none"
                        />
                    </div>
                )}
            </div>
          </div>
        </div>

        {!isSoldOut && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 p-4 shadow-xl z-30">
                <div className="max-w-2xl mx-auto flex items-center gap-4">
                    <div className="flex items-center bg-gray-100 rounded-full p-1">
                      <button onClick={() => handleQuantityChange(-1)} disabled={quantity === 1} className="p-3 disabled:opacity-30"><MinusIcon className="w-5 h-5" /></button>
                      <span className="px-4 text-xl font-black w-12 text-center text-brand-text">{quantity}</span>
                      <button onClick={() => handleQuantityChange(1)} className="p-3"><PlusIcon className="w-5 h-5" /></button>
                    </div>

                    <button 
                      onClick={handleAddToCartClick}
                      disabled={!isAllGroupsValid}
                      className="flex-grow bg-brand-primary text-white font-black py-4 px-6 rounded-2xl flex items-center justify-between shadow-lg hover:brightness-105 active:scale-95 transition-all disabled:opacity-50"
                    >
                        <span className="flex items-center gap-2">
                           <ShoppingBagIcon className="w-6 h-6" />
                           Adicionar
                        </span>
                        <span>{formatPrice(totalPrice)}</span>
                    </button>
                </div>
            </div>
        )}
      </div>
    </>
  );
};

