};

const DeleteCategoryConfirmationModal: React.FC<{
    categoryName: string;
    onCancel: () => void;
    onConfirm: () => void;
}> = ({ categoryName, onCancel, onConfirm }) => {
    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-[100] flex items-center justify-center p-4">
            <div className="bg-white rounded-lg shadow-xl max-w-sm w-full p-6 text-center animate-fade-in-up">
                <h3 className="text-lg font-bold text-brand-text">Confirmar Exclusão</h3>
                <p className="text-sm text-gray-500 mt-2">
                    Você tem certeza que deseja apagar a categoria <span className="font-semibold">"{categoryName}"</span>? Esta ação não pode ser desfeita.
                </p>
                <div className="mt-6 flex justify-center gap-4">
                    <button onClick={onCancel} className="px-6 py-2 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50">
                        Cancelar
                    </button>
                    <button onClick={onConfirm} className="px-6 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-brand-primary hover:bg-brand-primary-dark">
                        Apagar
                    </button>
                </div>
            </div>
        </div>
    );
};

const ProductsView: React.FC<ProductsViewProps> = ({ 
    products, 
    categories, 
    onAddProduct, 
    onUpdateProduct, 
    onDeleteProduct, 
    onAddCategory, 
    onDeleteCategory, 
    onUpdateCategoryOrder,
    onToggleCategoriesArchive
}) => {
  const activeCategoriesOnly = useMemo(() => categories.filter(c => !c.isArchived), [categories]);
  const archivedCategoriesOnly = useMemo(() => categories.filter(c => c.isArchived), [categories]);

  const sortedCategoriesForSelect = useMemo(() => {
    return [...activeCategoriesOnly, ...archivedCategoriesOnly];
  }, [activeCategoriesOnly, archivedCategoriesOnly]);

  const initialFormState = {
    name: '',
    description: '',
    price: '',
    originalPrice: '',
    promotionalTag: '',
    category: '',
    imageUrls: '',
    leadTimeDays: '0',
    inventoryEnabled: false,
    inventoryQuantity: '0'
  };

  const [productForm, setProductForm] = useState(initialFormState);
  const [productOptions, setProductOptions] = useState<ProductOption[]>([]);
  const [customizationGroups, setCustomizationGroups] = useState<CustomizationGroup[]>([]);
  const [newOption, setNewOption] = useState({ name: '', price: '' });

  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [productToDelete, setProductToDelete] = useState<Product | null>(null);
  const [categoryToDelete, setCategoryToDelete] = useState<string | null>(null);
  const [newCategory, setNewCategory] = useState('');
  const [productSearchQuery, setProductSearchQuery] = useState('');
  const [selectedCategoryFilter, setSelectedCategoryFilter] = useState('Todas');

  const [categoryTab, setCategoryTab] = useState<'active' | 'archived'>('active');
  const [productViewTab, setProductViewTab] = useState<'active' | 'inactive'>('active');
  const [selectedCategoryNames, setSelectedCategoryNames] = useState<string[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  useEffect(() => {
    if (productToDelete || categoryToDelete || isProductModalOpen) {
        document.body.style.overflow = 'hidden';
        return () => {
            document.body.style.overflow = 'auto';
        };
    }
  }, [productToDelete, categoryToDelete, isProductModalOpen]);

  useEffect(() => {
    if (productOptions.length > 0 && isProductModalOpen) {
        const minPrice = Math.min(...productOptions.map(o => o.price));
        setProductForm(prev => ({ ...prev, price: String(minPrice) }));
    }
  }, [productOptions, isProductModalOpen]);

  const handleProductFormChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as HTMLInputElement;
    if (type === 'checkbox') {
        setProductForm(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
    } else {
        setProductForm(prev => ({ ...prev, [name]: value }));
    }
  };

  const openAddProductModal = () => {
    setEditingProduct(null);
    setProductForm(initialFormState);
    setProductOptions([]);
    setCustomizationGroups([]);
    setIsProductModalOpen(true);
  };

  const handleEditClick = (product: Product) => {
    setEditingProduct(product);
    setProductForm({
        name: product.name,
        description: product.description,
        price: String(product.price),
        originalPrice: (product.originalPrice && product.originalPrice > 0) ? String(product.originalPrice) : '',
        promotionalTag: product.promotionalTag || '',
        category: product.category,
        imageUrls: product.imageUrls ? product.imageUrls.join('\n') : '',
        leadTimeDays: String(product.leadTimeDays || 0),
        inventoryEnabled: !!product.inventoryEnabled,
        inventoryQuantity: String(product.inventoryQuantity || 0)
    });
    setProductOptions(product.options || []);
    setCustomizationGroups(product.customizationGroups || []);
    setIsProductModalOpen(true);
  };

  const handleDuplicateClick = (product: Product) => {
    setProductForm({
        name: `${product.name} (Cópia)`,
        description: product.description,
        price: String(product.price),
        originalPrice: (product.originalPrice && product.originalPrice > 0) ? String(product.originalPrice) : '',
        promotionalTag: product.promotionalTag || '',
        category: product.category,
        imageUrls: product.imageUrls ? product.imageUrls.join('\n') : '',
        leadTimeDays: String(product.leadTimeDays || 0),
        inventoryEnabled: !!product.inventoryEnabled,
        inventoryQuantity: String(product.inventoryQuantity || 0)
    });
    setProductOptions(product.options || []);
    setCustomizationGroups(product.customizationGroups || []);
    setEditingProduct(null); 
    setIsProductModalOpen(true);
  };

  const confirmDelete = async () => {
    if (!productToDelete) return;
    setMessage(null);
    try {
        await onDeleteProduct(productToDelete.id);
        setMessage({ type: 'success', text: 'Produto apagado!' });
    } catch (error) {
        setMessage({ type: 'error', text: 'Erro ao apagar.' });
    } finally {
        setProductToDelete(null);
        setTimeout(() => setMessage(null), 3000);
    }
  };

  const closeProductModal = () => {
    setIsProductModalOpen(false);
    setEditingProduct(null);
    setProductForm(initialFormState);
    setProductOptions([]);
    setCustomizationGroups([]);
    setMessage(null);
  };

  const handleAddOption = () => {
      if (!newOption.name || !newOption.price) return;
      setProductOptions([...productOptions, { name: newOption.name, price: parseFloat(newOption.price) }]);
      setNewOption({ name: '', price: '' });
  };

  const handleRemoveOption = (index: number) => {
      setProductOptions(productOptions.filter((_, i) => i !== index));
  };

  const handleProductSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    setIsSubmitting(true);
    const imageUrlsArray = productForm.imageUrls.split('\n').map(url => url.trim()).filter(url => url);

    try {
      let effectivePrice = parseFloat(productForm.price);
      if (productOptions.length > 0) {
          effectivePrice = Math.min(...productOptions.map(o => o.price));
      }

      const productData: any = {
        name: productForm.name,
        description: productForm.description,
        price: effectivePrice,
        category: productForm.category,
        imageUrls: imageUrlsArray,
        leadTimeDays: parseInt(productForm.leadTimeDays, 10) || 0,
        options: productOptions,
        customizationGroups: customizationGroups,
        inventoryEnabled: productForm.inventoryEnabled,
        inventoryQuantity: parseInt(productForm.inventoryQuantity, 10) || 0,
      };

      if (editingProduct) productData.id = editingProduct.id;

      const origPrice = parseFloat(productForm.originalPrice);
      productData.originalPrice = !isNaN(origPrice) && origPrice > 0 ? origPrice : null;
      productData.promotionalTag = productForm.promotionalTag?.trim() || null;

      if (editingProduct) {
        await onUpdateProduct(productData);
        setMessage({ type: 'success', text: 'Atualizado!' });
      } else {
        await onAddProduct(productData);
        setMessage({ type: 'success', text: 'Cadastrado!' });
      }

      setTimeout(closeProductModal, 1000);
    } catch (error) {
        setMessage({ type: 'error', text: 'Ocorreu um erro.' });
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleAddCategory = async () => {
    if (!newCategory.trim()) return;
    setIsSubmitting(true);
    try {
        await onAddCategory(newCategory);
        setNewCategory('');
        setMessage({ type: 'success', text: 'Categoria adicionada!' });
    } catch (e) {
        setMessage({ type: 'error', text: 'Erro.' });
    } finally {
        setIsSubmitting(false);
        setTimeout(() => setMessage(null), 3000);
    }
  };

  const handleDeleteCategory = (categoryName: string) => {
      if (products.some(p => p.category === categoryName)) {
          alert(`A categoria "${categoryName}" está em uso e não pode ser removida.`);
          return;
      }
      setCategoryToDelete(categoryName);
  };

  const confirmDeleteCategory = async () => {
    if (!categoryToDelete) return;
    setIsSubmitting(true);
    try {
        await onDeleteCategory(categoryToDelete);
    } catch (e) {
        setMessage({ type: 'error', text: 'Erro ao apagar.' });
    } finally {
        setIsSubmitting(false);
        setCategoryToDelete(null);
    }
  };

  const handleSort = () => {
      if (dragItem.current === null || dragOverItem.current === null) return;
      const categoriesCopy = [...categories];
      const activeCats = categories.filter(c => !c.isArchived);
      const realDragIdx = categories.findIndex(c => c.name === activeCats[dragItem.current!].name);
      const realTargetIdx = categories.findIndex(c => c.name === activeCats[dragOverItem.current!].name);
      const item = categoriesCopy.splice(realDragIdx, 1)[0];
      categoriesCopy.splice(realTargetIdx, 0, item);
      dragItem.current = null;
      dragOverItem.current = null;
      onUpdateCategoryOrder(categoriesCopy);
  };

  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(productSearchQuery.toLowerCase());
    const isArchived = categories.find(c => c.name === p.category)?.isArchived;
    if (productViewTab === 'active' && isArchived) return false;
    if (productViewTab === 'inactive' && !isArchived) return false;
    return matchesSearch && (selectedCategoryFilter === 'Todas' || p.category === selectedCategoryFilter);
  });

  const inputStyles = "mt-1 block w-full px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm text-gray-900 focus:ring-brand-primary outline-none focus:ring-2 sm:text-sm";

  return (
    <>
        {productToDelete && (
            <DeleteConfirmationModal product={productToDelete} onCancel={() => setProductToDelete(null)} onConfirm={confirmDelete}/>
        )}
        {categoryToDelete && (
            <DeleteCategoryConfirmationModal categoryName={categoryToDelete} onCancel={() => setCategoryToDelete(null)} onConfirm={confirmDeleteCategory}/>
        )}

        {isProductModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-xl shadow-2xl max-w-3xl w-full max-h-[90vh] overflow-hidden flex flex-col animate-slide-in-up no-scrollbar">
                    <header className="p-4 border-b bg-gray-50 flex justify-between items-center">
                        <h2 className="text-xl font-bold text-brand-text">{editingProduct ? 'Editar Produto' : 'Novo Produto'}</h2>
                        <button onClick={closeProductModal} className="p-2 hover:bg-gray-200 rounded-full text-gray-400"><CloseIcon className="w-6 h-6"/></button>
                    </header>
                    <div className="flex-1 overflow-y-auto p-6 no-scrollbar">
                        <form onSubmit={handleProductSubmit} className="space-y-6">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="space-y-4">
                                    <div><label className="text-xs font-bold text-gray-500 uppercase">Nome</label><input type="text" value={productForm.name} onChange={handleProductFormChange} name="name" className={inputStyles} required /></div>
                                    <div><label className="text-xs font-bold text-gray-500 uppercase">Descrição</label><textarea value={productForm.description} onChange={handleProductFormChange} name="description" rows={3} className={inputStyles} required /></div>
                                    <div><label className="text-xs font-bold text-gray-500 uppercase">Categoria</label><SearchableSelect options={sortedCategoriesForSelect} value={productForm.category} onChange={(val) => setProductForm(prev => ({ ...prev, category: val }))} placeholder="Selecione..."/></div>
                                </div>
                                <div className="space-y-4">
                                    <div><label className="text-xs font-bold text-gray-500 uppercase">Imagens (URLs)</label><textarea value={productForm.imageUrls} onChange={handleProductFormChange} name="imageUrls" rows={3} className={inputStyles} placeholder="Uma URL por linha"/></div>
                                    <div className="grid grid-cols-2 gap-2">
                                        <div><label className="text-xs font-bold text-gray-500 uppercase">Preço Venda</label><input type="number" step="0.01" value={productForm.price} onChange={handleProductFormChange} name="price" className={inputStyles} readOnly={productOptions.length > 0} /></div>
                                        <div><label className="text-xs font-bold text-gray-500 uppercase">Dias Antecedência</label><input type="number" value={productForm.leadTimeDays} onChange={handleProductFormChange} name="leadTimeDays" className={inputStyles} /></div>
                                    </div>
                                    <div className="flex items-center gap-2 p-2 bg-gray-50 rounded border">
                                        <input type="checkbox" id="inv" name="inventoryEnabled" checked={!!productForm.inventoryEnabled} onChange={handleProductFormChange} className="w-4 h-4 text-brand-primary" />
                                        <label htmlFor="inv" className="text-xs font-bold text-gray-700">Controle Estoque</label>
                                        {productForm.inventoryEnabled && <input type="number" value={productForm.inventoryQuantity} name="inventoryQuantity" onChange={handleProductFormChange} className="w-16 ml-auto px-2 py-1 border rounded text-xs"/>}
                                    </div>
                                </div>
                            </div>

                            {/* Variantes de Tamanho */}
                            <div className="bg-gray-50 p-4 rounded-xl border border-gray-200">
                                <h4 className="text-xs font-black text-gray-400 uppercase mb-4 tracking-widest">Tamanhos / Variantes (Opcional)</h4>
                                <div className="space-y-2 mb-4">
                                    {productOptions.map((opt, i) => (
                                        <div key={i} className="flex justify-between bg-white p-2 border rounded-lg">
                                            <span className="text-sm font-bold">{opt.name} - R$ {opt.price.toFixed(2)}</span>
                                            <button type="button" onClick={() => handleRemoveOption(i)}><TrashIcon className="w-4 h-4 text-red-400"/></button>
                                        </div>
                                    ))}
                                </div>
                                <div className="flex gap-2">
                                    <input type="text" placeholder="Ex: Pequeno" value={newOption.name} onChange={e => setNewOption({...newOption, name: e.target.value})} className="flex-grow px-2 py-1 border rounded text-sm"/>
                                    <input type="number" placeholder="0,00" value={newOption.price} onChange={e => setNewOption({...newOption, price: e.target.value})} className="w-24 px-2 py-1 border rounded text-sm"/>
                                    <button type="button" onClick={handleAddOption} className="bg-brand-primary text-white px-3 py-1 rounded text-xs">Add</button>
                                </div>
                            </div>

                            {/* EDITOR DE PERSONALIZAÇÃO (ESTILO DINO) */}
                            <CustomizationGroupEditor groups={customizationGroups} onChange={setCustomizationGroups} />

                            <div className="flex gap-3">
                                <button type="submit" disabled={isSubmitting} className="flex-grow bg-brand-primary text-white py-3 rounded-xl font-bold shadow-lg disabled:opacity-50">
                                    {isSubmitting ? 'Salvando...' : (editingProduct ? 'Salvar Alterações' : 'Cadastrar Produto')}
                                </button>
                                <button type="button" onClick={closeProductModal} className="px-6 border rounded-xl font-bold text-gray-500">Cancelar</button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        )}

        <div className="space-y-8">
            <div className="max-w-3xl mx-auto flex justify-between items-center bg-white rounded-xl shadow-sm p-4 border border-gray-100">
                <h2 className="text-xl font-bold text-brand-text">Gestão de Produtos</h2>
                <button onClick={openAddProductModal} className="bg-brand-primary text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2"><PlusIcon className="w-5 h-5"/>Novo Produto</button>
            </div>

            <div className="max-w-3xl mx-auto bg-white rounded-xl shadow-md p-6">
                <h2 className="text-2xl font-bold text-brand-text mb-6">Categorias</h2>
                <div className="flex gap-2 mb-6">
                    <input type="text" value={newCategory} onChange={e => setNewCategory(e.target.value)} className={inputStyles + ' flex-grow'} placeholder="Nova categoria..." />
                    <button onClick={handleAddCategory} className="bg-brand-primary text-white px-4 rounded-lg font-bold">Add</button>
                </div>
                <div className="border-b mb-4 flex gap-4">
                    <button onClick={() => setCategoryTab('active')} className={`py-2 px-1 border-b-2 font-bold text-sm ${categoryTab === 'active' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}>Ativas</button>
                    <button onClick={() => setCategoryTab('archived')} className={`py-2 px-1 border-b-2 font-bold text-sm ${categoryTab === 'archived' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}>Arquivadas</button>
                </div>
                <div className="space-y-2">
                    {(categoryTab === 'active' ? activeCategoriesOnly : archivedCategoriesOnly).map((cat, i) => (
                        <div key={cat.name} draggable={categoryTab === 'active'} onDragStart={() => dragItem.current = i} onDragEnter={() => dragOverItem.current = i} onDragEnd={handleSort} onDragOver={e => e.preventDefault()} className="flex justify-between items-center p-3 bg-gray-50 border rounded-lg">
                            <span className="flex items-center gap-2 text-sm font-medium"><DragHandleIcon className="w-4 h-4 text-gray-300"/>{cat.name}</span>
                            <div className="flex gap-3">
                                <button onClick={() => onToggleCategoriesArchive([cat.name], !cat.isArchived)} title={cat.isArchived ? "Restaurar" : "Arquivar"}>
                                    <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4" /></svg>
                                </button>
                                <button onClick={() => handleDeleteCategory(cat.name)}><TrashIcon className="w-5 h-5 text-red-300"/></button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="max-w-3xl mx-auto bg-white rounded-xl shadow-md p-6">
                <h2 className="text-2xl font-bold text-brand-text mb-6">Produtos</h2>
                <div className="flex gap-4 mb-6 flex-wrap">
                    <div className="relative flex-grow min-w-[200px]"><SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-300"/><input type="text" value={productSearchQuery} onChange={e => setProductSearchQuery(e.target.value)} placeholder="Pesquisar produtos..." className="w-full pl-10 pr-4 py-2 bg-gray-50 rounded-full text-sm outline-none focus:ring-2 focus:ring-brand-primary"/></div>
                    <select value={selectedCategoryFilter} onChange={e => setSelectedCategoryFilter(e.target.value)} className="bg-gray-50 rounded-full px-4 py-2 text-sm outline-none">
                        <option value="Todas">Todas as Categorias</option>
                        {activeCategoriesOnly.map(c => <option key={c.name} value={c.name}>{c.name}</option>)}
                    </select>
                </div>
                <div className="border-b mb-6 flex gap-4">
                    <button onClick={() => setProductViewTab('active')} className={`py-2 px-1 border-b-2 font-bold text-sm ${productViewTab === 'active' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}>Visíveis</button>
                    <button onClick={() => setProductViewTab('inactive')} className={`py-2 px-1 border-b-2 font-bold text-sm ${productViewTab === 'inactive' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}>Arquivados (Categoria)</button>
                </div>
                <div className="space-y-3">
                    {filteredProducts.map(p => (
                        <div key={p.id} className="flex justify-between items-center p-3 bg-white border rounded-xl hover:shadow-sm transition-shadow">
                            <div className="flex items-center gap-3 min-w-0">
                                {p.imageUrls?.[0] ? <img src={p.imageUrls[0]} className="w-12 h-12 object-cover rounded-lg"/> : <div className="w-12 h-12 bg-gray-100 rounded-lg"/>}
                                <div className="min-w-0">
                                    <p className="font-bold text-sm truncate">{p.name}</p>
                                    <p className="text-[10px] text-gray-400 font-bold uppercase">{p.category}</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-3">
                                <button onClick={() => handleDuplicateClick(p)} title="Duplicar"><CopyIcon className="w-4 h-4 text-gray-300"/></button>
                                <button onClick={() => handleEditClick(p)} className="text-xs font-bold text-brand-primary hover:underline">Editar</button>
                                <button onClick={() => setProductToDelete(p)} className="text-xs font-bold text-red-400 hover:underline">Apagar</button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    </>
  );
};

export default ProductsView;

export interface ProductOption {
  name: string;
  price: number;
}

export interface CustomizationOption {
  name: string;
  priceExtra: number;
}

export interface CustomizationGroup {
  id: string;
  name: string;
  min: number;
  max: number;
  type: 'single' | 'counter';
  options: CustomizationOption[];
}

export interface SelectedCustomization {
  groupName: string;
  items: {
    name: string;
    quantity: number;
    priceExtra: number;
  }[];
}

export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  originalPrice?: number;
  promotionalTag?: string;
  category: string;
  imageUrls: string[];
  leadTimeDays: number;
  options?: ProductOption[];
  customizationGroups?: CustomizationGroup[];
  createdAt?: any;
  inventoryEnabled?: boolean;
  inventoryQuantity?: number;
}

export interface CategoryMetadata {
  name: string;
  isArchived: boolean;
}

export interface CartItem extends Product {
  quantity: number;
  observations?: string;
  selectedOption?: ProductOption;
  selectedCustomizations?: SelectedCustomization[];
}

export interface OperatingHours {
  day: string;
  time: string;
}

export interface StoreInfoData {
    name: string;
    logoUrl: string;
    hours: string; // delivery time
    coverImageUrl: string;
    operatingHours: OperatingHours[];
    paymentMethods: {
        online: string[];
    };
    whatsappNumber?: string;
}

export interface DeliveryInfo {
  type: 'delivery';
  address: {
    cep: string;
    street: string;
    number: string;
    neighborhood: string;
    complement?: string;
  };
}

export interface OrderItem {
  id: string;
  name: string;
  quantity: number;
  price: number;
  observations?: string;
  option?: string;
  selectedCustomizations?: SelectedCustomization[];
}

export interface Order {
  id: string;
  orderNumber: number;
  customer: {
    name: string;
    whatsapp: string;
  };
  delivery: DeliveryInfo;
  items: OrderItem[];
  total: number;
  deliveryFee?: number;
  paymentMethod: string;
  paymentLink?: string;
  deliveryDate: string;
  status: 'new' | 'pending_payment' | 'confirmed' | 'shipped' | 'completed' | 'archived';
  createdAt: any;
  updatedAt: any;
}

export interface Client {
  id: string;
  name: string;
  whatsapp: string;
  firstOrderDate: any;
  lastOrderDate: any;
  totalOrders: number;
  totalSpent: number;
  addresses: DeliveryInfo['address'][];
  orderIds: string[];
  observations?: string;
  birthday?: string;
  needsSync?: boolean;
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import StoreInfo from './components/StoreInfo';
import CategoryTabs from './components/CategoryTabs';
import ProductCard from './components/ProductCard';
import Footer from './components/Footer';
import LoginPage from './components/LoginPage';
import AdminPage from './components/AdminPage';
import StoreInfoModal from './components/StoreInfoModal';
import CategoryMenuModal from './components/CategoryMenuModal';
import ProductDetailModal from './components/ProductDetailModal';
import CartButton from './components/CartButton';
import CheckoutPage from './components/CheckoutPage';
import OrderSuccessPage from './components/OrderSuccessPage';
import OrderTrackingModal from './components/OrderTrackingModal';
import { BikeIcon, ShoppingBagIcon } from './components/IconComponents';
import type { Product, CartItem, StoreInfoData, Order, ProductOption, CategoryMetadata, SelectedCustomization } from './types';
import { getMenu, addProduct, getStoreInfo, updateStoreInfo, updateProduct, deleteProduct, addCategory, deleteCategory, initializeFirebaseData, updateCategoryOrder, incrementVisitCount, getOrderById, toggleCategoriesArchive } from './services/menuService';
import { auth } from './firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';

const App: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<CategoryMetadata[]>([]);
  const [storeInfo, setStoreInfo] = useState<StoreInfoData | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<string>('Todos');
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [view, setView] = useState<'menu' | 'login' | 'admin' | 'checkout' | 'orderSuccess'>('menu');
  const [orderSuccessData, setOrderSuccessData] = useState<Order | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [isStoreInfoModalOpen, setStoreInfoModalOpen] = useState(false);
  const [isCategoryMenuOpen, setCategoryMenuOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [isOrderTrackingOpen, setIsOrderTrackingOpen] = useState(false);

  const [activeOrders, setActiveOrders] = useState<Order[]>([]);

  useEffect(() => {
    incrementVisitCount();
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      if (user) {
        setIsAuthenticated(true);
      } else {
        setIsAuthenticated(false);
        setView(currentView => currentView === 'admin' ? 'login' : currentView);
      }
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const checkActiveOrders = async () => {
      let ids: string[] = [];
      const legacyId = localStorage.getItem('activeOrderId');
      if (legacyId) ids.push(legacyId);
      const storedIds = localStorage.getItem('activeOrderIds');
      if (storedIds) {
        try {
          const parsed = JSON.parse(storedIds);
          if (Array.isArray(parsed)) {
            ids = [...ids, ...parsed];
          }
        } catch (e) {
          console.error("Error parsing activeOrderIds", e);
        }
      }
      ids = [...new Set(ids)];
      if (ids.length === 0) {
        setActiveOrders([]);
        return;
      }
      const promises = ids.map(id => getOrderById(id));
      const results = await Promise.all(promises);
      const validOrders: Order[] = [];
      const validIds: string[] = [];
      results.forEach(order => {
        if (order && order.status !== 'archived' && order.status !== 'completed') {
            validOrders.push(order);
            validIds.push(order.id);
        }
      });
      validOrders.sort((a, b) => b.orderNumber - a.orderNumber);
      setActiveOrders(validOrders);
      if (validIds.length !== ids.length || legacyId) {
          localStorage.setItem('activeOrderIds', JSON.stringify(validIds));
          localStorage.removeItem('activeOrderId');
      }
    };
    checkActiveOrders();
    const interval = setInterval(checkActiveOrders, 30000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const isModalOpen = isStoreInfoModalOpen || isCategoryMenuOpen || !!selectedProduct || isOrderTrackingOpen;
    if (isModalOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'auto';
    }
    return () => {
      document.body.style.overflow = 'auto';
    };
  }, [isStoreInfoModalOpen, isCategoryMenuOpen, selectedProduct, isOrderTrackingOpen]);

  const fetchInitialData = useCallback(async () => {
    setIsLoading(true);
    try {
        await initializeFirebaseData();
        const [menuResult, storeInfoResult] = await Promise.all([getMenu(), getStoreInfo()]);
        setProducts(menuResult.products);
        setCategories(menuResult.categories);
        setStoreInfo(storeInfoResult);
    } catch (error) {
        console.error("Failed to fetch initial data", error);
    } finally {
        setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    if (view === 'menu' || (view === 'admin' && isAuthenticated)) {
        fetchInitialData();
    }
  }, [view, isAuthenticated, fetchInitialData]);

  const handleSelectCategory = useCallback((category: string) => {
    setSelectedCategory(category);
  }, []);

  const handleModalCategorySelect = useCallback((category: string) => {
    setSelectedCategory(category);
    setCategoryMenuOpen(false);
  }, []);

  const handleAddProduct = useCallback(async (productData: Omit<Product, 'id'>) => {
    await addProduct(productData);
    await fetchInitialData(); 
  }, [fetchInitialData]);

  const handleUpdateProduct = useCallback(async (productData: Product) => {
      await updateProduct(productData);
      await fetchInitialData();
  }, [fetchInitialData]);

   const handleDeleteProduct = useCallback(async (productId: string) => {
      try {
        await deleteProduct(productId);
        setProducts(prevProducts => prevProducts.filter(p => p.id !== productId));
      } catch (error) {
        console.error("Failed to delete product. Refetching to sync.", error);
        await fetchInitialData();
      }
  }, [fetchInitialData]);

  const handleUpdateStoreInfo = useCallback(async (storeInfoData: StoreInfoData) => {
      await updateStoreInfo(storeInfoData);
      await fetchInitialData();
  }, [fetchInitialData]);

  const handleAddCategory = useCallback(async (categoryName: string) => {
    const updatedCategories = await addCategory(categoryName);
    setCategories(updatedCategories);
  }, []);

  const handleDeleteCategory = useCallback(async (categoryName: string) => {
      const updatedCategories = await deleteCategory(categoryName);
      setCategories(updatedCategories);
      if (selectedCategory === categoryName) {
        setSelectedCategory('Todos');
      }
  }, [selectedCategory]);

  const handleUpdateCategoryOrder = useCallback(async (newOrder: CategoryMetadata[]) => {
      try {
          await updateCategoryOrder(newOrder);
          setCategories(newOrder);
      } catch (error) {
          console.error("Failed to update category order", error);
          await fetchInitialData();
      }
  }, [fetchInitialData]);

  const handleToggleCategoriesArchive = useCallback(async (categoryNames: string[], archive: boolean) => {
      try {
          const updated = await toggleCategoriesArchive(categoryNames, archive);
          setCategories(updated);
          if (archive && categoryNames.includes(selectedCategory)) {
              setSelectedCategory('Todos');
          }
      } catch (error) {
          console.error("Failed to archive categories", error);
      }
  }, [selectedCategory]);

  const handleProductClick = useCallback((product: Product) => {
    setSelectedProduct(product);
  }, []);

  const handleCloseModal = useCallback(() => {
    setSelectedProduct(null);
  }, []);

  const handleAddToCart = useCallback((productToAdd: Product, quantity: number, observations?: string, selectedOption?: ProductOption, selectedCustomizations?: SelectedCustomization[]) => {
    setCartItems(prevItems => {
        // Criar uma representação string única das customizações para comparação
        const customizationsKey = JSON.stringify(selectedCustomizations || []);

        const existingItemIndex = prevItems.findIndex(item => 
            item.id === productToAdd.id && 
            item.selectedOption?.name === selectedOption?.name &&
            JSON.stringify(item.selectedCustomizations || []) === customizationsKey
        );

        if (existingItemIndex !== -1) {
            const newItems = [...prevItems];
            newItems[existingItemIndex] = {
                ...newItems[existingItemIndex],
                quantity: newItems[existingItemIndex].quantity + quantity,
                observations: observations 
            };
            return newItems;
        } else {
            const basePrice = selectedOption ? selectedOption.price : productToAdd.price;
            const extraPrice = (selectedCustomizations || []).reduce((acc, group) => {
                return acc + group.items.reduce((groupAcc, item) => groupAcc + (item.priceExtra * item.quantity), 0);
            }, 0);

            return [...prevItems, { 
                ...productToAdd, 
                price: basePrice + extraPrice,
                quantity, 
                observations, 
                selectedOption,
                selectedCustomizations
            }];
        }
    });
    setSelectedProduct(null);
  }, []);

  const handleUpdateCartQuantity = useCallback((productId: string, newQuantity: number, optionName?: string) => {
    setCartItems(prev => {
        if (newQuantity <= 0) {
            return prev.filter(item => !(item.id === productId && item.selectedOption?.name === optionName));
        }
        return prev.map(item =>
            (item.id === productId && item.selectedOption?.name === optionName) 
                ? { ...item, quantity: newQuantity } 
                : item
        );
    });
  }, []);

  const handleRemoveFromCart = useCallback((productId: string, optionName?: string) => {
    setCartItems(prev => prev.filter(item => !(item.id === productId && item.selectedOption?.name === optionName)));
  }, []);

  const handleGoToCheckout = useCallback(() => {
    setView('checkout');
  }, []);

  const handleOrderSuccess = (order: Order) => {
    setOrderSuccessData(order);
    setCartItems([]);
    setActiveOrders(prev => {
        const exists = prev.some(o => o.id === order.id);
        const newOrders = exists 
            ? prev.map(o => o.id === order.id ? order : o) 
            : [order, ...prev];
        const ids = newOrders.map(o => o.id);
        localStorage.setItem('activeOrderIds', JSON.stringify(ids));
        localStorage.removeItem('activeOrderId');
        return newOrders;
    });
    setView('orderSuccess');
  };

  const handleTrackOrder = useCallback((order: Order) => {
    setOrderSuccessData(order);
    setView('orderSuccess');
    setIsOrderTrackingOpen(false);
  }, []);

  const handleBannerClick = () => {
    if (activeOrders.length === 1) {
        setOrderSuccessData(activeOrders[0]);
        setView('orderSuccess');
    } else if (activeOrders.length > 1) {
        setIsOrderTrackingOpen(true);
    }
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
      setView('login');
    } catch (error) {
      console.error("Error signing out", error);
    }
  };

  const SectionTitle: React.FC<{ title: string }> = ({ title }) => (
    <div className="flex justify-between items-center mb-6 mt-10">
        <div className="flex items-center space-x-3">
            <div className="w-1.5 h-6 bg-brand-primary rounded-full"></div>
            <h2 className="text-xl font-bold text-brand-text tracking-tight">{title}</h2>
        </div>
    </div>
  );

  const activeCategoriesList = useMemo(() => {
      return categories.filter(c => !c.isArchived).map(c => c.name);
  }, [categories]);

  const allVisibleCategoriesForTabs = useMemo(() => {
    const productCategories = new Set(products.map(p => p.category));
    const activeOfficial = activeCategoriesList;
    const orphanCategories = Array.from(productCategories).filter(cat => 
        cat && cat !== 'Todos' && !activeOfficial.includes(cat) && 
        !categories.some(c => c.name === cat && c.isArchived)
    );
    return [...activeOfficial, ...orphanCategories];
  }, [activeCategoriesList, products, categories]);

  const renderMenu = () => {
    const categoriesWithProducts = allVisibleCategoriesForTabs.filter(category => 
        products.some(p => p.category === category)
    );
    const visibleCategoriesForTabs = ['Todos', ...categoriesWithProducts];

    const getStatusText = (status: Order['status']) => {
        const texts = {
            new: 'Recebido',
            pending_payment: 'Pagamento Pendente',
            confirmed: 'Em Preparo',
            shipped: 'Saiu para entrega',
            completed: 'Finalizado',
            archived: ''
        };
        return texts[status] || 'Em andamento';
    };

    return (
        <>
        <div className="min-h-screen flex flex-col bg-gray-50">
            {activeOrders.length > 0 && (
                <div 
                    onClick={handleBannerClick}
                    className="bg-brand-primary text-white py-3 px-4 cursor-pointer shadow-md flex items-center justify-between"
                >
                    {activeOrders.length === 1 ? (
                        <>
                            <div className="flex items-center gap-3">
                                <div className="bg-white/20 p-2 rounded-full">
                                    <BikeIcon className="w-5 h-5 text-white" />
                                </div>
                                <div>
                                    <p className="text-sm font-semibold">Você possui um pedido em andamento</p>
                                    <p className="text-xs text-brand-secondary opacity-90">
                                        Pedido #{activeOrders[0].orderNumber} • {getStatusText(activeOrders[0].status)}
                                    </p>
                                </div>
                            </div>
                            <div className="bg-white/10 px-3 py-1 rounded text-xs font-bold hover:bg-white/20 transition-colors">
                                Ver
                            </div>
                        </>
                    ) : (
                        <>
                            <div className="flex items-center gap-3">
                                <div className="bg-white/20 p-2 rounded-full">
                                    <ShoppingBagIcon className="w-5 h-5 text-white" />
                                </div>
                                <div>
                                    <p className="text-sm font-semibold">Você tem {activeOrders.length} pedidos em andamento</p>
                                    <p className="text-xs text-brand-secondary opacity-90">
                                        Toque para acompanhar
                                    </p>
                                </div>
                            </div>
                            <div className="bg-white/10 px-3 py-1 rounded text-xs font-bold hover:bg-white/20 transition-colors">
                                Ver todos
                            </div>
                        </>
                    )}
                </div>
            )}
            <main className="flex-grow">
            <StoreInfo 
                storeInfo={storeInfo} 
                isLoading={!storeInfo}
                onOpenModal={() => setStoreInfoModalOpen(true)}
                onOpenOrderTracker={() => setIsOrderTrackingOpen(true)}
            />
            <CategoryTabs
                categories={visibleCategoriesForTabs}
                selectedCategory={selectedCategory}
                onSelectCategory={handleSelectCategory}
                onOpenMenu={() => setCategoryMenuOpen(true)}
                onSearch={setSearchQuery}
                searchQuery={searchQuery}
            />
            <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-4">
                {isLoading ? (
                <div>
                    {Array.from({length: 2}).map((_, i) => (
                        <div key={i}>
                            <div className="h-6 bg-gray-200 rounded w-1/3 animate-pulse mb-4 mt-8"></div>
                            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                                {Array.from({length: 3}).map((_, index) => (
                                    <div key={index} className="flex items-center bg-white p-2 rounded-lg gap-4 animate-pulse">
                                        <div className="w-24 h-24 sm:w-32 sm:h-32 bg-gray-200 rounded-md"></div>
                                        <div className="flex-grow space-y-3 py-2">
                                            <div className="h-5 bg-gray-200 rounded w-3/4"></div>
                                            <div className="h-4 bg-gray-200 rounded w-full hidden sm:block"></div>
                                            <div className="h-6 bg-gray-200 rounded w-1/2"></div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
                ) : searchQuery.trim() !== '' ? (() => {
                    const searchResults = products.filter(p =>
                    p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                    p.description.toLowerCase().includes(searchQuery.toLowerCase())
                    );
                    return (
                    <section>
                        <SectionTitle title={`Resultados para "${searchQuery}"`} />
                        {searchResults.length > 0 ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 sm:gap-6">
                            {searchResults.map(product => (
                            <ProductCard key={product.id} product={product} onProductClick={handleProductClick} />
                            ))}
                        </div>
                        ) : (
                        <p className="text-center text-gray-500 mt-8">Nenhum produto encontrado.</p>
                        )}
                    </section>
                    );
                })() : (
                    selectedCategory === 'Todos' ? (
                        categoriesWithProducts.map(category => {
                            const categoryProducts = products.filter(p => p.category === category);
                            if (categoryProducts.length === 0) return null;
                            return (
                                <section key={category}>
                                    <SectionTitle title={category} />
                                    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 sm:gap-6">
                                        {categoryProducts.map(product => (
                                            <ProductCard key={product.id} product={product} onProductClick={handleProductClick} />
                                        ))}
                                    </div>
                                </section>
                            )
                        })
                    ) : (() => {
                        const categoryProducts = products.filter(p => p.category === selectedCategory);
                        return (
                        <section>
                            <SectionTitle title={selectedCategory} />
                            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 sm:gap-6">
                                {categoryProducts.map(product => (
                                <ProductCard
                                    key={product.id}
                                    product={product}
                                    onProductClick={handleProductClick}
                                />
                                ))}
                            </div>
                        </section>
                        );
                    })()
                )}
            </div>
            </main>
            <Footer onNavigate={(target) => {
                if (target === 'login' && isAuthenticated) {
                    setView('admin');
                } else {
                    setView(target);
                }
            }} />
            {cartItems.length > 0 && <div className="h-24 sm:h-28" />}
        </div>
        <StoreInfoModal 
            isOpen={isStoreInfoModalOpen}
            onClose={() => setStoreInfoModalOpen(false)}
            storeInfo={storeInfo}
        />
        <CategoryMenuModal
            isOpen={isCategoryMenuOpen}
            onClose={() => setCategoryMenuOpen(false)}
            categories={categoriesWithProducts}
            onSelectCategory={handleModalCategorySelect}
        />
        <ProductDetailModal 
            product={selectedProduct}
            onClose={handleCloseModal}
            onAddToCart={handleAddToCart}
        />
        <CartButton 
            itemCount={cartItems.reduce((sum, item) => sum + item.quantity, 0)}
            totalPrice={cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0)}
            onClick={handleGoToCheckout}
        />
        <OrderTrackingModal
            isOpen={isOrderTrackingOpen}
            onClose={() => setIsOrderTrackingOpen(false)}
            onTrackOrder={handleTrackOrder}
            initialOrders={activeOrders}
        />
        </>
    );
  }


  switch (view) {
    case 'login':
      return <LoginPage
        onLoginSuccess={() => {
          setView('admin');
        }}
        onNavigateBack={() => setView('menu')}
      />;
    case 'admin':
      if (!isAuthenticated) {
        return <div className="min-h-screen flex items-center justify-center">Verificando acesso...</div>;
      }
      return <AdminPage
        products={products}
        categories={categories}
        storeInfo={storeInfo}
        onAddProduct={handleAddProduct}
        onUpdateProduct={handleUpdateProduct}
        onDeleteProduct={handleDeleteProduct}
        onUpdateStoreInfo={handleUpdateStoreInfo}
        onAddCategory={handleAddCategory}
        onDeleteCategory={handleDeleteCategory}
        onUpdateCategoryOrder={handleUpdateCategoryOrder}
        onToggleCategoriesArchive={handleToggleCategoriesArchive}
        onNavigateBack={() => setView('menu')}
        onLogout={handleLogout}
        onRefreshData={fetchInitialData}
      />;
    case 'checkout':
        return <CheckoutPage 
            cartItems={cartItems}
            storeInfo={storeInfo}
            onNavigateBack={() => {
                setView('menu');
            }}
            onOrderSuccess={handleOrderSuccess}
            onUpdateQuantity={handleUpdateCartQuantity}
            onRemoveItem={handleRemoveFromCart}
        />;
    case 'orderSuccess':
        return <OrderSuccessPage
            order={orderSuccessData}
            storeInfo={storeInfo}
            onNavigateBack={() => setView('menu')}
        />
    default:
      return renderMenu();
  }
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import type { Product, ProductOption, CategoryMetadata, CustomizationGroup, CustomizationOption } from '../types';
import { TrashIcon, SearchIcon, DragHandleIcon, CopyIcon, PlusIcon, ChevronRightIcon, XIcon as CloseIcon } from './IconComponents';

interface ProductsViewProps {
  products: Product[];
  categories: CategoryMetadata[];
  onAddProduct: (productData: Omit<Product, 'id'>) => Promise<void>;
  onUpdateProduct: (productData: Product) => Promise<void>;
  onDeleteProduct: (productId: string) => Promise<void>;
  onAddCategory: (categoryName: string) => Promise<void>;
  onDeleteCategory: (categoryName: string) => Promise<void>;
  onUpdateCategoryOrder: (newOrder: CategoryMetadata[]) => Promise<void>;
  onToggleCategoriesArchive: (categoryNames: string[], archive: boolean) => Promise<void>;
}

const CustomizationEditor: React.FC<{
    groups: CustomizationGroup[];
    onChange: (groups: CustomizationGroup[]) => void;
}> = ({ groups, onChange }) => {
    const addGroup = () => {
        const newGroup: CustomizationGroup = {
            id: `group-${Date.now()}`,
            name: '',
            min: 0,
            max: 1,
            type: 'single',
            options: []
        };
        onChange([...groups, newGroup]);
    };

    const updateGroup = (id: string, data: Partial<CustomizationGroup>) => {
        onChange(groups.map(g => g.id === id ? { ...g, ...data } : g));
    };

    const removeGroup = (id: string) => {
        onChange(groups.filter(g => g.id !== id));
    };

    const addOptionToGroup = (groupId: string) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                return {
                    ...g,
                    options: [...g.options, { name: '', priceExtra: 0 }]
                };
            }
            return g;
        }));
    };

    const updateOptionInGroup = (groupId: string, optIndex: number, data: Partial<CustomizationOption>) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                const newOpts = [...g.options];
                newOpts[optIndex] = { ...newOpts[optIndex], ...data };
                return { ...g, options: newOpts };
            }
            return g;
        }));
    };

    const removeOptionFromGroup = (groupId: string, optIndex: number) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                return { ...g, options: g.options.filter((_, i) => i !== optIndex) };
            }
            return g;
        }));
    };

    return (
        <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mt-6">
            <div className="flex justify-between items-center mb-4">
                <h4 className="text-sm font-bold text-brand-text uppercase tracking-wider">Personalizações & Adicionais</h4>
                <button type="button" onClick={addGroup} className="text-xs font-bold text-brand-primary bg-brand-secondary/50 px-3 py-1.5 rounded-lg hover:bg-brand-primary hover:text-white transition-all">
                    + Adicionar Grupo
                </button>
            </div>

            <div className="space-y-6">
                {groups.map((group) => (
                    <div key={group.id} className="bg-white p-4 rounded-lg border border-gray-100 shadow-sm relative">
                        <button type="button" onClick={() => removeGroup(group.id)} className="absolute top-2 right-2 text-gray-300 hover:text-red-500">
                            <TrashIcon className="w-4 h-4" />
                        </button>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-4">
                            <div>
                                <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1">Título do Grupo</label>
                                <input type="text" value={group.name} onChange={e => updateGroup(group.id, { name: e.target.value })} placeholder="Ex: Escolha a massa" className="w-full px-3 py-1.5 border rounded-md text-sm text-gray-900" />
                            </div>
                            <div className="flex gap-2">
                                <div className="w-1/2">
                                    <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1">Mín</label>
                                    <input type="number" min="0" value={group.min} onChange={e => updateGroup(group.id, { min: parseInt(e.target.value) })} className="w-full px-3 py-1.5 border rounded-md text-sm text-gray-900" />
                                </div>
                                <div className="w-1/2">
                                    <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1">Máx</label>
                                    <input type="number" min="1" value={group.max} onChange={e => updateGroup(group.id, { max: parseInt(e.target.value), type: parseInt(e.target.value) > 1 ? 'counter' : 'single' })} className="w-full px-3 py-1.5 border rounded-md text-sm text-gray-900" />
                                </div>
                            </div>
                        </div>

                        <div className="space-y-2">
                            {group.options.map((opt, idx) => (
                                <div key={idx} className="flex gap-2 items-center bg-gray-50 p-2 rounded-md">
                                    <input type="text" value={opt.name} onChange={e => updateOptionInGroup(group.id, idx, { name: e.target.value })} placeholder="Nome do item" className="flex-grow px-2 py-1 text-sm border rounded bg-white text-gray-900" />
                                    <div className="relative w-24">
                                        <span className="absolute left-1.5 top-1/2 -translate-y-1/2 text-[10px] text-gray-400 font-bold">R$</span>
                                        <input type="number" step="0.01" value={opt.priceExtra} onChange={e => updateOptionInGroup(group.id, idx, { priceExtra: parseFloat(e.target.value) })} className="w-full pl-6 pr-2 py-1 text-sm border rounded bg-white text-brand-primary font-bold" />
                                    </div>
                                    <button type="button" onClick={() => removeOptionFromGroup(group.id, idx)} className="text-gray-300 hover:text-red-500">
                                        <TrashIcon className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                            <button type="button" onClick={() => addOptionToGroup(group.id)} className="w-full py-2 border-2 border-dashed border-gray-200 rounded-lg text-xs font-bold text-gray-400 hover:border-brand-primary hover:text-brand-primary transition-all">
                                + Adicionar Opção ao Grupo
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

const SearchableSelect: React.FC<{
    options: CategoryMetadata[];
    value: string;
    onChange: (value: string) => void;
    placeholder: string;
}> = ({ options, value, onChange, placeholder }) => {
    const [isOpen, setIsOpen] = useState(false);
    const [search, setSearch] = useState('');
    const containerRef = useRef<HTMLDivElement>(null);

    const filteredOptions = useMemo(() => {
        return options.filter(opt => 
            opt.name.toLowerCase().includes(search.toLowerCase())
        );
    }, [options, search]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const selectedCategory = options.find(o => o.name === value);

    return (
        <div className="relative mt-1" ref={containerRef}>
            <button
                type="button"
                onClick={() => setIsOpen(!isOpen)}
                className="relative w-full bg-white border border-gray-300 rounded-md shadow-sm pl-3 pr-10 py-2 text-left cursor-default focus:outline-none focus:ring-1 focus:ring-brand-primary focus:border-brand-primary sm:text-sm"
            >
                <span className="block truncate text-gray-900">
                    {selectedCategory ? (
                        <span className="flex items-center gap-2">
                            {selectedCategory.isArchived ? '📦' : '📂'} {selectedCategory.name}
                        </span>
                    ) : (
                        <span className="text-gray-400">{placeholder}</span>
                    )}
                </span>
                <span className="absolute inset-y-0 right-0 flex items-center pr-2 pointer-events-none">
                    <svg className="h-5 w-5 text-gray-400 transform transition-transform duration-200" style={{ transform: isOpen ? 'rotate(-90deg)' : 'rotate(90deg)' }} viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
                    </svg>
                </span>
            </button>

            {isOpen && (
                <div className="absolute z-50 mt-1 w-full bg-white shadow-lg max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                    <div className="sticky top-0 z-10 bg-white px-2 py-2 border-b border-gray-100">
                        <div className="relative">
                            <SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
                            <input
                                type="text"
                                className="block w-full pl-8 pr-3 py-1.5 border border-gray-200 rounded-md text-sm focus:ring-brand-primary focus:border-brand-primary"
                                placeholder="Pesquisar categoria..."
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                                onClick={(e) => e.stopPropagation()}
                                autoFocus
                            />
                        </div>
                    </div>
                    <ul className="max-h-48 overflow-y-auto">
                        {filteredOptions.length > 0 ? (
                            filteredOptions.map((opt) => (
                                <li
                                    key={opt.name}
                                    onClick={() => {
                                        onChange(opt.name);
                                        setIsOpen(false);
                                        setSearch('');
                                    }}
                                    className={`cursor-pointer select-none relative py-2 pl-3 pr-9 hover:bg-brand-secondary/30 transition-colors ${
                                        value === opt.name ? 'bg-brand-secondary/50 text-brand-primary font-semibold' : 'text-gray-900'
                                    }`}
                                >
                                    <div className="flex items-center gap-2">
                                        <span className="text-xs">{opt.isArchived ? '📦' : '📂'}</span>
                                        <span className="block truncate">{opt.name}</span>
                                        {opt.isArchived && <span className="text-[10px] text-gray-400 uppercase font-bold">(Arquivada)</span>}
                                    </div>
                                    {value === opt.name && (
                                        <span className="absolute inset-y-0 right-0 flex items-center pr-4 text-brand-primary">
                                            <svg className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                                <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                                            </svg>
                                        </span>
                                    )}
                                </li>
                            ))
                        ) : (
                            <li className="py-4 text-center text-gray-500 text-sm">Nenhuma categoria encontrada</li>
                        )}
                    </ul>
                </div>
            )}
        </div>
    );
};

