export default CheckoutPage;

import * as https from "https";
import { Buffer } from "buffer";

interface ApiRequest {
    method?: string;
    body: any;
}

interface ApiResponse {
    setHeader: (key: string, value: any) => void;
    status: (code: number) => {
        json: (data: any) => void;
        end: (message?: string) => void;
    };
}

const formatPrice = (price: number) => (price || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

const formatDisplayDate = (dateString: string) => {
    if (!dateString) return 'N/A';
    try {
        const date = new Date(dateString + 'T00:00:00');
        return new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' }).format(date);
    } catch (e) {
        return dateString;
    }
}

const escapeHtml = (unsafe: string) => {
    return (unsafe || '')
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
};

async function sendNewOrderNotification(order: any) {
    const botToken = process.env.TELEGRAM_BOT_TOKEN;
    const chatId = process.env.TELEGRAM_CHAT_ID;

    if (!botToken || !chatId) {
        throw new Error("Telegram Bot Token or Chat ID not configured.");
    }

    const itemsList = (order.items || []).map((item: any) => {
        let text = `• <b>${item.quantity}x</b> ${escapeHtml(item.name)}`;
        if (item.option) {
            text += ` (<i>${escapeHtml(item.option)}</i>)`;
        }

        // Detalhamento das Customizações
        if (item.selectedCustomizations && item.selectedCustomizations.length > 0) {
            item.selectedCustomizations.forEach((group: any) => {
                const opts = group.items.map((it: any) => `${it.quantity}x ${it.name}`).join(', ');
                text += `\n   └ <b>${escapeHtml(group.groupName)}:</b> ${escapeHtml(opts)}`;
            });
        }

        if (item.observations) {
            text += `\n   <pre>Obs: ${escapeHtml(item.observations)}</pre>`;
        }
        return text;
    }).join("\n\n");

    const address = order.delivery?.address || {};
    const fullAddress = escapeHtml(`${address.street || ''}, ${address.number || ''}${address.complement ? `, ${address.complement}` : ''} - ${address.neighborhood || ''}`);

    const rawWhatsapp = (order.customer?.whatsapp || '').replace(/\D/g, '');
    const whatsappLink = `https://wa.me/55${rawWhatsapp}`;

    const message = `<b>🔔 NOVO PEDIDO - #${order.orderNumber} 🔔</b>

<b>🗓️ DATA AGENDADA:</b>
<b>${formatDisplayDate(order.deliveryDate)}</b>

---

<b>👤 CLIENTE</b>
<b>Nome:</b> ${escapeHtml(order.customer?.name)}
<b>WhatsApp:</b> ${escapeHtml(order.customer?.whatsapp)}
<a href="${whatsappLink}">💬 Iniciar conversa no WhatsApp</a>

---

<b>📦 ITENS DO PEDIDO</b>
${itemsList}

---

<b>💰 PAGAMENTO</b>
<b>Subtotal:</b> ${formatPrice(order.total)}
<b>Método:</b> ${escapeHtml(order.paymentMethod)}

---

<b>🚚 ENDEREÇO DE ENTREGA</b>
${fullAddress}
<b>CEP:</b> ${escapeHtml(address.cep)}`;

    const data = JSON.stringify({
      chat_id: chatId,
      text: message,
      parse_mode: "HTML",
      disable_web_page_preview: true,
      reply_markup: {
        inline_keyboard: [[{ text: "🌐 Abrir Painel Admin", url: "https://pipper-psi.vercel.app/" }]],
      },
    });

    const options = {
      hostname: "api.telegram.org",
      port: 443,
      path: `/bot${botToken}/sendMessage`,
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Content-Length": Buffer.byteLength(data),
      },
    };

    return new Promise<void>((resolve, reject) => {
        const req = https.request(options, (res) => {
          res.on("end", () => (res.statusCode! >= 200 && res.statusCode! < 300) ? resolve() : reject());
        });
        req.on("error", (error) => reject(error));
        req.write(data);
        req.end();
    });
}

export default async function handler(req: ApiRequest, res: ApiResponse) {
    if (req.method !== 'POST') return res.status(405).end();
    try {
        await sendNewOrderNotification(req.body.order);
        return res.status(200).json({ message: 'Notification sent successfully.' });
    } catch (error: any) {
        return res.status(500).json({ error: 'Failed' });
    }
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Product, ProductOption, CustomizationGroup, CustomizationOption, SelectedCustomization } from '../types';
import { ArrowLeftIcon, PlusIcon, MinusIcon, ShoppingBagIcon, ExpandIcon, XIcon, ChevronLeftIcon, ChevronRightIcon, CheckCircleIcon } from './IconComponents';

interface ProductDetailModalProps {
  product: Product | null;
  onClose: () => void;
  onAddToCart: (product: Product, quantity: number, observations?: string, selectedOption?: ProductOption, selectedCustomizations?: SelectedCustomization[]) => void;
}

const ProductDetailModal: React.FC<ProductDetailModalProps> = ({ product, onClose, onAddToCart }) => {
  const [quantity, setQuantity] = useState(1);
  const [observations, setObservations] = useState('');
  const [isImageFullscreen, setIsImageFullscreen] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [selectedOption, setSelectedOption] = useState<ProductOption | null>(null);

  // Estado para armazenar as seleções: { [groupId]: { [optionName]: quantidade } }
  const [customSelections, setCustomSelections] = useState<Record<string, Record<string, number>>>({});

  useEffect(() => {
    if (product) {
      setQuantity(1);
      setObservations('');
      setIsImageFullscreen(false);
      setCurrentImageIndex(0);
      setCustomSelections({});
      if (product.options && product.options.length > 0) {
          setSelectedOption(product.options[0]);
      } else {
          setSelectedOption(null);
      }
    }
  }, [product]);

  const handleImageNavigation = useCallback((direction: 'next' | 'prev') => {
    if (!product) return;
    const newIndex = direction === 'next'
      ? (currentImageIndex + 1) % product.imageUrls.length
      : (currentImageIndex - 1 + product.imageUrls.length) % product.imageUrls.length;
    setCurrentImageIndex(newIndex);
  }, [currentImageIndex, product]);

  const handleQuantityChange = (amount: number) => {
    setQuantity(prev => {
        const next = Math.max(1, prev + amount);
        if (product?.inventoryEnabled && next > (product.inventoryQuantity || 0)) {
            return prev;
        }
        return next;
    });
  };

  // Cálculo de extras e validação de grupos em tempo real
  const { extraTotal, isAllGroupsValid, formattedCustomizations } = useMemo(() => {
    let total = 0;
    let allValid = true;
    const result: SelectedCustomization[] = [];

    if (!product?.customizationGroups) return { extraTotal: 0, isAllGroupsValid: true, formattedCustomizations: [] };

    for (const group of product.customizationGroups) {
      const groupSelections = customSelections[group.id] || {};
      // Fix: Explicitly type reduce parameters to resolve unknown operator error
      const totalInGroup = Object.values(groupSelections).reduce((a: number, b: number) => a + b, 0);

      if (totalInGroup < group.min || totalInGroup > group.max) {
        allValid = false;
      }

      const items = [];
      for (const [optName, optQtyValue] of Object.entries(groupSelections)) {
        // Fix: Cast optQtyValue to number for arithmetic operations
        const optQty = optQtyValue as number;
        if (optQty > 0) {
          const opt = group.options.find(o => o.name === optName);
          if (opt) {
            total += (opt.priceExtra * optQty);
            items.push({ name: opt.name, quantity: optQty, priceExtra: opt.priceExtra });
          }
        }
      }
      if (items.length > 0) {
        result.push({ groupName: group.name, items });
      }
    }
    return { extraTotal: total, isAllGroupsValid: allValid, formattedCustomizations: result };
  }, [product, customSelections]);

  const handleCustomOptionChange = (group: CustomizationGroup, option: CustomizationOption, delta: number) => {
    setCustomSelections(prev => {
      const groupSelections = { ...(prev[group.id] || {}) };
      // Fix: Cast groupSelections entry to number
      const currentQty = (groupSelections[option.name] as number) || 0;
      // Fix: Explicitly type reduce parameters to resolve unknown operator error
      const totalInGroup = Object.values(groupSelections).reduce((a: number, b: number) => a + b, 0);

      if (group.type === 'single') {
        if (delta > 0) {
          return { ...prev, [group.id]: { [option.name]: 1 } };
        } else {
          return { ...prev, [group.id]: {} };
        }
      }

      const newQty = Math.max(0, currentQty + delta);
      if (delta > 0 && totalInGroup >= group.max) return prev;

      return {
        ...prev,
        [group.id]: {
          ...groupSelections,
          [option.name]: newQty
        }
      };
    });
  };

  const handleAddToCartClick = () => {
    if (product) {
        if (product.options && product.options.length > 0 && !selectedOption) {
            alert("Por favor, selecione uma opção.");
            return;
        }

        if (!isAllGroupsValid) {
            alert("Por favor, preencha as opções obrigatórias.");
            return;
        }

      onAddToCart(product, quantity, observations, selectedOption || undefined, formattedCustomizations);
    }
  };

  const formatPrice = (price: number) => {
    return price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  if (!product) return null;

  const basePrice = selectedOption ? selectedOption.price : product.price;
  const totalPrice = (basePrice + extraTotal) * quantity;
  const isSoldOut = product.inventoryEnabled && (product.inventoryQuantity || 0) <= 0;

  return (
    <>
      {isImageFullscreen && (
        <div className="fixed inset-0 bg-black z-[70] flex items-center justify-center p-4" onClick={() => setIsImageFullscreen(false)}>
            <button className="absolute top-4 right-4 text-white p-2"><XIcon className="w-8 h-8"/></button>
            <img src={product.imageUrls[currentImageIndex]} className="max-h-full max-w-full object-contain rounded" alt={product.name}/>
        </div>
      )}

      <div className="fixed inset-0 z-50 bg-white flex flex-col animate-slide-in-up overflow-y-auto no-scrollbar">
        <style>{`.animate-slide-in-up { animation: slideInUp 0.3s ease-out; } @keyframes slideInUp { from { transform: translateY(100%); } to { transform: translateY(0); } }`}</style>

        <div className="flex-1 pb-32"> 
          <div className="max-w-2xl mx-auto w-full">
            {product.imageUrls && product.imageUrls.length > 0 ? (
              <div className="relative aspect-square sm:aspect-video w-full bg-gray-100">
                  <img src={product.imageUrls[currentImageIndex]} alt={product.name} className={`w-full h-full object-cover ${isSoldOut ? 'grayscale' : ''}`} onClick={() => setIsImageFullscreen(true)}/>
                  <button onClick={onClose} className="absolute top-4 left-4 p-2 bg-white/80 rounded-full shadow-md"><ArrowLeftIcon className="w-6 h-6"/></button>
                  {isSoldOut && <div className="absolute inset-0 bg-black/40 flex items-center justify-center"><span className="bg-red-600 text-white font-bold px-6 py-2 rounded uppercase">Esgotado</span></div>}
              </div>
            ) : (
               <div className="p-4 border-b flex items-center sticky top-0 bg-white z-20">
                  <button onClick={onClose} className="p-2 -ml-2 rounded-full hover:bg-gray-100"><ArrowLeftIcon className="w-6 h-6"/></button>
                  <h1 className="ml-2 text-lg font-bold text-brand-text truncate">{product.name}</h1>
              </div>
            )}

            <div className="p-6 space-y-8">
                <div>
                    <h1 className="text-2xl font-bold text-brand-text">{product.name}</h1>
                    <p className="text-brand-text-light text-base mt-2 leading-relaxed">{product.description}</p>
                </div>

                {product.options && product.options.length > 0 && !isSoldOut && (
                    <div className="space-y-4">
                        <h3 className="text-base font-bold text-brand-text border-l-4 border-brand-primary pl-3">Escolha uma opção</h3>
                        <div className="grid gap-3">
                            {product.options.map((option, index) => (
                                <button key={index} onClick={() => setSelectedOption(option)}
                                    className={`flex items-center justify-between p-4 rounded-xl border transition-all ${selectedOption?.name === option.name ? 'border-brand-primary bg-brand-secondary/20 ring-1 ring-brand-primary' : 'border-gray-200'}`}
                                >
                                    <span className="font-bold text-brand-text">{option.name}</span>
                                    <span className="font-bold text-brand-primary">{formatPrice(option.price)}</span>
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* Grupos de Personalização (Estilo Dino) */}
                {product.customizationGroups?.map((group) => {
                  const groupSelections = customSelections[group.id] || {};
                  // Fix: Explicitly type reduce parameters to resolve unknown operator error
                  const totalInGroup = Object.values(groupSelections).reduce((a: number, b: number) => a + b, 0);
                  const isValid = totalInGroup >= group.min && totalInGroup <= group.max;

                  return (
                    <div key={group.id} className="pt-6 border-t border-gray-100 space-y-4">
                        <div className="flex justify-between items-start">
                            <div>
                                <h3 className="text-base font-bold text-brand-text">{group.name}</h3>
                                <p className="text-xs text-gray-400">
                                    {group.min === group.max ? `Escolha ${group.min}` : `Escolha de ${group.min} a ${group.max}`}
                                </p>
                            </div>
                            {isValid ? (
                                <CheckCircleIcon className="w-5 h-5 text-green-500" />
                            ) : (
                                <span className="text-[10px] font-black bg-amber-100 text-amber-700 px-2 py-0.5 rounded uppercase">Obrigatório</span>
                            )}
                        </div>

                        <div className="space-y-3">
                            {group.options.map((opt) => {
                                // Fix: Cast groupSelections entry to number
                                const qty = (groupSelections[opt.name] as number) || 0;
                                return (
                                    <div key={opt.name} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${qty > 0 ? 'border-brand-primary/50 bg-brand-secondary/10' : 'border-gray-50'}`}>
                                        <div className="flex-grow pr-4">
                                            <p className="text-sm font-bold text-brand-text">{opt.name}</p>
                                            {opt.priceExtra > 0 && <p className="text-xs text-brand-accent font-bold">+{formatPrice(opt.priceExtra)}</p>}
                                        </div>

                                        <div className="flex items-center bg-white rounded-lg border border-gray-100 shadow-sm">
                                            <button onClick={() => handleCustomOptionChange(group, opt, -1)} className={`p-2 ${qty === 0 ? 'opacity-20' : 'text-brand-text'}`}><MinusIcon className="w-4 h-4"/></button>
                                            <span className="px-3 text-sm font-black w-8 text-center text-brand-text">{qty}</span>
                                            <button onClick={() => handleCustomOptionChange(group, opt, 1)} className={`p-2 ${(totalInGroup >= group.max && group.type !== 'single') ? 'opacity-20' : 'text-brand-primary'}`}><PlusIcon className="w-4 h-4"/></button>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                  );
                })}

                {!isSoldOut && (
                    <div className="pt-6 border-t border-gray-100">
                        <label className="block text-sm font-bold text-brand-text mb-2">Observações</label>
                        <textarea value={observations} onChange={(e) => setObservations(e.target.value)} rows={3} placeholder="Algum pedido especial? (Ex: Sem amendoim)"
                            className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-brand-primary outline-none text-gray-900"
                        />
                    </div>
                )}
            </div>
          </div>
        </div>

        {!isSoldOut && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 p-4 shadow-xl z-30">
                <div className="max-w-2xl mx-auto flex items-center gap-4">
                    <div className="flex items-center bg-gray-100 rounded-full p-1">
                      <button onClick={() => handleQuantityChange(-1)} disabled={quantity === 1} className="p-3 disabled:opacity-30"><MinusIcon className="w-5 h-5 text-gray-700" /></button>
                      <span className="px-4 text-xl font-black w-12 text-center text-brand-text">{quantity}</span>
                      <button onClick={() => handleQuantityChange(1)} className="p-3"><PlusIcon className="w-5 h-5 text-gray-700" /></button>
                    </div>

                    <button onClick={handleAddToCartClick} disabled={!isAllGroupsValid}
                      className="flex-grow bg-brand-primary text-white font-black py-4 px-6 rounded-2xl flex items-center justify-between shadow-lg hover:brightness-105 transition-all disabled:opacity-50"
                    >
                        <span className="flex items-center gap-2"><ShoppingBagIcon className="w-6 h-6" /> Adicionar</span>
                        <span>{formatPrice(totalPrice)}</span>
                    </button>
                </div>
            </div>
        )}
      </div>
    </>
  );
};

