                                            <p className="text-sm font-bold text-brand-text">{opt.name}</p>
                                            {opt.priceExtra > 0 && <p className="text-xs text-brand-accent font-bold">+{formatPrice(opt.priceExtra)}</p>}
                                        </div>

                                        <div className="flex items-center bg-white rounded-lg border border-gray-100 shadow-sm">
                                            <button onClick={() => handleCustomOptionChange(group, opt, -1)} className={`p-2 transition-opacity ${qty === 0 ? 'opacity-20 text-gray-300' : 'text-gray-900'}`}><MinusIcon className="w-4 h-4"/></button>
                                            <span className="px-3 text-sm font-black w-8 text-center text-brand-text">{qty}</span>
                                            <button onClick={() => handleCustomOptionChange(group, opt, 1)} className={`p-2 transition-opacity ${(totalInGroup >= group.max && group.type !== 'single') ? 'opacity-20 text-gray-300' : 'text-brand-primary'}`}><PlusIcon className="w-4 h-4"/></button>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                  );
                })}

                {!isSoldOut && (
                    <div className="pt-6 border-t border-gray-100">
                        <label className="block text-sm font-bold text-brand-text mb-2">Observações</label>
                        <textarea 
                            value={observations} 
                            onChange={(e) => setObservations(e.target.value)} 
                            rows={3} 
                            placeholder="Algum pedido especial? (Ex: Sem amendoim)"
                            className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-brand-primary outline-none text-gray-900 placeholder-gray-400"
                        />
                    </div>
                )}
            </div>
          </div>
        </div>

        {/* Barra de Ação Inferior */}
        {!isSoldOut && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 p-4 pb-safe shadow-2xl z-30">
                <div className="max-w-2xl mx-auto flex items-center gap-4">
                    <div className="flex items-center bg-gray-100 rounded-full p-1 border border-gray-200">
                      <button onClick={() => handleQuantityChange(-1)} disabled={quantity === 1} className="p-3 disabled:opacity-30 text-gray-900"><MinusIcon className="w-5 h-5" /></button>
                      <span className="px-4 text-xl font-black w-12 text-center text-brand-text">{quantity}</span>
                      <button onClick={() => handleQuantityChange(1)} className="p-3 text-gray-900"><PlusIcon className="w-5 h-5" /></button>
                    </div>

                    <button onClick={handleAddToCartClick} disabled={!isAllGroupsValid}
                      className="flex-grow bg-brand-primary text-white font-black py-4 px-6 rounded-2xl flex items-center justify-between shadow-lg hover:brightness-105 active:scale-95 transition-all disabled:opacity-50"
                    >
                        <span className="flex items-center gap-2">
                          <ShoppingBagIcon className="w-6 h-6 text-brand-secondary" /> 
                          Adicionar
                        </span>
                        <span className="text-lg">{formatPrice(totalPrice)}</span>
                    </button>
                </div>
            </div>
        )}
      </div>
    </>
  );
};

export default ProductDetailModal;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Product, ProductOption, CustomizationGroup, CustomizationOption, SelectedCustomization } from '../types';
import { ArrowLeftIcon, PlusIcon, MinusIcon, ShoppingBagIcon, XIcon, CheckCircleIcon, ChevronLeftIcon, ChevronRightIcon } from './IconComponents';

interface ProductDetailModalProps {
  product: Product | null;
  onClose: () => void;
  onAddToCart: (product: Product, quantity: number, observations?: string, selectedOption?: ProductOption, selectedCustomizations?: SelectedCustomization[]) => void;
}

const ProductDetailModal: React.FC<ProductDetailModalProps> = ({ product, onClose, onAddToCart }) => {
  const [quantity, setQuantity] = useState(1);
  const [observations, setObservations] = useState('');
  const [isImageFullscreen, setIsImageFullscreen] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [selectedOption, setSelectedOption] = useState<ProductOption | null>(null);

  const [customSelections, setCustomSelections] = useState<Record<string, Record<string, number>>>({});

  useEffect(() => {
    if (product) {
      setQuantity(1);
      setObservations('');
      setIsImageFullscreen(false);
      setCurrentImageIndex(0);
      setCustomSelections({});
      if (product.options && product.options.length > 0) {
          setSelectedOption(product.options[0]);
      } else {
          setSelectedOption(null);
      }
    }
  }, [product]);

  const handleImageNavigation = useCallback((direction: 'next' | 'prev') => {
    if (!product) return;
    const newIndex = direction === 'next'
      ? (currentImageIndex + 1) % product.imageUrls.length
      : (currentImageIndex - 1 + product.imageUrls.length) % product.imageUrls.length;
    setCurrentImageIndex(newIndex);
  }, [currentImageIndex, product]);

  const handleQuantityChange = (amount: number) => {
    setQuantity(prev => {
        const next = Math.max(1, prev + amount);
        if (product?.inventoryEnabled && next > (product.inventoryQuantity || 0)) {
            return prev;
        }
        return next;
    });
  };

  const { extraTotal, isAllGroupsValid, formattedCustomizations } = useMemo(() => {
    let total = 0;
    let allValid = true;
    const result: SelectedCustomization[] = [];

    if (!product?.customizationGroups) return { extraTotal: 0, isAllGroupsValid: true, formattedCustomizations: [] };

    for (const group of product.customizationGroups) {
      const groupSelections = customSelections[group.id] || {};
      const totalInGroup = (Object.values(groupSelections) as number[]).reduce((a: number, b: number) => a + b, 0);

      if (totalInGroup < group.min || totalInGroup > group.max) {
        allValid = false;
      }

      const items = [];
      for (const [optName, optQtyValue] of Object.entries(groupSelections)) {
        const optQty = optQtyValue as number;
        if (optQty > 0) {
          const opt = group.options.find(o => o.name === optName);
          if (opt) {
            total += (opt.priceExtra * optQty);
            items.push({ name: opt.name, quantity: optQty, priceExtra: opt.priceExtra });
          }
        }
      }
      if (items.length > 0) {
        result.push({ groupName: group.name, items });
      }
    }
    return { extraTotal: total, isAllGroupsValid: allValid, formattedCustomizations: result };
  }, [product, customSelections]);

  const handleCustomOptionChange = (group: CustomizationGroup, option: CustomizationOption, delta: number) => {
    setCustomSelections(prev => {
      const groupSelections: Record<string, number> = { ...(prev[group.id] || {}) };
      const currentQty = (groupSelections[option.name] as number) || 0;
      const totalInGroup = (Object.values(groupSelections) as number[]).reduce((a: number, b: number) => a + b, 0);

      if (group.type === 'single') {
        if (delta > 0) {
          return { ...prev, [group.id]: { [option.name]: 1 } };
        } else {
          return { ...prev, [group.id]: {} };
        }
      }

      const newQty = Math.max(0, currentQty + delta);
      if (delta > 0 && totalInGroup >= group.max) return prev;

      return {
        ...prev,
        [group.id]: {
          ...groupSelections,
          [option.name]: newQty
        }
      };
    });
  };

  const handleAddToCartClick = () => {
    if (product) {
        if (product.options && product.options.length > 0 && !selectedOption) {
            alert("Por favor, selecione uma opção.");
            return;
        }
        if (!isAllGroupsValid) {
            alert("Por favor, preencha as opções obrigatórias.");
            return;
        }
      onAddToCart(product, quantity, observations, selectedOption || undefined, formattedCustomizations);
    }
  };

  const formatPrice = (price: number) => {
    return price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  if (!product) return null;

  const basePrice = selectedOption ? selectedOption.price : product.price;
  const totalPrice = (basePrice + extraTotal) * quantity;
  const isSoldOut = product.inventoryEnabled && (product.inventoryQuantity || 0) <= 0;

  return (
    <>
      {isImageFullscreen && (
        <div className="fixed inset-0 bg-black z-[70] flex items-center justify-center p-4" onClick={() => setIsImageFullscreen(false)}>
            <button className="absolute top-4 right-4 text-white p-2"><XIcon className="w-8 h-8"/></button>
            <img src={product.imageUrls[currentImageIndex]} className="max-h-full max-w-full object-contain rounded" alt={product.name}/>
        </div>
      )}

      <div className="fixed inset-0 z-50 bg-white flex flex-col animate-slide-in-up overflow-y-auto no-scrollbar">
        <style>{`.animate-slide-in-up { animation: slideInUp 0.3s ease-out; } @keyframes slideInUp { from { transform: translateY(100%); } to { transform: translateY(0); } }`}</style>

        <div className="flex-1 pb-32"> 
          <div className="max-w-2xl mx-auto w-full relative">

            {/* Imagem do Produto com Botão de Voltar e Carrossel */}
            {product.imageUrls && product.imageUrls.length > 0 ? (
              <div className="relative aspect-square sm:aspect-video w-full bg-gray-100">
                  <img 
                    src={product.imageUrls[currentImageIndex]} 
                    alt={product.name} 
                    className={`w-full h-full object-cover cursor-pointer ${isSoldOut ? 'grayscale' : ''}`} 
                    onClick={() => setIsImageFullscreen(true)}
                  />

                  {/* Seta de Voltar (Fixa na Imagem) */}
                  <button 
                    onClick={onClose} 
                    className="absolute top-4 left-4 p-2 bg-white/90 rounded-full shadow-lg text-gray-900 hover:bg-white transition-all active:scale-90 z-20"
                    aria-label="Voltar"
                  >
                    <ArrowLeftIcon className="w-6 h-6" />
                  </button>

                  {/* Controles do Carrossel (Aparecem apenas se houver mais de uma imagem) */}
                  {product.imageUrls.length > 1 && (
                    <>
                      <button 
                        onClick={() => handleImageNavigation('prev')}
                        className="absolute left-2 top-1/2 -translate-y-1/2 p-1.5 bg-black/30 hover:bg-black/50 text-white rounded-full transition-all z-10"
                      >
                        <ChevronLeftIcon className="w-6 h-6" />
                      </button>
                      <button 
                        onClick={() => handleImageNavigation('next')}
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-black/30 hover:bg-black/50 text-white rounded-full transition-all z-10"
                      >
                        <ChevronRightIcon className="w-6 h-6" />
                      </button>
                      {/* Indicadores de Página */}
                      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-1.5 z-10">
                        {product.imageUrls.map((_, idx) => (
                          <div 
                            key={idx} 
                            className={`w-2 h-2 rounded-full transition-all ${idx === currentImageIndex ? 'bg-white w-4' : 'bg-white/50'}`}
                          />
                        ))}
                      </div>
                    </>
                  )}

                  {isSoldOut && (
                    <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
                      <span className="bg-red-600 text-white font-bold px-6 py-2 rounded uppercase tracking-widest">Esgotado</span>
                    </div>
                  )}
              </div>
            ) : (
               <div className="p-4 border-b flex items-center sticky top-0 bg-white z-20">
                  <button onClick={onClose} className="p-2 -ml-2 rounded-full hover:bg-gray-100 text-gray-900"><ArrowLeftIcon className="w-6 h-6"/></button>
                  <h1 className="ml-2 text-lg font-bold text-brand-text truncate">{product.name}</h1>
              </div>
            )}

            <div className="p-6 space-y-8">
                <div>
                    <h1 className="text-2xl font-bold text-brand-text">{product.name}</h1>
                    <p className="text-brand-text-light text-base mt-2 leading-relaxed">{product.description}</p>
                </div>

                {/* Variações de Tamanho/Opção */}
                {product.options && product.options.length > 0 && !isSoldOut && (
                    <div className="space-y-4">
                        <h3 className="text-base font-bold text-brand-text border-l-4 border-brand-primary pl-3">Escolha uma opção</h3>
                        <div className="grid gap-3">
                            {product.options.map((option, index) => (
                                <button key={index} onClick={() => setSelectedOption(option)}
                                    className={`flex items-center justify-between p-4 rounded-xl border transition-all ${selectedOption?.name === option.name ? 'border-brand-primary bg-brand-secondary/20 ring-1 ring-brand-primary shadow-sm' : 'border-gray-200'}`}
                                >
                                    <span className="font-bold text-brand-text">{option.name}</span>
                                    <span className="font-bold text-brand-primary">{formatPrice(option.price)}</span>
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* Grupos de Personalização */}
                {product.customizationGroups?.map((group) => {
                  const groupSelections = customSelections[group.id] || {};
                  const totalInGroup = (Object.values(groupSelections) as number[]).reduce((a: number, b: number) => a + b, 0);
                  const isValid = totalInGroup >= group.min && totalInGroup <= group.max;

                  return (
                    <div key={group.id} className="pt-6 border-t border-gray-100 space-y-4">
                        <div className="flex justify-between items-start">
                            <div>
                                <h3 className="text-base font-bold text-brand-text">{group.name}</h3>
                                <p className="text-xs text-gray-400">
                                    {group.min === group.max ? `Escolha ${group.min}` : `Escolha de ${group.min} a ${group.max}`}
                                </p>
                            </div>
                            {isValid ? (
                                <CheckCircleIcon className="w-5 h-5 text-green-500" />
                            ) : (
                                <span className="text-[10px] font-black bg-amber-100 text-amber-700 px-2 py-0.5 rounded uppercase">Obrigatório</span>
                            )}
                        </div>

                        <div className="space-y-3">
                            {group.options.map((opt) => {
                                const qty = (groupSelections[opt.name] as number) || 0;
                                return (
                                    <div key={opt.name} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${qty > 0 ? 'border-brand-primary/50 bg-brand-secondary/10' : 'border-gray-50'}`}>
                                        <div className="flex-grow pr-4">
                                            <p className="text-sm font-bold text-brand-text">{opt.name}</p>
                                            {opt.priceExtra > 0 && <p className="text-xs text-brand-accent font-bold">+{formatPrice(opt.priceExtra)}</p>}
                                        </div>

                                        <div className="flex items-center bg-white rounded-lg border border-gray-100 shadow-sm">
                                            <button onClick={() => handleCustomOptionChange(group, opt, -1)} className={`p-2 transition-opacity ${qty === 0 ? 'opacity-20 text-gray-300' : 'text-gray-900'}`}><MinusIcon className="w-4 h-4"/></button>
                                            <span className="px-3 text-sm font-black w-8 text-center text-brand-text">{qty}</span>
                                            <button onClick={() => handleCustomOptionChange(group, opt, 1)} className={`p-2 transition-opacity ${(totalInGroup >= group.max && group.type !== 'single') ? 'opacity-20 text-gray-300' : 'text-brand-primary'}`}><PlusIcon className="w-4 h-4"/></button>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                  );
                })}

                {!isSoldOut && (
                    <div className="pt-6 border-t border-gray-100">
                        <label className="block text-sm font-bold text-brand-text mb-2">Observações</label>
                        <textarea 
                            value={observations} 
                            onChange={(e) => setObservations(e.target.value)} 
                            rows={3} 
                            placeholder="Algum pedido especial? (Ex: Sem amendoim)"
                            className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-brand-primary outline-none text-gray-900 placeholder-gray-400 shadow-sm"
                        />
                    </div>
                )}
            </div>
          </div>
        </div>

        {/* Barra de Ação Inferior */}
        {!isSoldOut && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 p-4 pb-safe shadow-2xl z-30">
                <div className="max-w-2xl mx-auto flex items-center gap-4">
                    <div className="flex items-center bg-gray-100 rounded-full p-1 border border-gray-200">
                      <button onClick={() => handleQuantityChange(-1)} disabled={quantity === 1} className="p-3 disabled:opacity-30 text-gray-900"><MinusIcon className="w-5 h-5" /></button>
                      <span className="px-4 text-xl font-black w-12 text-center text-brand-text">{quantity}</span>
                      <button onClick={() => handleQuantityChange(1)} className="p-3 text-gray-900"><PlusIcon className="w-5 h-5" /></button>
                    </div>

                    <button onClick={handleAddToCartClick} disabled={!isAllGroupsValid}
                      className="flex-grow bg-brand-primary text-white font-black py-4 px-6 rounded-2xl flex items-center justify-between shadow-lg hover:brightness-105 active:scale-95 transition-all disabled:opacity-50"
                    >
                        <span className="flex items-center gap-2">
                          <ShoppingBagIcon className="w-6 h-6 text-brand-secondary" /> 
                          Adicionar
                        </span>
                        <span className="text-lg">{formatPrice(totalPrice)}</span>
                    </button>
                </div>
            </div>
        )}
      </div>
    </>
  );
};

export default ProductDetailModal;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import type { Product, ProductOption, CategoryMetadata, CustomizationGroup, CustomizationOption } from '../types';
import { TrashIcon, SearchIcon, DragHandleIcon, CopyIcon, PlusIcon, ChevronRightIcon, XIcon as CloseIcon } from './IconComponents';

interface ProductsViewProps {
  products: Product[];
  categories: CategoryMetadata[];
  onAddProduct: (productData: Omit<Product, 'id'>) => Promise<void>;
  onUpdateProduct: (productData: Product) => Promise<void>;
  onDeleteProduct: (productId: string) => Promise<void>;
  onAddCategory: (categoryName: string) => Promise<void>;
  onDeleteCategory: (categoryName: string) => Promise<void>;
  onUpdateCategoryOrder: (newOrder: CategoryMetadata[]) => Promise<void>;
  onToggleCategoriesArchive: (categoryNames: string[], archive: boolean) => Promise<void>;
}

const CustomizationEditor: React.FC<{
    groups: CustomizationGroup[];
    onChange: (groups: CustomizationGroup[]) => void;
}> = ({ groups, onChange }) => {
    const addGroup = () => {
        const newGroup: CustomizationGroup = {
            id: `group-${Date.now()}`,
            name: '',
            min: 0,
            max: 1,
            type: 'single',
            options: []
        };
        onChange([...groups, newGroup]);
    };

    const updateGroup = (id: string, data: Partial<CustomizationGroup>) => {
        onChange(groups.map(g => g.id === id ? { ...g, ...data } : g));
    };

    const removeGroup = (id: string) => {
        onChange(groups.filter(g => g.id !== id));
    };

    const addOptionToGroup = (groupId: string) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                return {
                    ...g,
                    options: [...g.options, { name: '', priceExtra: 0 }]
                };
            }
            return g;
        }));
    };

    const updateOptionInGroup = (groupId: string, optIndex: number, data: Partial<CustomizationOption>) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                const newOpts = [...g.options];
                newOpts[optIndex] = { ...newOpts[optIndex], ...data };
                return { ...g, options: newOpts };
            }
            return g;
        }));
    };

    const removeOptionFromGroup = (groupId: string, optIndex: number) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                return { ...g, options: g.options.filter((_, i) => i !== optIndex) };
            }
            return g;
        }));
    };

    return (
        <div className="bg-gray-50/50 p-4 rounded-xl border border-gray-200 mt-6 shadow-inner">
            <div className="flex justify-between items-center mb-6">
                <h4 className="text-sm font-black text-brand-primary uppercase tracking-widest">Personalizações & Adicionais</h4>
                <button 
                  type="button" 
                  onClick={addGroup} 
                  className="text-xs font-bold text-white bg-brand-primary px-4 py-2 rounded-lg hover:bg-brand-primary-dark transition-all shadow-sm"
                >
                    + Novo Grupo
                </button>
            </div>

            <div className="space-y-6">
                {groups.map((group) => (
                    <div key={group.id} className="bg-white p-5 rounded-xl border border-gray-100 shadow-sm relative group/card">
                        <button 
                          type="button" 
                          onClick={() => removeGroup(group.id)} 
                          className="absolute top-3 right-3 text-gray-300 hover:text-red-500 transition-colors"
                          title="Remover Grupo"
                        >
                            <TrashIcon className="w-5 h-5" />
                        </button>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-5 pr-8">
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1 tracking-tight">Nome do Grupo (Ex: Escolha o sabor)</label>
                                <input 
                                  type="text" 
                                  value={group.name} 
                                  onChange={e => updateGroup(group.id, { name: e.target.value })} 
                                  placeholder="Título" 
                                  className="w-full px-3 py-2 border rounded-lg text-sm text-gray-900 bg-gray-50/30 focus:bg-white focus:ring-2 focus:ring-brand-primary outline-none transition-all" 
                                />
                            </div>
                            <div className="flex gap-3">
                                <div className="flex-1">
                                    <label className="block text-[10px] font-black text-gray-400 uppercase mb-1 tracking-tight">Mín</label>
                                    <input type="number" min="0" value={group.min} onChange={e => updateGroup(group.id, { min: parseInt(e.target.value) || 0 })} className="w-full px-3 py-2 border rounded-lg text-sm text-gray-900 bg-gray-50/30 focus:bg-white focus:ring-2 focus:ring-brand-primary outline-none transition-all" />
                                </div>
                                <div className="flex-1">
                                    <label className="block text-[10px] font-black text-gray-400 uppercase mb-1 tracking-tight">Máx</label>
                                    <input type="number" min="1" value={group.max} onChange={e => updateGroup(group.id, { max: parseInt(e.target.value) || 1, type: parseInt(e.target.value) > 1 ? 'counter' : 'single' })} className="w-full px-3 py-2 border rounded-lg text-sm text-gray-900 bg-gray-50/30 focus:bg-white focus:ring-2 focus:ring-brand-primary outline-none transition-all" />
                                </div>
                            </div>
                        </div>

                        <div className="space-y-2">
                            <p className="text-[10px] font-bold text-gray-400 uppercase mb-2">Itens da Lista</p>
                            {group.options.map((opt, idx) => (
                                <div key={idx} className="flex gap-2 items-center bg-gray-50/50 p-2 rounded-lg border border-gray-100 hover:border-gray-200 transition-colors">
                                    <input 
                                      type="text" 
                                      value={opt.name} 
                                      onChange={e => updateOptionInGroup(group.id, idx, { name: e.target.value })} 
                                      placeholder="Nome do item (Ex: Brigadeiro)" 
                                      className="flex-grow px-3 py-1.5 text-sm border border-gray-200 rounded-md bg-white text-gray-900 outline-none focus:ring-1 focus:ring-brand-primary" 
                                    />
                                    <div className="relative w-28">
                                        <span className="absolute left-2 top-1/2 -translate-y-1/2 text-[10px] text-gray-400 font-bold">R$</span>
                                        <input 
                                          type="number" 
                                          step="0.01" 
                                          value={opt.priceExtra} 
                                          onChange={e => updateOptionInGroup(group.id, idx, { priceExtra: parseFloat(e.target.value) || 0 })} 
                                          className="w-full pl-7 pr-2 py-1.5 text-sm border border-gray-200 rounded-md bg-white text-brand-primary font-black outline-none focus:ring-1 focus:ring-brand-primary" 
                                        />
                                    </div>
                                    <button 
                                      type="button" 
                                      onClick={() => removeOptionFromGroup(group.id, idx)} 
                                      className="p-1.5 text-gray-300 hover:text-red-500 hover:bg-white rounded-md transition-all shadow-sm"
                                    >
                                        <TrashIcon className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                            <button 
                              type="button" 
                              onClick={() => addOptionToGroup(group.id)} 
                              className="w-full py-3 border-2 border-dashed border-gray-200 rounded-xl text-xs font-bold text-gray-400 hover:border-brand-primary hover:text-brand-primary hover:bg-brand-primary/5 transition-all mt-2"
                            >
                                + Adicionar Opção ao Grupo
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

const SearchableSelect: React.FC<{
    options: CategoryMetadata[];
    value: string;
    onChange: (value: string) => void;
    placeholder: string;
}> = ({ options, value, onChange, placeholder }) => {
    const [isOpen, setIsOpen] = useState(false);
    const [search, setSearch] = useState('');
    const containerRef = useRef<HTMLDivElement>(null);

    const filteredOptions = useMemo(() => {
        return options.filter(opt => 
            opt.name.toLowerCase().includes(search.toLowerCase())
        );
    }, [options, search]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const selectedCategory = options.find(o => o.name === value);

    return (
        <div className="relative mt-1" ref={containerRef}>
            <button
                type="button"
                onClick={() => setIsOpen(!isOpen)}
                className="relative w-full bg-white border border-gray-300 rounded-lg shadow-sm pl-3 pr-10 py-2.5 text-left cursor-default focus:outline-none focus:ring-2 focus:ring-brand-primary sm:text-sm"
            >
                <span className="block truncate text-gray-900">
                    {selectedCategory ? (
                        <span className="flex items-center gap-2">
                            {selectedCategory.isArchived ? '📦' : '📂'} {selectedCategory.name}
                        </span>
                    ) : (
                        <span className="text-gray-400">{placeholder}</span>
                    )}
                </span>
                <span className="absolute inset-y-0 right-0 flex items-center pr-2 pointer-events-none">
                    <svg className="h-5 w-5 text-gray-400 transform transition-transform duration-200" style={{ transform: isOpen ? 'rotate(-90deg)' : 'rotate(90deg)' }} viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
                    </svg>
                </span>
            </button>

            {isOpen && (
                <div className="absolute z-50 mt-1 w-full bg-white shadow-2xl max-h-60 rounded-xl py-1 text-base ring-1 ring-black/5 overflow-auto focus:outline-none sm:text-sm border border-gray-100">
                    <div className="sticky top-0 z-10 bg-white px-2 py-2 border-b border-gray-100">
                        <div className="relative">
                            <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
                            <input
                                type="text"
                                className="block w-full pl-9 pr-3 py-2 border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-brand-primary outline-none"
                                placeholder="Pesquisar categoria..."
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                                onClick={(e) => e.stopPropagation()}
                                autoFocus
                            />
                        </div>
                    </div>
                    <ul className="max-h-48 overflow-y-auto p-1">
                        {filteredOptions.length > 0 ? (
                            filteredOptions.map((opt) => (
                                <li
                                    key={opt.name}
                                    onClick={() => {
                                        onChange(opt.name);
                                        setIsOpen(false);
                                        setSearch('');
                                    }}
                                    className={`cursor-pointer select-none relative py-2.5 pl-3 pr-9 rounded-lg hover:bg-brand-secondary/30 transition-colors ${
                                        value === opt.name ? 'bg-brand-secondary/50 text-brand-primary font-bold' : 'text-gray-900'
                                    }`}
                                >
                                    <div className="flex items-center gap-2">
                                        <span className="text-xs">{opt.isArchived ? '📦' : '📂'}</span>
                                        <span className="block truncate">{opt.name}</span>
                                        {opt.isArchived && <span className="text-[10px] text-gray-400 uppercase font-black tracking-tighter ml-auto">(Arquivada)</span>}
                                    </div>
                                    {value === opt.name && (
                                        <span className="absolute inset-y-0 right-0 flex items-center pr-4 text-brand-primary">
                                            <svg className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                                <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                                            </svg>
                                        </span>
                                    )}
                                </li>
                            ))
                        ) : (
                            <li className="py-4 text-center text-gray-500 text-sm">Nenhuma categoria encontrada</li>
                        )}
                    </ul>
                </div>
            )}
        </div>
    );
};

