interface ProductsViewProps {
  products: Product[];
  categories: CategoryMetadata[];
  onAddProduct: (productData: Omit<Product, 'id'>) => Promise<void>;
  onUpdateProduct: (productData: Product) => Promise<void>;
  onDeleteProduct: (productId: string) => Promise<void>;
  onAddCategory: (categoryName: string) => Promise<void>;
  onDeleteCategory: (categoryName: string) => Promise<void>;
  onUpdateCategoryOrder: (newOrder: CategoryMetadata[]) => Promise<void>;
  onToggleCategoriesArchive: (categoryNames: string[], archive: boolean) => Promise<void>;
}

// Main View for product and category management
const ProductsView: React.FC<ProductsViewProps> = ({ 
    products, 
    categories, 
    onAddProduct, 
    onUpdateProduct, 
    onDeleteProduct, 
    onAddCategory, 
    onDeleteCategory, 
    onUpdateCategoryOrder,
    onToggleCategoriesArchive
}) => {
  const activeCategoriesOnly = useMemo(() => categories.filter(c => !c.isArchived), [categories]);
  const archivedCategoriesOnly = useMemo(() => categories.filter(c => c.isArchived), [categories]);

  const sortedCategoriesForSelect = useMemo(() => {
    return [...activeCategoriesOnly, ...archivedCategoriesOnly];
  }, [activeCategoriesOnly, archivedCategoriesOnly]);

  const initialFormState = {
    name: '',
    description: '',
    price: '',
    originalPrice: '',
    promotionalTag: '',
    category: '',
    imageUrls: '',
    leadTimeDays: '0',
    inventoryEnabled: false,
    inventoryQuantity: '0'
  };

  const [productForm, setProductForm] = useState(initialFormState);
  const [productOptions, setProductOptions] = useState<ProductOption[]>([]);
  const [customizationGroups, setCustomizationGroups] = useState<CustomizationGroup[]>([]);
  const [newOption, setNewOption] = useState({ name: '', price: '' });

  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [productToDelete, setProductToDelete] = useState<Product | null>(null);
  const [categoryToDelete, setCategoryToDelete] = useState<string | null>(null);
  const [newCategory, setNewCategory] = useState('');
  const [productSearchQuery, setProductSearchQuery] = useState('');
  const [selectedCategoryFilter, setSelectedCategoryFilter] = useState('Todas');

  const [categoryTab, setCategoryTab] = useState<'active' | 'archived'>('active');
  const [productViewTab, setProductViewTab] = useState<'active' | 'inactive'>('active');
  const [selectedCategoryNames, setSelectedCategoryNames] = useState<string[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  useEffect(() => {
    if (productToDelete || categoryToDelete || isProductModalOpen) {
        document.body.style.overflow = 'hidden';
        return () => {
            document.body.style.overflow = 'auto';
        };
    }
  }, [productToDelete, categoryToDelete, isProductModalOpen]);

  useEffect(() => {
    if (productOptions.length > 0 && isProductModalOpen) {
        const minPrice = Math.min(...productOptions.map(o => o.price));
        setProductForm(prev => ({ ...prev, price: String(minPrice) }));
    }
  }, [productOptions, isProductModalOpen]);

  const handleProductFormChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as HTMLInputElement;
    if (type === 'checkbox') {
        setProductForm(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
    } else {
        setProductForm(prev => ({ ...prev, [name]: value }));
    }
  };

  const openAddProductModal = () => {
    setEditingProduct(null);
    setProductForm(initialFormState);
    setProductOptions([]);
    setCustomizationGroups([]);
    setIsProductModalOpen(true);
  };

  const handleEditClick = (product: Product) => {
    setEditingProduct(product);
    setProductForm({
        name: product.name,
        description: product.description,
        price: String(product.price),
        originalPrice: (product.originalPrice && product.originalPrice > 0) ? String(product.originalPrice) : '',
        promotionalTag: product.promotionalTag || '',
        category: product.category,
        imageUrls: product.imageUrls ? product.imageUrls.join('\n') : '',
        leadTimeDays: String(product.leadTimeDays || 0),
        inventoryEnabled: !!product.inventoryEnabled,
        inventoryQuantity: String(product.inventoryQuantity || 0)
    });
    setProductOptions(product.options || []);
    setCustomizationGroups(product.customizationGroups || []);
    setIsProductModalOpen(true);
  };

  const handleDuplicateClick = (product: Product) => {
    setProductForm({
        name: `${product.name} (Cópia)`,
        description: product.description,
        price: String(product.price),
        originalPrice: (product.originalPrice && product.originalPrice > 0) ? String(product.originalPrice) : '',
        promotionalTag: product.promotionalTag || '',
        category: product.category,
        imageUrls: product.imageUrls ? product.imageUrls.join('\n') : '',
        leadTimeDays: String(product.leadTimeDays || 0),
        inventoryEnabled: !!product.inventoryEnabled,
        inventoryQuantity: String(product.inventoryQuantity || 0)
    });
    setProductOptions(product.options || []);
    setCustomizationGroups(product.customizationGroups || []);
    setEditingProduct(null); 
    setIsProductModalOpen(true);
  };

  const confirmDelete = async () => {
    if (!productToDelete) return;
    setMessage(null);
    try {
        await onDeleteProduct(productToDelete.id);
        setMessage({ type: 'success', text: 'Produto apagado com sucesso!' });
    } catch (error) {
        setMessage({ type: 'error', text: 'Ocorreu um erro ao apagar o produto.' });
    } finally {
        setProductToDelete(null);
        setTimeout(() => setMessage(null), 5000);
    }
  };

  const closeProductModal = () => {
    setIsProductModalOpen(false);
    setEditingProduct(null);
    setProductForm(initialFormState);
    setProductOptions([]);
    setCustomizationGroups([]);
    setMessage(null);
  };

  const handleAddOption = () => {
      if (!newOption.name || !newOption.price) return;
      setProductOptions([...productOptions, { name: newOption.name, price: parseFloat(newOption.price) || 0 }]);
      setNewOption({ name: '', price: '' });
  };

  const handleRemoveOption = (index: number) => {
      setProductOptions(productOptions.filter((_, i) => i !== index));
  };

  const handleProductSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    setIsSubmitting(true);
    const imageUrlsArray = productForm.imageUrls.split('\n').map(url => url.trim()).filter(url => url);

    if (!productForm.name || !productForm.description || !productForm.category) {
        setMessage({ type: 'error', text: 'Por favor, preencha todos os campos obrigatórios.' });
        setIsSubmitting(false);
        return;
    }

    if (productOptions.length === 0 && !productForm.price) {
         setMessage({ type: 'error', text: 'Por favor, informe o preço base ou adicione opções.' });
         setIsSubmitting(false);
         return;
    }

    try {
      let effectivePrice = parseFloat(productForm.price) || 0;
      if (productOptions.length > 0) {
          effectivePrice = Math.min(...productOptions.map(o => o.price));
      }

      const productData: any = {
        name: productForm.name,
        description: productForm.description,
        price: effectivePrice,
        category: productForm.category,
        imageUrls: imageUrlsArray,
        leadTimeDays: parseInt(productForm.leadTimeDays, 10) || 0,
        options: productOptions,
        customizationGroups: customizationGroups,
        inventoryEnabled: productForm.inventoryEnabled,
        inventoryQuantity: parseInt(productForm.inventoryQuantity, 10) || 0,
      };

      if (editingProduct) {
          productData.id = editingProduct.id;
      }

      const origPrice = parseFloat(productForm.originalPrice);
      if (!isNaN(origPrice) && origPrice > 0) {
        productData.originalPrice = origPrice;
      } else {
        productData.originalPrice = null;
      }

      if (productForm.promotionalTag && productForm.promotionalTag.trim()) {
        productData.promotionalTag = productForm.promotionalTag.trim();
      } else {
        productData.promotionalTag = null;
      }

      if (editingProduct) {
        await onUpdateProduct(productData);
        setMessage({ type: 'success', text: 'Produto atualizado com sucesso!' });
      } else {
        await onAddProduct(productData);
        setMessage({ type: 'success', text: 'Produto cadastrado com sucesso!' });
      }

      setTimeout(() => {
          closeProductModal();
      }, 1000);
    } catch (error) {
        setMessage({ type: 'error', text: 'Ocorreu um erro.' });
        console.error(error);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleAddCategory = async () => {
    if (!newCategory.trim()) return;
    setIsSubmitting(true);
    try {
        await onAddCategory(newCategory);
        setNewCategory('');
        setMessage({ type: 'success', text: 'Categoria adicionada!' });
    } catch (e) {
        setMessage({ type: 'error', text: 'Erro ao adicionar categoria.' });
    } finally {
        setIsSubmitting(false);
        setTimeout(() => setMessage(null), 3000);
    }
  };

  const handleDeleteCategory = (categoryName: string) => {
      const isCategoryInUse = products.some(p => p.category === categoryName);
      if (isCategoryInUse) {
          alert(`A categoria "${categoryName}" está em uso por um ou mais produtos e não pode ser apagada.`);
          return;
      }
      setCategoryToDelete(categoryName);
  };

  const confirmDeleteCategory = async () => {
    if (!categoryToDelete) return;
    setIsSubmitting(true);
    try {
        await onDeleteCategory(categoryToDelete);
        setMessage({ type: 'success', text: 'Categoria apagada!' });
    } catch (e) {
        setMessage({ type: 'error', text: 'Erro ao apagar categoria.' });
    } finally {
        setIsSubmitting(false);
        setCategoryToDelete(null);
        setTimeout(() => setMessage(null), 3000);
    }
  };

  const handleSort = () => {
      if (dragItem.current === null || dragOverItem.current === null) return;
      const categoriesCopy = [...categories];

      const activeCats = categories.filter(c => !c.isArchived);
      const draggedCat = activeCats[dragItem.current];
      const targetCat = activeCats[dragOverItem.current];

      const realDragIdx = categories.findIndex(c => c.name === draggedCat.name);
      const realTargetIdx = categories.findIndex(c => c.name === targetCat.name);

      const item = categoriesCopy.splice(realDragIdx, 1)[0];
      categoriesCopy.splice(realTargetIdx, 0, item);

      dragItem.current = null;
      dragOverItem.current = null;
      onUpdateCategoryOrder(categoriesCopy);
  };

  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(productSearchQuery.toLowerCase());
    const isCategoryArchived = categories.some(c => c.name === p.category && c.isArchived);

    if (productViewTab === 'active' && isCategoryArchived) return false;
    if (productViewTab === 'inactive' && !isCategoryArchived) return false;

    const matchesCategory = selectedCategoryFilter === 'Todas' || p.category === selectedCategoryFilter;
    return matchesSearch && matchesCategory;
  });

  const inputStyles = "mt-1 block w-full px-4 py-2.5 bg-white border border-gray-300 rounded-lg shadow-sm placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-brand-primary sm:text-sm text-gray-900 outline-none transition-all";

  const archivedCategories = useMemo(() => categories.filter(c => c.isArchived), [categories]);
  const currentCategoryList = categoryTab === 'active' ? activeCategoriesOnly : archivedCategories;

  const toggleCategorySelection = (name: string) => {
    setSelectedCategoryNames(prev => {
      if (prev.includes(name)) {
        return prev.filter(n => n !== name);
      } else {
        return [...prev, name];
      }
    });
  };

  const handleArchiveSelected = async () => {
    if (selectedCategoryNames.length === 0) return;
    setIsSubmitting(true);
    try {
      await onToggleCategoriesArchive(selectedCategoryNames, categoryTab === 'active');
      setSelectedCategoryNames([]);
      setMessage({ type: 'success', text: `Categorias ${categoryTab === 'active' ? 'arquivadas' : 'restauradas'} com sucesso!` });
    } catch (e) {
      setMessage({ type: 'error', text: 'Erro ao atualizar categorias.' });
    } finally {
      setIsSubmitting(false);
      setTimeout(() => setMessage(null), 3000);
    }
  };

  const productCounts = useMemo(() => {
    const active = products.filter(p => !categories.find(c => c.name === p.category && c.isArchived)).length;
    const inactive = products.length - active;
    return { active, inactive };
  }, [products, categories]);

  return (
    <>
        {productToDelete && (
            <DeleteConfirmationModal 
                product={productToDelete}
                onCancel={() => setProductToDelete(null)}
                onConfirm={confirmDelete}
            />
        )}
        {categoryToDelete && (
            <DeleteCategoryConfirmationModal
                categoryName={categoryToDelete}
                onCancel={() => setCategoryToDelete(null)}
                onConfirm={confirmDeleteCategory}
            />
        )}

        {/* Modal de Produto (Cadastro/Edição) */}
        {isProductModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-hidden flex flex-col animate-slide-in-up no-scrollbar border border-gray-100">
                    <header className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/80">
                        <h2 className="text-xl font-black text-brand-text uppercase tracking-tight">{editingProduct ? 'Editar Produto' : 'Novo Produto'}</h2>
                        <button onClick={closeProductModal} className="p-2 hover:bg-gray-200 rounded-full transition-colors text-gray-500">
                            <CloseIcon className="w-6 h-6" />
                        </button>
                    </header>
                    <div className="flex-1 overflow-y-auto p-6 no-scrollbar bg-white">
                        <form onSubmit={handleProductSubmit} className="space-y-8">
                            <div className="space-y-6">
                                <div>
                                    <label htmlFor="name" className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-1">Nome do Produto</label>
                                    <input type="text" name="name" id="name" value={productForm.name} onChange={handleProductFormChange} className={inputStyles} required placeholder="Ex: Bolo de Chocolate Belga" />
                                </div>
                                <div>
                                    <label htmlFor="description" className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-1">Descrição</label>
                                    <textarea name="description" id="description" value={productForm.description} onChange={handleProductFormChange} rows={3} className={inputStyles} required placeholder="Descreva os detalhes deliciosos deste produto..."></textarea>
                                </div>
                                <div>
                                    <label htmlFor="imageUrls" className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-1">URLs da Imagem (uma por linha)</label>
                                    <textarea name="imageUrls" id="imageUrls" value={productForm.imageUrls} onChange={handleProductFormChange} rows={4} className={inputStyles} placeholder="https://exemplo.com/foto1.jpg&#10;https://exemplo.com/foto2.jpg"></textarea>
                                </div>

                                <div className="bg-gray-50/50 p-4 rounded-xl border border-gray-200">
                                    <label className="block text-xs font-black text-brand-primary uppercase tracking-widest mb-3">Variações (Tamanho/Peso)</label>
                                    <div className="space-y-2 mb-4">
                                        {productOptions.map((opt, index) => (
                                            <div key={index} className="flex items-center justify-between p-3 bg-white rounded-lg border border-gray-200 shadow-sm transition-all hover:border-brand-primary/50">
                                                <div className="min-w-0 pr-4 flex items-center gap-2">
                                                    <span className="font-bold text-brand-text">{opt.name}</span>
                                                    <span className="w-1 h-1 bg-gray-300 rounded-full"></span>
                                                    <span className="text-brand-primary font-black">{opt.price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                                                </div>
                                                <button type="button" onClick={() => handleRemoveOption(index)} className="p-1.5 text-gray-300 hover:text-red-600 transition-colors">
                                                    <TrashIcon className="w-5 h-5" />
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                    <div className="flex flex-col sm:flex-row gap-2 items-end">
                                        <div className="flex-grow w-full">
                                            <input type="text" placeholder="Nome (Ex: 500g)" value={newOption.name} onChange={(e) => setNewOption({ ...newOption, name: e.target.value })} className="block w-full px-3 py-2 bg-white border border-gray-300 rounded-lg sm:text-sm focus:ring-2 focus:ring-brand-primary outline-none" />
                                        </div>
                                        <div className="w-full sm:w-1/3">
                                            <input type="number" placeholder="Preço" value={newOption.price} onChange={(e) => setNewOption({ ...newOption, price: e.target.value })} className="block w-full px-3 py-2 bg-white border border-gray-300 rounded-lg sm:text-sm focus:ring-2 focus:ring-brand-primary outline-none" />
                                        </div>
                                        <button type="button" onClick={handleAddOption} className="px-5 py-2 bg-brand-primary text-white rounded-lg hover:bg-brand-primary-dark font-bold shadow-md transition-all active:scale-95">
                                            Add
                                        </button>
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                                    <div>
                                        <label htmlFor="price" className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-1">Preço de Venda (R$)</label>
                                        <input type="number" name="price" id="price" value={productForm.price} onChange={handleProductFormChange} className={`${inputStyles} ${productOptions.length > 0 ? 'bg-gray-100/50 cursor-not-allowed' : ''}`} step="0.01" min="0" required={productOptions.length === 0} readOnly={productOptions.length > 0} />
                                    </div>
                                    <div>
                                        <label htmlFor="originalPrice" className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-1">Preço Original (R$ - Opcional)</label>
                                        <input type="number" name="originalPrice" id="originalPrice" value={productForm.originalPrice} onChange={handleProductFormChange} className={inputStyles} step="0.01" min="0" placeholder="Sem promoção" />
                                    </div>
                                </div>

                                <div className="bg-blue-50/50 p-4 rounded-xl border border-blue-100">
                                    <div className="flex items-center gap-3 mb-3">
                                        <input 
                                            type="checkbox" 
                                            id="inventoryEnabled" 
                                            name="inventoryEnabled" 
                                            checked={!!productForm.inventoryEnabled} 
                                            onChange={handleProductFormChange}
                                            className="w-5 h-5 text-brand-primary border-gray-300 rounded-md focus:ring-brand-primary transition-all cursor-pointer"
                                        />
                                        <label htmlFor="inventoryEnabled" className="text-sm font-black text-brand-primary uppercase tracking-tight cursor-pointer">Habilitar Controle de Estoque</label>
                                    </div>
                                    {productForm.inventoryEnabled && (
                                        <div className="animate-fade-in pl-8">
                                            <label htmlFor="inventoryQuantity" className="block text-xs font-bold text-blue-600/70 uppercase mb-1">Quantidade Disponível</label>
                                            <input 
                                                type="number" 
                                                name="inventoryQuantity" 
                                                id="inventoryQuantity" 
                                                value={productForm.inventoryQuantity} 
                                                onChange={handleProductFormChange} 
                                                className="w-32 px-3 py-2 border border-blue-200 rounded-lg text-sm bg-white focus:ring-2 focus:ring-brand-primary outline-none transition-all font-black text-brand-primary" 
                                                min="0"
                                            />
                                        </div>
                                    )}
                                </div>

                                {/* Seção de Personalizações Suavizada */}
                                <CustomizationEditor groups={customizationGroups} onChange={setCustomizationGroups} />

                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                                    <div>
                                        <label htmlFor="category" className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-1">Categoria</label>
                                        <SearchableSelect options={sortedCategoriesForSelect} value={productForm.category} onChange={(val) => setProductForm(prev => ({ ...prev, category: val }))} placeholder="Selecione..." />
                                    </div>
                                    <div>
                                        <label htmlFor="promotionalTag" className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-1">Tag Promocional (Opcional)</label>
                                        <input type="text" name="promotionalTag" id="promotionalTag" value={productForm.promotionalTag} onChange={handleProductFormChange} className={inputStyles} placeholder="Ex: PROMO OURO" />
                                    </div>
                                </div>
                                <div>
                                    <label htmlFor="leadTimeDays" className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-1">Prazo de Produção (dias úteis)</label>
                                    <input type="number" name="leadTimeDays" id="leadTimeDays" value={productForm.leadTimeDays} onChange={handleProductFormChange} className={inputStyles} min="0" required />
                                    <p className="text-[10px] text-gray-400 mt-1">Coloque 0 se for pronta entrega.</p>
                                </div>
                            </div>

                            {message && (
                                <div className={`p-4 rounded-xl text-sm font-bold animate-fade-in ${message.type === 'success' ? 'bg-green-50 text-green-700 border border-green-100' : 'bg-red-50 text-red-700 border border-red-100'}`}>
                                    {message.text}
                                </div>
                            )}

                            <div className="pt-6 border-t border-gray-100 flex gap-4">
                                <button type="submit" disabled={isSubmitting} className="flex-grow py-4 px-4 rounded-xl text-white bg-brand-primary hover:bg-brand-primary-dark font-black uppercase tracking-widest shadow-xl transition-all active:scale-95 disabled:opacity-50 disabled:active:scale-100">
                                    {isSubmitting ? 'Processando...' : (editingProduct ? 'Salvar Alterações' : 'Publicar Produto')}
                                </button>
                                <button type="button" onClick={closeProductModal} className="px-8 py-4 border border-gray-200 rounded-xl font-bold text-gray-500 bg-white hover:bg-gray-50 transition-all">
                                    Fechar
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        )}

        <div className="space-y-8">
            <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
                <div className="relative flex-grow w-full">
                    <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                    <input
                        type="text"
                        value={productSearchQuery}
                        onChange={(e) => setProductSearchQuery(e.target.value)}
                        placeholder="Buscar produtos..."
                        className="w-full bg-white border border-gray-300 rounded-full py-2.5 pl-10 pr-4 text-gray-900 focus:outline-none focus:ring-2 focus:ring-brand-primary"
                    />
                </div>
                <button
                    onClick={openAddProductModal}
                    className="w-full sm:w-auto flex items-center justify-center gap-2 px-6 py-2.5 bg-brand-primary text-white font-bold rounded-lg hover:bg-brand-primary-dark transition-all shadow-md active:scale-95"
                >
                    <PlusIcon className="w-5 h-5" />
                    Novo Produto
                </button>
            </div>

            <section className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <div className="flex items-center justify-between mb-6">
                    <h3 className="text-lg font-bold text-brand-text flex items-center gap-2">
                        <span className="w-1.5 h-6 bg-brand-primary rounded-full"></span>
                        Gestão de Categorias
                    </h3>
                </div>

                <div className="flex border-b border-gray-200 mb-6">
                    <button
                        onClick={() => setCategoryTab('active')}
                        className={`px-4 py-2 text-sm font-bold border-b-2 transition-colors ${categoryTab === 'active' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}
                    >
                        Ativas ({activeCategoriesOnly.length})
                    </button>
                    <button
                        onClick={() => setCategoryTab('archived')}
                        className={`px-4 py-2 text-sm font-bold border-b-2 transition-colors ${categoryTab === 'archived' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}
                    >
                        Arquivadas ({archivedCategoriesOnly.length})
                    </button>
                </div>

                <div className="space-y-3">
                    <div className="flex gap-2 mb-4">
                        <input
                            type="text"
                            value={newCategory}
                            onChange={(e) => setNewCategory(e.target.value)}
                            placeholder="Nova categoria..."
                            className="flex-grow px-4 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-brand-primary outline-none"
                        />
                        <button
                            onClick={handleAddCategory}
                            disabled={isSubmitting || !newCategory.trim()}
                            className="px-6 py-2 bg-brand-primary text-white rounded-lg font-bold hover:bg-brand-primary-dark disabled:opacity-50"
                        >
                            Adicionar
                        </button>
                    </div>

                    {currentCategoryList.map((cat, index) => (
                        <div
                            key={cat.name}
                            draggable={categoryTab === 'active'}
                            onDragStart={() => (dragItem.current = index)}
                            onDragEnter={() => (dragOverItem.current = index)}
                            onDragEnd={handleSort}
                            onDragOver={(e) => e.preventDefault()}
                            className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg border border-gray-100 group"
                        >
                            {categoryTab === 'active' && <DragHandleIcon className="w-5 h-5 text-gray-300 cursor-grab active:cursor-grabbing" />}
                            <input
                                type="checkbox"
                                checked={selectedCategoryNames.includes(cat.name)}
                                onChange={() => toggleCategorySelection(cat.name)}
                                className="w-4 h-4 text-brand-primary border-gray-300 rounded focus:ring-brand-primary"
                            />
                            <span className="flex-grow font-medium text-gray-700">{cat.name}</span>
                            <button
                                onClick={() => handleDeleteCategory(cat.name)}
                                className="p-1.5 text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                            >
                                <TrashIcon className="w-4 h-4" />
                            </button>
                        </div>
                    ))}

                    {selectedCategoryNames.length > 0 && (
                        <div className="mt-4 pt-4 border-t border-gray-100">
                            <button
                                onClick={handleArchiveSelected}
                                className="px-6 py-2 bg-gray-800 text-white rounded-lg text-sm font-bold hover:bg-gray-900 transition-all"
                            >
                                {categoryTab === 'active' ? 'Arquivar Selecionadas' : 'Restaurar Selecionadas'}
                            </button>
                        </div>
                    )}
                </div>
            </section>

            <section className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <div className="flex items-center justify-between mb-6">
                    <h3 className="text-lg font-bold text-brand-text flex items-center gap-2">
                        <span className="w-1.5 h-6 bg-brand-accent rounded-full"></span>
                        Produtos ({filteredProducts.length})
                    </h3>
                </div>

                <div className="flex border-b border-gray-200 mb-6">
                    <button
                        onClick={() => setProductViewTab('active')}
                        className={`px-4 py-2 text-sm font-bold border-b-2 transition-colors ${productViewTab === 'active' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}
                    >
                        Ativos ({productCounts.active})
                    </button>
                    <button
                        onClick={() => setProductViewTab('inactive')}
                        className={`px-4 py-2 text-sm font-bold border-b-2 transition-colors ${productViewTab === 'inactive' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}
                    >
                        Inativos/Arquivados ({productCounts.inactive})
                    </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                    {filteredProducts.map(product => (
                        <div key={product.id} className="bg-gray-50 p-4 rounded-xl border border-gray-100 hover:border-brand-primary/30 transition-all group">
                            <div className="flex gap-4">
                                {product.imageUrls?.[0] ? (
                                    <img src={product.imageUrls[0]} alt={product.name} className="w-16 h-16 object-cover rounded-lg shadow-sm" />
                                ) : (
                                    <div className="w-16 h-16 bg-gray-200 rounded-lg flex items-center justify-center text-[10px] text-gray-400">Sem Imagem</div>
                                )}
                                <div className="min-w-0 flex-grow">
                                    <h4 className="font-bold text-brand-text truncate">{product.name}</h4>
                                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{product.category}</p>
                                    <p className="text-sm font-black text-brand-primary mt-1">{product.price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</p>
                                </div>
                            </div>
                            <div className="mt-4 pt-4 border-t border-gray-200 flex gap-2">
                                <button
                                    onClick={() => handleEditClick(product)}
                                    className="flex-1 py-2 bg-white border border-gray-200 rounded-lg text-xs font-bold text-gray-600 hover:bg-gray-50 hover:border-brand-primary transition-all"
                                >
                                    Editar
                                </button>
                                <button
                                    onClick={() => handleDuplicateClick(product)}
                                    className="p-2 bg-gray-100 rounded-lg text-gray-500 hover:bg-brand-secondary/30 transition-all"
                                    title="Duplicar"
                                >
                                    <CopyIcon className="w-4 h-4" />
                                </button>
                                <button
                                    onClick={() => setProductToDelete(product)}
                                    className="p-2 bg-gray-100 rounded-lg text-gray-400 hover:bg-red-50 hover:text-red-500 transition-all"
                                >
                                    <TrashIcon className="w-4 h-4" />
                                </button>
                            </div>
                        </div>
                    ))}
                </div>

                {filteredProducts.length === 0 && (
                    <div className="text-center py-12">
                        <p className="text-gray-400 italic">Nenhum produto encontrado nesta visualização.</p>
                    </div>
                )}
            </section>
        </div>
    </>
  );
};

export default ProductsView;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import type { Product, ProductOption, CustomizationGroup, CustomizationOption, SelectedCustomization } from '../types';
import { ArrowLeftIcon, PlusIcon, MinusIcon, ShoppingBagIcon, XIcon, CheckCircleIcon, ChevronLeftIcon, ChevronRightIcon } from './IconComponents';

interface ProductDetailModalProps {
  product: Product | null;
  onClose: () => void;
  onAddToCart: (product: Product, quantity: number, observations?: string, selectedOption?: ProductOption, selectedCustomizations?: SelectedCustomization[]) => void;
}

const ProductDetailModal: React.FC<ProductDetailModalProps> = ({ product, onClose, onAddToCart }) => {
  const [quantity, setQuantity] = useState(1);
  const [observations, setObservations] = useState('');
  const [isImageFullscreen, setIsImageFullscreen] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [selectedOption, setSelectedOption] = useState<ProductOption | null>(null);
  const [customSelections, setCustomSelections] = useState<Record<string, Record<string, number>>>({});

  // Estados para o efeito de deslize (Swipe)
  const [touchStartX, setTouchStartX] = useState<number | null>(null);
  const [dragOffset, setDragOffset] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (product) {
      setQuantity(1);
      setObservations('');
      setIsImageFullscreen(false);
      setCurrentImageIndex(0);
      setDragOffset(0);
      setCustomSelections({});
      if (product.options && product.options.length > 0) {
          setSelectedOption(product.options[0]);
      } else {
          setSelectedOption(null);
      }
    }
  }, [product]);

  const handleImageNavigation = useCallback((direction: 'next' | 'prev') => {
    if (!product) return;
    if (direction === 'next' && currentImageIndex < product.imageUrls.length - 1) {
      setCurrentImageIndex(prev => prev + 1);
    } else if (direction === 'prev' && currentImageIndex > 0) {
      setCurrentImageIndex(prev => prev - 1);
    }
    setDragOffset(0);
  }, [currentImageIndex, product]);

  // Lógica de arraste manual (Feel the slide)
  const handleTouchStart = (e: React.TouchEvent) => {
    setTouchStartX(e.touches[0].clientX);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (touchStartX === null) return;
    const currentX = e.touches[0].clientX;
    const diff = currentX - touchStartX;

    // Impedir arraste para fora dos limites
    const isAtFirst = currentImageIndex === 0 && diff > 0;
    const isAtLast = product && currentImageIndex === product.imageUrls.length - 1 && diff < 0;

    if (isAtFirst || isAtLast) {
      setDragOffset(diff * 0.2); // Resistência elástica
    } else {
      setDragOffset(diff);
    }
  };

  const handleTouchEnd = () => {
    if (touchStartX === null) return;

    const threshold = 80; // pixels para mudar de foto
    if (dragOffset < -threshold) {
      handleImageNavigation('next');
    } else if (dragOffset > threshold) {
      handleImageNavigation('prev');
    }

    setTouchStartX(null);
    setDragOffset(0);
  };

  const handleQuantityChange = (amount: number) => {
    setQuantity(prev => {
        const next = Math.max(1, prev + amount);
        if (product?.inventoryEnabled && next > (product.inventoryQuantity || 0)) {
            return prev;
        }
        return next;
    });
  };

  const { extraTotal, isAllGroupsValid, formattedCustomizations } = useMemo(() => {
    let total = 0;
    let allValid = true;
    const result: SelectedCustomization[] = [];

    if (!product?.customizationGroups) return { extraTotal: 0, isAllGroupsValid: true, formattedCustomizations: [] };

    for (const group of product.customizationGroups) {
      const groupSelections = customSelections[group.id] || {};
      const totalInGroup = (Object.values(groupSelections) as number[]).reduce((a: number, b: number) => a + b, 0);

      if (totalInGroup < group.min || totalInGroup > group.max) {
        allValid = false;
      }

      const items = [];
      for (const [optName, optQtyValue] of Object.entries(groupSelections)) {
        const optQty = optQtyValue as number;
        if (optQty > 0) {
          const opt = group.options.find(o => o.name === optName);
          if (opt) {
            total += (opt.priceExtra * optQty);
            items.push({ name: opt.name, quantity: optQty, priceExtra: opt.priceExtra });
          }
        }
      }
      if (items.length > 0) {
        result.push({ groupName: group.name, items });
      }
    }
    return { extraTotal: total, isAllGroupsValid: allValid, formattedCustomizations: result };
  }, [product, customSelections]);

  const handleCustomOptionChange = (group: CustomizationGroup, option: CustomizationOption, delta: number) => {
    setCustomSelections(prev => {
      const groupSelections: Record<string, number> = { ...(prev[group.id] || {}) };
      const currentQty = (groupSelections[option.name] as number) || 0;
      const totalInGroup = (Object.values(groupSelections) as number[]).reduce((a: number, b: number) => a + b, 0);

      if (group.type === 'single') {
        if (delta > 0) {
          return { ...prev, [group.id]: { [option.name]: 1 } };
        } else {
          return { ...prev, [group.id]: {} };
        }
      }

      const newQty = Math.max(0, currentQty + delta);
      if (delta > 0 && totalInGroup >= group.max) return prev;

      return {
        ...prev,
        [group.id]: {
          ...groupSelections,
          [option.name]: newQty
        }
      };
    });
  };

  const handleAddToCartClick = () => {
    if (product) {
        if (product.options && product.options.length > 0 && !selectedOption) {
            alert("Por favor, selecione uma opção.");
            return;
        }
        if (!isAllGroupsValid) {
            alert("Por favor, preencha as opções obrigatórias.");
            return;
        }
      onAddToCart(product, quantity, observations, selectedOption || undefined, formattedCustomizations);
    }
  };

  const formatPrice = (price: number) => {
    return price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  if (!product) return null;

  const basePrice = selectedOption ? selectedOption.price : product.price;
  const totalPrice = (basePrice + extraTotal) * quantity;
  const isSoldOut = product.inventoryEnabled && (product.inventoryQuantity || 0) <= 0;

  return (
    <>
      {/* MODO TELA CHEIA (FULLSCREEN) COM CARROSSEL INTERATIVO */}
      {isImageFullscreen && (
        <div 
          className="fixed inset-0 bg-black z-[70] flex items-center justify-center select-none"
          onTouchStart={handleTouchStart}
          onTouchMove={handleTouchMove}
          onTouchEnd={handleTouchEnd}
        >
            <button 
              onClick={() => setIsImageFullscreen(false)} 
              className="absolute top-6 right-6 text-white p-3 bg-white/10 rounded-full hover:bg-white/20 transition-all z-[80]"
            >
              <XIcon className="w-8 h-8"/>
            </button>

            <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
               {/* Setas Condicionais no Fullscreen */}
               {currentImageIndex > 0 && (
                <button 
                  onClick={(e) => { e.stopPropagation(); handleImageNavigation('prev'); }}
                  className="absolute left-4 top-1/2 -translate-y-1/2 p-4 bg-white/10 text-white rounded-full hover:bg-white/20 z-[80] hidden sm:block"
                >
                  <ChevronLeftIcon className="w-10 h-10" />
                </button>
               )}

               <div 
                  className="flex transition-transform duration-300 ease-out h-full w-full items-center"
                  style={{ 
                    transform: `translateX(calc(-${currentImageIndex * 100}% + ${dragOffset}px))`,
                    transition: touchStartX !== null ? 'none' : 'transform 0.3s ease-out'
                  }}
               >
                 {product.imageUrls.map((url, idx) => (
                   <div key={idx} className="min-w-full h-full flex items-center justify-center p-4">
                      <img 
                        src={url} 
                        className="max-h-full max-w-full object-contain rounded shadow-2xl" 
                        alt={`${product.name} ${idx + 1}`}
                      />
                   </div>
                 ))}
               </div>

               {currentImageIndex < product.imageUrls.length - 1 && (
                <button 
                  onClick={(e) => { e.stopPropagation(); handleImageNavigation('next'); }}
                  className="absolute right-4 top-1/2 -translate-y-1/2 p-4 bg-white/10 text-white rounded-full hover:bg-white/20 z-[80] hidden sm:block"
                >
                  <ChevronRightIcon className="w-10 h-10" />
                </button>
               )}
            </div>

            {/* Contador de Fotos */}
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 bg-black/50 text-white px-4 py-1.5 rounded-full text-sm font-bold backdrop-blur-sm">
               {currentImageIndex + 1} / {product.imageUrls.length}
            </div>
        </div>
      )}

      <div className="fixed inset-0 z-50 bg-white flex flex-col animate-slide-in-up overflow-y-auto no-scrollbar">
        <style>{`.animate-slide-in-up { animation: slideInUp 0.3s ease-out; } @keyframes slideInUp { from { transform: translateY(100%); } to { transform: translateY(0); } }`}</style>

        <div className="flex-1 pb-32"> 
          <div className="max-w-2xl mx-auto w-full relative">

            {/* ÁREA DA IMAGEM COM SWIPE (TOUCHMOVE) */}
            {product.imageUrls && product.imageUrls.length > 0 ? (
              <div 
                className="relative aspect-square sm:aspect-video w-full bg-gray-100 overflow-hidden"
                onTouchStart={handleTouchStart}
                onTouchMove={handleTouchMove}
                onTouchEnd={handleTouchEnd}
              >
                  <div 
                    className="flex h-full transition-transform duration-300 ease-out"
                    style={{ 
                      transform: `translateX(calc(-${currentImageIndex * 100}% + ${dragOffset}px))`,
                      transition: touchStartX !== null ? 'none' : 'transform 0.3s ease-out'
                    }}
                  >
                    {product.imageUrls.map((url, idx) => (
                      <img 
                        key={idx}
                        src={url} 
                        alt={product.name} 
                        className={`min-w-full h-full object-cover cursor-pointer ${isSoldOut ? 'grayscale' : ''}`} 
                        onClick={() => setIsImageFullscreen(true)}
                      />
                    ))}
                  </div>

                  {/* Seta de Voltar (Sempre visível sobre a imagem) */}
                  <button 
                    onClick={onClose} 
                    className="absolute top-4 left-4 p-2 bg-white/90 rounded-full shadow-lg text-gray-900 hover:bg-white transition-all active:scale-90 z-20"
                    aria-label="Voltar"
                  >
                    <ArrowLeftIcon className="w-6 h-6" />
                  </button>

                  {/* Setas de Navegação Inteligentes (Condicionais) */}
                  {product.imageUrls.length > 1 && (
                    <>
                      {currentImageIndex > 0 && (
                        <button 
                          onClick={() => handleImageNavigation('prev')}
                          className="absolute left-2 top-1/2 -translate-y-1/2 p-2 bg-white/30 backdrop-blur-sm text-gray-900 rounded-full transition-all z-10 hidden sm:block shadow-md"
                        >
                          <ChevronLeftIcon className="w-6 h-6" />
                        </button>
                      )}
                      {currentImageIndex < product.imageUrls.length - 1 && (
                        <button 
                          onClick={() => handleImageNavigation('next')}
                          className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-white/30 backdrop-blur-sm text-gray-900 rounded-full transition-all z-10 hidden sm:block shadow-md"
                        >
                          <ChevronRightIcon className="w-6 h-6" />
                        </button>
                      )}

                      {/* Indicadores de progresso */}
                      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-2 z-10">
                        {product.imageUrls.map((_, idx) => (
                          <div 
                            key={idx} 
                            className={`w-1.5 h-1.5 rounded-full transition-all duration-300 ${idx === currentImageIndex ? 'bg-white scale-150' : 'bg-white/40'}`}
                          />
                        ))}
                      </div>
                    </>
                  )}

                  {isSoldOut && (
                    <div className="absolute inset-0 bg-black/40 flex items-center justify-center z-10">
                      <span className="bg-red-600 text-white font-bold px-6 py-2 rounded uppercase tracking-widest">Esgotado</span>
                    </div>
                  )}
              </div>
            ) : (
               <div className="p-4 border-b flex items-center sticky top-0 bg-white z-20">
                  <button onClick={onClose} className="p-2 -ml-2 rounded-full hover:bg-gray-100 text-gray-900"><ArrowLeftIcon className="w-6 h-6"/></button>
                  <h1 className="ml-2 text-lg font-bold text-brand-text truncate">{product.name}</h1>
              </div>
            )}

            <div className="p-6 space-y-8">
                <div>
                    <h1 className="text-2xl font-bold text-brand-text">{product.name}</h1>
                    <p className="text-brand-text-light text-base mt-2 leading-relaxed">{product.description}</p>
                </div>

                {/* Variações de Tamanho/Opção */}
                {product.options && product.options.length > 0 && !isSoldOut && (
                    <div className="space-y-4">
                        <h3 className="text-base font-bold text-brand-text border-l-4 border-brand-primary pl-3">Escolha uma opção</h3>
                        <div className="grid gap-3">
                            {product.options.map((option, index) => (
                                <button key={index} onClick={() => setSelectedOption(option)}
                                    className={`flex items-center justify-between p-4 rounded-xl border transition-all ${selectedOption?.name === option.name ? 'border-brand-primary bg-brand-secondary/20 ring-1 ring-brand-primary shadow-sm' : 'border-gray-200'}`}
                                >
                                    <span className="font-bold text-brand-text">{option.name}</span>
                                    <span className="font-bold text-brand-primary">{formatPrice(option.price)}</span>
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* Grupos de Personalização */}
                {product.customizationGroups?.map((group) => {
                  const groupSelections = customSelections[group.id] || {};
                  const totalInGroup = (Object.values(groupSelections) as number[]).reduce((a: number, b: number) => a + b, 0);
                  const isValid = totalInGroup >= group.min && totalInGroup <= group.max;

                  return (
                    <div key={group.id} className="pt-6 border-t border-gray-100 space-y-4">
                        <div className="flex justify-between items-start">
                            <div>
                                <h3 className="text-base font-bold text-brand-text">{group.name}</h3>
                                <p className="text-xs text-gray-400">
                                    {group.min === group.max ? `Escolha ${group.min}` : `Escolha de ${group.min} a ${group.max}`}
                                </p>
                            </div>
                            {isValid ? (
                                <CheckCircleIcon className="w-5 h-5 text-green-500" />
                            ) : (
                                <span className="text-[10px] font-black bg-amber-100 text-amber-700 px-2 py-0.5 rounded uppercase">Obrigatório</span>
                            )}
                        </div>

                        <div className="space-y-3">
                            {group.options.map((opt) => {
                                const qty = (groupSelections[opt.name] as number) || 0;
                                return (
                                    <div key={opt.name} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${qty > 0 ? 'border-brand-primary/50 bg-brand-secondary/10' : 'border-gray-50'}`}>
                                        <div className="flex-grow pr-4">
                                            <p className="text-sm font-bold text-brand-text">{opt.name}</p>
                                            {opt.priceExtra > 0 && <p className="text-xs text-brand-accent font-bold">+{formatPrice(opt.priceExtra)}</p>}
                                        </div>

                                        <div className="flex items-center bg-white rounded-lg border border-gray-100 shadow-sm">
                                            <button onClick={() => handleCustomOptionChange(group, opt, -1)} className={`p-2 transition-opacity ${qty === 0 ? 'opacity-20 text-gray-300' : 'text-gray-900'}`}><MinusIcon className="w-4 h-4"/></button>
                                            <span className="px-3 text-sm font-black w-8 text-center text-brand-text">{qty}</span>
                                            <button onClick={() => handleCustomOptionChange(group, opt, 1)} className={`p-2 transition-opacity ${(totalInGroup >= group.max && group.type !== 'single') ? 'opacity-20 text-gray-300' : 'text-brand-primary'}`}><PlusIcon className="w-4 h-4"/></button>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                  );
                })}

                {!isSoldOut && (
                    <div className="pt-6 border-t border-gray-100">
                        <label className="block text-sm font-bold text-brand-text mb-2">Observações</label>
                        <textarea 
                            value={observations} 
                            onChange={(e) => setObservations(e.target.value)} 
                            rows={3} 
                            placeholder="Algum pedido especial? (Ex: Sem amendoim)"
                            className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-brand-primary outline-none text-gray-900 placeholder-gray-400 shadow-sm"
                        />
                    </div>
                )}
            </div>
          </div>
        </div>

        {/* Barra de Ação Inferior */}
        {!isSoldOut && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 p-4 pb-safe shadow-2xl z-30">
                <div className="max-w-2xl mx-auto flex items-center gap-4">
                    <div className="flex items-center bg-gray-100 rounded-full p-1 border border-gray-200">
                      <button onClick={() => handleQuantityChange(-1)} disabled={quantity === 1} className="p-3 disabled:opacity-30 text-gray-900"><MinusIcon className="w-5 h-5" /></button>
                      <span className="px-4 text-xl font-black w-12 text-center text-brand-text">{quantity}</span>
                      <button onClick={() => handleQuantityChange(1)} className="p-3 text-gray-900"><PlusIcon className="w-5 h-5" /></button>
                    </div>

                    <button onClick={handleAddToCartClick} disabled={!isAllGroupsValid}
                      className="flex-grow bg-brand-primary text-white font-black py-4 px-6 rounded-2xl flex items-center justify-between shadow-lg hover:brightness-105 active:scale-95 transition-all disabled:opacity-50"
                    >
                        <span className="flex items-center gap-2">
                          <ShoppingBagIcon className="w-6 h-6 text-brand-secondary" /> 
                          Adicionar
                        </span>
                        <span className="text-lg">{formatPrice(totalPrice)}</span>
                    </button>
                </div>
            </div>
        )}
      </div>
    </>
  );
};

