// Component for editing customization groups and their options
const CustomizationEditor: React.FC<{
    groups: CustomizationGroup[];
    onChange: (groups: CustomizationGroup[]) => void;
}> = ({ groups, onChange }) => {
    const addGroup = () => {
        const newGroup: CustomizationGroup = {
            id: `group-${Date.now()}`,
            name: '',
            min: 0,
            max: 1,
            type: 'single',
            options: []
        };
        onChange([...groups, newGroup]);
    };

    const updateGroup = (id: string, data: Partial<CustomizationGroup>) => {
        onChange(groups.map(g => g.id === id ? { ...g, ...data } : g));
    };

    const removeGroup = (id: string) => {
        onChange(groups.filter(g => g.id !== id));
    };

    const addOptionToGroup = (groupId: string) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                return {
                    ...g,
                    options: [...g.options, { name: '', priceExtra: 0 }]
                };
            }
            return g;
        }));
    };

    const updateOptionInGroup = (groupId: string, optIndex: number, data: Partial<CustomizationOption>) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                const newOpts = [...g.options];
                newOpts[optIndex] = { ...newOpts[optIndex], ...data };
                return { ...g, options: newOpts };
            }
            return g;
        }));
    };

    const removeOptionFromGroup = (groupId: string, optIndex: number) => {
        onChange(groups.map(g => {
            if (g.id === groupId) {
                return { ...g, options: g.options.filter((_, i) => i !== optIndex) };
            }
            return g;
        }));
    };

    return (
        <div className="bg-blue-50/30 p-5 rounded-2xl border border-blue-100/50 mt-8 shadow-inner">
            <div className="flex justify-between items-center mb-6">
                <div className="flex flex-col">
                    <h4 className="text-xs font-black text-brand-primary uppercase tracking-widest">Personalizações</h4>
                    <span className="text-[10px] text-gray-400 font-bold">ADICIONAIS E OPÇÕES DO PRODUTO</span>
                </div>
                <button 
                  type="button" 
                  onClick={addGroup} 
                  className="text-xs font-bold text-white bg-brand-primary px-4 py-2 rounded-lg hover:bg-brand-primary-dark transition-all shadow-sm active:scale-95"
                >
                    + Novo Grupo
                </button>
            </div>

            <div className="space-y-6">
                {groups.map((group) => (
                    <div key={group.id} className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm relative group/card hover:border-brand-primary/20 transition-colors">
                        <button 
                          type="button" 
                          onClick={() => removeGroup(group.id)} 
                          className="absolute top-3 right-3 text-gray-300 hover:text-red-500 transition-colors p-1"
                          title="Remover Grupo"
                        >
                            <TrashIcon className="w-5 h-5" />
                        </button>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-5 pr-8">
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1 tracking-tight">Nome do Grupo (Ex: Escolha o sabor)</label>
                                <input 
                                  type="text" 
                                  value={group.name} 
                                  onChange={e => updateGroup(group.id, { name: e.target.value })} 
                                  placeholder="Título do grupo" 
                                  className="w-full px-3 py-2 border rounded-lg text-sm text-gray-900 bg-gray-50/50 focus:bg-white focus:ring-2 focus:ring-brand-primary outline-none transition-all" 
                                />
                            </div>
                            <div className="flex gap-3">
                                <div className="flex-1">
                                    <label className="block text-[10px] font-black text-gray-400 uppercase mb-1 tracking-tight">Mín</label>
                                    <input type="number" min="0" value={group.min} onChange={e => updateGroup(group.id, { min: parseInt(e.target.value) || 0 })} className="w-full px-3 py-2 border rounded-lg text-sm text-gray-900 bg-gray-50/50 focus:bg-white focus:ring-2 focus:ring-brand-primary outline-none transition-all" />
                                </div>
                                <div className="flex-1">
                                    <label className="block text-[10px] font-black text-gray-400 uppercase mb-1 tracking-tight">Máx</label>
                                    <input type="number" min="1" value={group.max} onChange={e => updateGroup(group.id, { max: parseInt(e.target.value) || 1, type: parseInt(e.target.value) > 1 ? 'counter' : 'single' })} className="w-full px-3 py-2 border rounded-lg text-sm text-gray-900 bg-gray-50/50 focus:bg-white focus:ring-2 focus:ring-brand-primary outline-none transition-all" />
                                </div>
                            </div>
                        </div>

                        <div className="space-y-2">
                            <p className="text-[10px] font-bold text-gray-400 uppercase mb-2">Opções Disponíveis</p>
                            {group.options.map((opt, idx) => (
                                <div key={idx} className="flex gap-2 items-center bg-gray-50/40 p-2 rounded-lg border border-gray-100 hover:bg-white transition-colors">
                                    <input 
                                      type="text" 
                                      value={opt.name} 
                                      onChange={e => updateOptionInGroup(group.id, idx, { name: e.target.value })} 
                                      placeholder="Nome da opção" 
                                      className="flex-grow px-3 py-1.5 text-sm border border-gray-200 rounded-md bg-white text-gray-900 outline-none focus:ring-1 focus:ring-brand-primary" 
                                    />
                                    <div className="relative w-28">
                                        <span className="absolute left-2 top-1/2 -translate-y-1/2 text-[10px] text-gray-400 font-bold">R$</span>
                                        <input 
                                          type="number" 
                                          step="0.01" 
                                          value={opt.priceExtra} 
                                          onChange={e => updateOptionInGroup(group.id, idx, { priceExtra: parseFloat(e.target.value) || 0 })} 
                                          className="w-full pl-7 pr-2 py-1.5 text-sm border border-gray-200 rounded-md bg-white text-brand-primary font-black outline-none focus:ring-1 focus:ring-brand-primary" 
                                        />
                                    </div>
                                    <button 
                                      type="button" 
                                      onClick={() => removeOptionFromGroup(group.id, idx)} 
                                      className="p-1.5 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-md transition-all"
                                    >
                                        <TrashIcon className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                            <button 
                              type="button" 
                              onClick={() => addOptionToGroup(group.id)} 
                              className="w-full py-3 border-2 border-dashed border-gray-200 rounded-xl text-xs font-bold text-gray-400 hover:border-brand-primary hover:text-brand-primary hover:bg-brand-primary/5 transition-all mt-2"
                            >
                                + Adicionar Opção ao Grupo
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

// Dropdown selector with search functionality for categories
const SearchableSelect: React.FC<{
    options: CategoryMetadata[];
    value: string;
    onChange: (value: string) => void;
    placeholder: string;
}> = ({ options, value, onChange, placeholder }) => {
    const [isOpen, setIsOpen] = useState(false);
    const [search, setSearch] = useState('');
    const containerRef = useRef<HTMLDivElement>(null);

    const filteredOptions = useMemo(() => {
        return options.filter(opt => 
            opt.name.toLowerCase().includes(search.toLowerCase())
        );
    }, [options, search]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const selectedCategory = options.find(o => o.name === value);

    return (
        <div className="relative mt-1" ref={containerRef}>
            <button
                type="button"
                onClick={() => setIsOpen(!isOpen)}
                className="relative w-full bg-white border border-gray-300 rounded-lg shadow-sm pl-3 pr-10 py-2.5 text-left cursor-default focus:outline-none focus:ring-2 focus:ring-brand-primary sm:text-sm"
            >
                <span className="block truncate text-gray-900">
                    {selectedCategory ? (
                        <span className="flex items-center gap-2">
                            {selectedCategory.isArchived ? '📦' : '📂'} {selectedCategory.name}
                        </span>
                    ) : (
                        <span className="text-gray-400">{placeholder}</span>
                    )}
                </span>
                <span className="absolute inset-y-0 right-0 flex items-center pr-2 pointer-events-none">
                    <svg className="h-5 w-5 text-gray-400 transform transition-transform duration-200" style={{ transform: isOpen ? 'rotate(-90deg)' : 'rotate(90deg)' }} viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
                    </svg>
                </span>
            </button>

            {isOpen && (
                <div className="absolute z-50 mt-1 w-full bg-white shadow-2xl max-h-60 rounded-xl py-1 text-base ring-1 ring-black/5 overflow-auto focus:outline-none sm:text-sm border border-gray-100">
                    <div className="sticky top-0 z-10 bg-white px-2 py-2 border-b border-gray-100">
                        <div className="relative">
                            <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
                            <input
                                type="text"
                                className="block w-full pl-9 pr-3 py-2 border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-brand-primary outline-none"
                                placeholder="Pesquisar categoria..."
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                                onClick={(e) => e.stopPropagation()}
                                autoFocus
                            />
                        </div>
                    </div>
                    <ul className="max-h-48 overflow-y-auto p-1">
                        {filteredOptions.length > 0 ? (
                            filteredOptions.map((opt) => (
                                <li
                                    key={opt.name}
                                    onClick={() => {
                                        onChange(opt.name);
                                        setIsOpen(false);
                                        setSearch('');
                                    }}
                                    className={`cursor-pointer select-none relative py-2.5 pl-3 pr-9 rounded-lg hover:bg-brand-secondary/30 transition-colors ${
                                        value === opt.name ? 'bg-brand-secondary/50 text-brand-primary font-bold' : 'text-gray-900'
                                    }`}
                                >
                                    <div className="flex items-center gap-2">
                                        <span className="text-xs">{opt.isArchived ? '📦' : '📂'}</span>
                                        <span className="block truncate">{opt.name}</span>
                                        {opt.isArchived && <span className="text-[10px] text-gray-400 uppercase font-black tracking-tighter ml-auto">(Arquivada)</span>}
                                    </div>
                                    {value === opt.name && (
                                        <span className="absolute inset-y-0 right-0 flex items-center pr-4 text-brand-primary">
                                            <svg className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                                <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                                            </svg>
                                        </span>
                                    )}
                                </li>
                            ))
                        ) : (
                            <li className="py-4 text-center text-gray-500 text-sm">Nenhuma categoria encontrada</li>
                        )}
                    </ul>
                </div>
            )}
        </div>
    );
};

