                <div className="flex border-b border-gray-200 mb-6">
                    <button
                        onClick={() => setCategoryTab('active')}
                        className={`px-4 py-2 text-sm font-bold border-b-2 transition-colors ${categoryTab === 'active' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}
                    >
                        Ativas ({activeCategoriesOnly.length})
                    </button>
                    <button
                        onClick={() => setCategoryTab('archived')}
                        className={`px-4 py-2 text-sm font-bold border-b-2 transition-colors ${categoryTab === 'archived' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}
                    >
                        Arquivadas ({archivedCategoriesOnly.length})
                    </button>
                </div>

                <div className="space-y-3">
                    <div className="flex gap-2 mb-4">
                        <input
                            type="text"
                            value={newCategory}
                            onChange={(e) => setNewCategory(e.target.value)}
                            placeholder="Nova categoria..."
                            className="flex-grow px-4 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-brand-primary outline-none"
                        />
                        <button
                            onClick={handleAddCategory}
                            disabled={isSubmitting || !newCategory.trim()}
                            className="px-6 py-2 bg-brand-primary text-white rounded-lg font-bold hover:bg-brand-primary-dark disabled:opacity-50"
                        >
                            Adicionar
                        </button>
                    </div>

                    {currentCategoryList.map((cat, index) => (
                        <div
                            key={cat.name}
                            draggable={categoryTab === 'active'}
                            onDragStart={() => (dragItem.current = index)}
                            onDragEnter={() => (dragOverItem.current = index)}
                            onDragEnd={handleSort}
                            onDragOver={(e) => e.preventDefault()}
                            className="flex items-center gap-3 p-3 bg-gray-50/50 rounded-lg border border-gray-100 group"
                        >
                            {categoryTab === 'active' && <DragHandleIcon className="w-5 h-5 text-gray-300 cursor-grab active:cursor-grabbing" />}
                            <input
                                type="checkbox"
                                checked={selectedCategoryNames.includes(cat.name)}
                                onChange={() => toggleCategorySelection(cat.name)}
                                className="w-4 h-4 text-brand-primary border-gray-300 rounded focus:ring-brand-primary"
                            />
                            <span className="flex-grow font-medium text-gray-700">{cat.name}</span>
                            <button
                                onClick={() => handleDeleteCategory(cat.name)}
                                className="p-1.5 text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                            >
                                <TrashIcon className="w-4 h-4" />
                            </button>
                        </div>
                    ))}

                    {selectedCategoryNames.length > 0 && (
                        <div className="mt-4 pt-4 border-t border-gray-100">
                            <button
                                onClick={handleArchiveSelected}
                                className="px-6 py-2 bg-gray-800 text-white rounded-lg text-sm font-bold hover:bg-gray-900 transition-all"
                            >
                                {categoryTab === 'active' ? 'Arquivar Selecionadas' : 'Restaurar Selecionadas'}
                            </button>
                        </div>
                    )}
                </div>
            </section>

            <section className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <div className="flex items-center justify-between mb-6">
                    <h3 className="text-lg font-bold text-brand-text flex items-center gap-2">
                        <span className="w-1.5 h-6 bg-brand-accent rounded-full"></span>
                        Produtos ({filteredProducts.length})
                    </h3>
                </div>

                <div className="flex border-b border-gray-200 mb-6">
                    <button
                        onClick={() => setProductViewTab('active')}
                        className={`px-4 py-2 text-sm font-bold border-b-2 transition-colors ${productViewTab === 'active' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}
                    >
                        Ativos ({productCounts.active})
                    </button>
                    <button
                        onClick={() => setProductViewTab('inactive')}
                        className={`px-4 py-2 text-sm font-bold border-b-2 transition-colors ${productViewTab === 'inactive' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-gray-400'}`}
                    >
                        Inativos/Arquivados ({productCounts.inactive})
                    </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                    {filteredProducts.map(product => (
                        <div key={product.id} className="bg-gray-50/50 p-4 rounded-xl border border-gray-100 hover:border-brand-primary/30 transition-all group">
                            <div className="flex gap-4">
                                {product.imageUrls?.[0] ? (
                                    <img src={product.imageUrls[0]} alt={product.name} className="w-16 h-16 object-cover rounded-lg shadow-sm" />
                                ) : (
                                    <div className="w-16 h-16 bg-gray-200 rounded-lg flex items-center justify-center text-[10px] text-gray-400">Sem Imagem</div>
                                )}
                                <div className="min-w-0 flex-grow">
                                    <h4 className="font-bold text-brand-text truncate">{product.name}</h4>
                                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{product.category}</p>
                                    <p className="text-sm font-black text-brand-primary mt-1">{product.price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</p>
                                </div>
                            </div>
                            <div className="mt-4 pt-4 border-t border-gray-200 flex gap-2">
                                <button
                                    onClick={() => handleEditClick(product)}
                                    className="flex-1 py-2 bg-white border border-gray-200 rounded-lg text-xs font-bold text-gray-600 hover:bg-gray-50 hover:border-brand-primary transition-all shadow-sm"
                                >
                                    Editar
                                </button>
                                <button
                                    onClick={() => handleDuplicateClick(product)}
                                    className="p-2 bg-gray-100 rounded-lg text-gray-500 hover:bg-brand-secondary/30 transition-all"
                                    title="Duplicar"
                                >
                                    <CopyIcon className="w-4 h-4" />
